window.KHO_DATA_L1_AMNHAC = [
{"lop":1,"mon":"Âm nhạc","tuan":1,"tiet":1,"bai":"Chủ đề 1: Âm thanh kì diệu — Học hát: Vào rừng hoa (Việt Anh)","yccd":"1. Năng lực âm nhạc\n- Nhớ tên bài hát, tên tác giả; hát rõ lời, đúng giai điệu bài Vào rừng hoa.\n- Bước đầu cảm nhận tính chất vui tươi, trong sáng của bài hát.\n- Biết hát kết hợp vỗ tay theo phách.\n2. Năng lực chung\n- Tự chủ và tự học: mạnh dạn hát trước lớp, tự tập lại câu hát chưa thuộc.\n- Giao tiếp và hợp tác: hát hòa giọng, hát nối tiếp cùng các bạn.\n3. Phẩm chất\n- Yêu thiên nhiên, biết giữ gìn cảnh đẹp xung quanh.\n4. Tích hợp\n- Năng lực số 3.3 CB1a: Xác định được các quy tắc đơn giản về bản quyền và giấy phép áp dụng cho dữ liệu, thông tin và nội dung số: HS nói được tên bài hát cùng tên tác giả Việt Anh.","dodung":"- Giáo viên: đàn phím điện tử (hoặc nhạc đệm), loa, tranh cảnh rừng hoa, thanh phách, thiết bị trình chiếu mở học liệu số.\n- Học sinh: SGK Âm nhạc 1, thanh phách (hoặc nhạc cụ gõ tự tạo).","hoatdong":[{"ten":"1. Khởi động","gv":"- GV cho HS xem tranh rừng hoa nhiều màu sắc, hỏi: Trong tranh có gì? Các em có muốn vào rừng hoa dạo chơi không?\n- GV cho HS đứng tại chỗ, vươn vai, hít thở sâu và bắt chước tiếng chim hót \"chíp chíp\" cao – thấp theo tay GV.\n- GV giới thiệu tên bài hát Vào rừng hoa và tên tác giả Việt Anh.","hs":"- HS quan sát, trả lời: có hoa, có bướm, có cây xanh...\n- HS đứng dậy vận động, bắt chước tiếng chim theo tay GV.\n- HS nhắc lại tên bài hát, tên tác giả."},{"ten":"2. Khám phá — Học hát: Vào rừng hoa","gv":"- GV mở bản hát mẫu từ học liệu số 1–2 lần, hỏi: Bài hát nhanh hay chậm, vui hay buồn?\n- GV chia bài thành các câu ngắn (khoảng 4 câu), đọc lời từng câu theo tiết tấu, HS đọc theo.\n- GV đàn giai điệu và hát mẫu từng câu 2 lần rồi bắt nhịp cho HS hát; dạy nối câu 1 với câu 2, câu 3 với câu 4, rồi ghép cả bài.\n- GV chú ý sửa những tiếng hát ngân, luyến; nhắc HS hát nhẹ nhàng, tươi vui.","hs":"- HS nghe, trả lời: bài hát vui, nhanh vừa.\n- HS đọc lời ca từng câu theo GV.\n- HS hát từng câu theo tiếng đàn, hát nối các câu, hát cả bài.\n- HS sửa chỗ hát chưa đúng theo hướng dẫn."},{"ten":"3. Luyện tập","gv":"- GV mở nhạc đệm, cho cả lớp hát 2 lần; sau đó hát theo dãy, theo tổ.\n- GV làm mẫu vỗ tay theo phách (vỗ đều, mỗi phách một tiếng) rồi cho HS hát kết hợp vỗ tay.\n- GV cho HS dùng thanh phách gõ theo phách thay vỗ tay; nhóm hát – nhóm gõ rồi đổi vai.","hs":"- HS hát cả bài theo nhạc đệm; hát theo dãy, tổ.\n- HS quan sát, vỗ tay theo phách rồi vừa hát vừa vỗ tay.\n- HS gõ thanh phách theo phách, đổi vai hát – gõ."},{"ten":"4. Vận dụng","gv":"- GV mời 2–3 nhóm (3–4 HS) lên hát trước lớp kết hợp vỗ tay theo phách; GV khen ngợi, nhận xét ngắn.\n- GV hỏi: Bài hát nói về điều gì? Khi vào rừng hoa các em cần làm gì để giữ gìn cảnh đẹp?\n- GV dặn HS về nhà hát cho người thân nghe.","hs":"- HS xung phong biểu diễn, các bạn khác vỗ tay cổ vũ.\n- HS trả lời: không hái hoa, bẻ cành...\n- HS ghi nhớ nhiệm vụ."},{"ten":"5. Tích hợp Năng lực số & AI","gv":"- (Miền 1: Khai thác dữ liệu và thông tin — Cơ bản, bậc 1) GV mở bản hát mẫu bài “Vào rừng hoa” từ học liệu số của bộ sách, chiếu màn hình có tên bài hát và tên tác giả Việt Anh; GV mở từng câu ngắn, dừng cho HS nghe rồi hát nối tiếp, câu nào chưa đúng thì mở lại câu đó.\n- (Miền 3: Sáng tạo nội dung số — Cơ bản, bậc 1) GV dùng điện thoại ghi âm phần cả lớp hát kết hợp vỗ tay theo phách rồi mở lại qua loa ngay tại lớp; HS nghe giọng hát của mình, chỉ ra chỗ hát chưa rõ lời hoặc vỗ chưa đều; GV thao tác thiết bị, HS chỉ nghe và nhận xét.\n⚠ (Miền 4: An toàn) Bản thu chỉ lấy từ học liệu của bộ sách hoặc kênh chính thức, không tải nhạc từ trang lạ vì có thể sai lời và kèm quảng cáo không phù hợp; giới thiệu bài hát phải nói rõ tên tác giả; mở loa vừa đủ nghe, không để loa sát tai HS.","hs":"- HS nghe bản hát mẫu, nói được tên bài hát “Vào rừng hoa” và tên tác giả Việt Anh, hát đúng lời theo từng câu.\n- HS nghe lại bản ghi âm của lớp, chỉ ra một chỗ hát chưa rõ lời hoặc vỗ tay chưa đúng phách rồi hát lại."}],"status":"checked","source":"KHBD Âm nhạc 1 KNTT (Bút Xanh, theo SGV) — Tiết 1"},
{"lop":1,"mon":"Âm nhạc","tuan":2,"tiet":2,"bai":"Chủ đề 1: Âm thanh kì diệu — Ôn bài hát Vào rừng hoa; Thường thức âm nhạc: Câu chuyện \"Âm thanh kì diệu\"","yccd":"1. Năng lực âm nhạc\n- Hát thuộc lời, đúng giai điệu bài Vào rừng hoa; biết hát kết hợp vận động đơn giản.\n- Nghe và phân biệt được một số âm thanh trong tự nhiên và cuộc sống (tiếng chim, tiếng gió, tiếng mưa, tiếng nhạc cụ).\n- Biết dùng giọng nói, bàn tay, đồ vật để bắt chước âm thanh.\n2. Năng lực chung\n- Tự chủ và tự học: tự tin hát và vận động trước lớp.\n- Giao tiếp và hợp tác: cùng nhóm bắt chước âm thanh theo yêu cầu.\n3. Phẩm chất\n- Yêu thiên nhiên, thích lắng nghe âm thanh xung quanh.\n4. Tích hợp\n- Năng lực số 1.1 CB1a: Tìm được thông tin theo hướng dẫn: HS nghe các đoạn âm thanh GV mở từ học liệu số và nói được đó là tiếng gì.","dodung":"- Giáo viên: đàn phím điện tử, loa, tranh minh họa câu chuyện Âm thanh kì diệu (chim hót, gió thổi, mưa rơi, nhạc cụ), tệp âm thanh tự nhiên, thanh phách, trống con.\n- Học sinh: SGK Âm nhạc 1, thanh phách.","hoatdong":[{"ten":"1. Khởi động","gv":"- GV cho HS nhắm mắt, lắng nghe 2–3 âm thanh GV tạo ra tại lớp (gõ thanh phách, vỗ tay, tiếng giấy sột soạt) rồi đoán đó là tiếng gì.\n- GV mở nhạc bài Vào rừng hoa, cho HS đoán tên bài hát và tác giả.","hs":"- HS nhắm mắt lắng nghe, giơ tay đoán âm thanh.\n- HS nêu tên bài hát Vào rừng hoa của tác giả Việt Anh."},{"ten":"2. Ôn bài hát Vào rừng hoa","gv":"- GV mở nhạc đệm, cho cả lớp hát lại 1–2 lần, sửa chỗ hát chưa đúng.\n- GV hướng dẫn hát kết hợp vận động: câu 1–2 tay vẫy nhẹ như bướm bay, câu 3–4 nghiêng người sang hai bên theo nhịp.\n- GV cho hát theo tổ, theo nhóm; mời 1–2 nhóm biểu diễn.","hs":"- HS hát cả bài theo nhạc đệm.\n- HS quan sát và làm theo động tác, hát kết hợp vận động.\n- HS hát theo tổ, nhóm; biểu diễn trước lớp."},{"ten":"3. Thường thức âm nhạc: Câu chuyện \"Âm thanh kì diệu\"","gv":"- GV treo tranh, kể chuyện ngắn: một bạn nhỏ đi dạo trong rừng, lần lượt nghe thấy tiếng chim hót, tiếng gió thổi, tiếng suối chảy, tiếng mưa rơi, rồi về nhà nghe tiếng đàn, tiếng trống; mỗi đoạn GV mở âm thanh minh họa.\n- GV hỏi: Bạn nhỏ đã nghe được những âm thanh nào? Âm thanh nào nhẹ nhàng, âm thanh nào mạnh?\n- GV cho HS bắt chước từng âm thanh: tiếng gió \"vù vù\", tiếng mưa vỗ nhẹ đầu ngón tay lên bàn, tiếng chim hót, tiếng trống.\n- GV kết luận: xung quanh ta có rất nhiều âm thanh, có âm thanh của tự nhiên và âm thanh của nhạc cụ.","hs":"- HS quan sát tranh, lắng nghe câu chuyện và các âm thanh.\n- HS trả lời: tiếng chim, tiếng gió, tiếng mưa, tiếng đàn...\n- HS bắt chước âm thanh bằng giọng, bàn tay theo GV.\n- HS lắng nghe, nhắc lại."},{"ten":"4. Vận dụng","gv":"- GV tổ chức trò chơi \"Ai đoán giỏi\": GV mở hoặc tạo âm thanh, HS giơ tranh (chim, gió, mưa, trống) tương ứng.\n- GV chia nhóm, mỗi nhóm cùng tạo một \"cơn mưa rừng\": xoa tay – búng tay – vỗ đùi – dậm chân từ nhỏ đến to rồi nhỏ dần.\n- GV dặn HS về nhà lắng nghe và kể cho người thân 3 âm thanh nghe được ở nhà.","hs":"- HS tham gia trò chơi, giơ tranh đúng âm thanh.\n- HS cùng nhóm tạo âm thanh cơn mưa theo hiệu lệnh.\n- HS ghi nhớ nhiệm vụ."},{"ten":"5. Tích hợp Năng lực số & AI","gv":"- (Miền 1: Khai thác dữ liệu và thông tin — Cơ bản, bậc 1) GV mở lần lượt các đoạn âm thanh tự nhiên (chim hót, gió, mưa, suối chảy) và âm thanh nhạc cụ (trống, đàn) từ học liệu số, mỗi đoạn dừng lại cho HS nói tên âm thanh, rồi chiếu tranh tương ứng để đối chiếu.\n- (Miền 3: Sáng tạo nội dung số — Cơ bản, bậc 1) GV ghi âm phần cả lớp tạo \"cơn mưa rừng\" bằng tay chân, mở lại qua loa; HS nghe và nhận xét đoạn nào nghe giống mưa nhỏ, đoạn nào giống mưa to; GV thao tác thiết bị, HS chỉ nghe và trả lời.\n⚠ (Miền 4: An toàn) Các tệp âm thanh lấy từ học liệu của bộ sách hoặc kho âm thanh miễn phí có ghi rõ nguồn; mở loa vừa đủ nghe, tránh tiếng sấm, tiếng trống quá to làm HS giật mình; không cho HS tự cầm thiết bị.","hs":"- HS nghe từng đoạn âm thanh từ loa, nói đúng tên âm thanh (tiếng chim, tiếng mưa, tiếng trống...) và chỉ tranh tương ứng.\n- HS nghe lại bản thu \"cơn mưa rừng\" của lớp, nhận xét chỗ mưa to – mưa nhỏ và làm lại cho rõ hơn."}],"status":"checked","source":"KHBD Âm nhạc 1 KNTT (Bút Xanh, theo SGV) — Tiết 2"},
{"lop":1,"mon":"Âm nhạc","tuan":3,"tiet":3,"bai":"Chủ đề 1: Âm thanh kì diệu — Ôn bài hát Vào rừng hoa; Đọc nhạc: Bậc thang Đô – Rê – Mi","yccd":"1. Năng lực âm nhạc\n- Hát thuộc bài Vào rừng hoa, biết hát nối tiếp theo nhóm kết hợp gõ đệm theo phách.\n- Nhớ tên 3 nốt Đô – Rê – Mi; đọc được 3 nốt theo kí hiệu bàn tay và theo hình bậc thang.\n- Bước đầu phân biệt được nốt cao hơn, nốt thấp hơn khi nghe.\n2. Năng lực chung\n- Tự chủ và tự học: tự làm được kí hiệu bàn tay của 3 nốt.\n- Giao tiếp và hợp tác: đọc nhạc nối tiếp cùng nhóm.\n3. Phẩm chất\n- Chăm chỉ, tích cực tham gia hoạt động học tập.\n4. Tích hợp\n- Năng lực số 1.1 CB1a: Tìm được thông tin theo hướng dẫn: HS nhìn hình bậc thang Đô – Rê – Mi trên màn hình và nghe tiếng đàn để nói được nốt nào cao, nốt nào thấp.","dodung":"- Giáo viên: đàn phím điện tử, loa, tranh hình bậc thang 3 bậc ghi Đô – Rê – Mi, thẻ kí hiệu bàn tay 3 nốt, thanh phách, thiết bị trình chiếu.\n- Học sinh: SGK Âm nhạc 1, thanh phách.","hoatdong":[{"ten":"1. Khởi động","gv":"- GV cho HS chơi \"Làm theo tôi nói, đừng làm theo tôi làm\": GV hô \"vỗ tay\", \"dậm chân\", \"vỗ đùi\" theo phách của nhạc đệm bài Vào rừng hoa.\n- GV hỏi: Nhạc vừa nghe là bài gì? Ai sáng tác?","hs":"- HS vận động theo hiệu lệnh, đúng phách.\n- HS trả lời: bài Vào rừng hoa, tác giả Việt Anh."},{"ten":"2. Ôn bài hát Vào rừng hoa","gv":"- GV cho cả lớp hát cùng nhạc đệm, nhắc HS lấy hơi đầu câu, hát rõ lời.\n- GV chia lớp thành 2 nhóm hát nối tiếp: nhóm 1 hát câu 1, 3; nhóm 2 hát câu 2, 4; sau đó đổi lại.\n- GV cho HS hát kết hợp gõ thanh phách theo phách; mời 1–2 HS hát đơn ca.","hs":"- HS hát cả bài, chú ý lấy hơi, rõ lời.\n- HS hát nối tiếp theo nhóm, nghe bạn để vào đúng câu.\n- HS hát kết hợp gõ phách; HS xung phong hát đơn ca."},{"ten":"3. Đọc nhạc: Bậc thang Đô – Rê – Mi","gv":"- GV treo tranh bậc thang 3 bậc, giới thiệu: bậc thấp nhất là Đô, bậc giữa là Rê, bậc cao nhất là Mi; đàn từng nốt cho HS nghe.\n- GV làm mẫu kí hiệu bàn tay: Đô – bàn tay nắm để ngang bụng; Rê – bàn tay nghiêng, ngón tay chếch lên; Mi – bàn tay để ngang; vừa làm vừa đọc tên nốt.\n- GV đàn và đọc mẫu chuỗi Đô – Rê – Mi, Mi – Rê – Đô rồi cho HS đọc theo kèm kí hiệu bàn tay; sau đó đọc chậm các mẫu ngắn như Đô Đô Rê, Rê Mi Mi, Mi Rê Đô.\n- GV chỉ vào bậc thang không theo thứ tự, HS đọc tên nốt và làm kí hiệu tay.","hs":"- HS quan sát tranh, nghe đàn, nhắc lại tên 3 nốt.\n- HS làm kí hiệu bàn tay theo GV, đọc tên nốt.\n- HS đọc chuỗi nốt theo tiếng đàn kết hợp kí hiệu tay, đọc theo dãy, nhóm.\n- HS nhìn bậc thang, đọc đúng tên nốt GV chỉ."},{"ten":"4. Vận dụng","gv":"- GV tổ chức trò chơi \"Bước lên bậc thang\": GV đàn một nốt, HS làm kí hiệu tay và nói tên nốt; ai đúng được bước lên một bậc vẽ dưới sàn.\n- GV cho 3 HS đóng vai Đô, Rê, Mi đứng theo bậc thang; GV chỉ ai thì cả lớp đọc tên nốt đó.\n- GV dặn HS về nhà tập làm kí hiệu tay 3 nốt cho người thân xem.","hs":"- HS nghe đàn, làm kí hiệu tay, nói tên nốt.\n- HS sắm vai nốt nhạc, cả lớp đọc theo.\n- HS ghi nhớ nhiệm vụ."},{"ten":"5. Tích hợp Năng lực số & AI","gv":"- (Miền 1: Khai thác dữ liệu và thông tin — Cơ bản, bậc 1) GV chiếu hình bậc thang Đô – Rê – Mi từ học liệu số, bấm đàn từng nốt trong khi ô nốt tương ứng sáng lên trên màn hình; HS nhìn – nghe rồi nói tên nốt và cho biết nốt nào cao hơn.\n- (Miền 3: Sáng tạo nội dung số — Cơ bản, bậc 1) GV quay đoạn ngắn cả lớp đọc Đô – Rê – Mi kết hợp kí hiệu bàn tay, mở lại trên màn hình để HS xem tay mình làm đã đúng hình chưa; GV thao tác thiết bị, HS chỉ xem và nhận xét.\n⚠ (Miền 4: An toàn) Hình ảnh và âm thanh lấy từ học liệu của bộ sách; đoạn quay chỉ dùng tại lớp, không đăng lên mạng; HS ngồi cách màn hình đủ xa, không nhìn màn hình quá lâu.","hs":"- HS nhìn ô nốt sáng trên màn hình, nghe đàn và nói đúng tên nốt Đô, Rê hay Mi; nói được nốt Mi cao nhất, nốt Đô thấp nhất.\n- HS xem lại đoạn quay của lớp, chỉ ra bạn nào làm kí hiệu tay chưa đúng và cùng làm lại."}],"status":"checked","source":"KHBD Âm nhạc 1 KNTT (Bút Xanh, theo SGV) — Tiết 3"},
{"lop":1,"mon":"Âm nhạc","tuan":4,"tiet":4,"bai":"Chủ đề 1: Âm thanh kì diệu — Vận dụng – Sáng tạo: To – Nhỏ","yccd":"1. Năng lực âm nhạc\n- Nhận biết và thể hiện được âm thanh to – nhỏ bằng giọng nói, giọng hát, tiếng gõ.\n- Hát bài Vào rừng hoa với sắc thái to – nhỏ theo tay chỉ huy của GV.\n- Đọc được Đô – Rê – Mi to – nhỏ theo ý thích kết hợp kí hiệu bàn tay.\n2. Năng lực chung\n- Tự chủ và tự học: tự chọn cách thể hiện to – nhỏ của riêng mình.\n- Giao tiếp và hợp tác: phối hợp cùng nhóm trong trò chơi Đọc to – đọc nhỏ.\n3. Phẩm chất\n- Yêu âm nhạc, mạnh dạn, tự tin thể hiện trước lớp.\n4. Tích hợp\n- Năng lực số 3.1 CB1a: Tạo được nội dung số đơn giản với sự hỗ trợ của GV: HS cùng GV tạo bản ghi âm đoạn đọc to – nhỏ của lớp và nghe lại.","dodung":"- Giáo viên: đàn phím điện tử, loa, tranh minh họa các hình ảnh to – nhỏ (voi – chuột, trống cái – trống con), thẻ hình \"loa to\" và \"loa nhỏ\", thanh phách, trống con, thiết bị trình chiếu.\n- Học sinh: SGK Âm nhạc 1, thanh phách.","hoatdong":[{"ten":"1. Khởi động","gv":"- GV cho HS xem tranh con voi và con chuột, hỏi: Con nào kêu to, con nào kêu nhỏ? Cho HS bắt chước tiếng voi (to) và tiếng chuột (nhỏ).\n- GV gõ trống con 2 lần: một lần mạnh, một lần nhẹ, HS nói \"to\" hay \"nhỏ\".","hs":"- HS quan sát, trả lời, bắt chước tiếng kêu to – nhỏ.\n- HS nghe tiếng trống, nói to hoặc nhỏ."},{"ten":"2. Thể hiện giọng nói to – nhỏ","gv":"- GV nói một câu chào với giọng to rồi giọng nhỏ, hỏi HS lần nào to, lần nào nhỏ.\n- GV giơ thẻ \"loa to\" thì HS đọc tên mình to, giơ thẻ \"loa nhỏ\" thì đọc nhỏ; làm với tên các bạn, tên đồ vật trong lớp.\n- GV giải thích: nói to khi ở sân trường, nói nhỏ khi ở thư viện, bệnh viện.","hs":"- HS lắng nghe, phân biệt to – nhỏ.\n- HS đọc theo thẻ hiệu lệnh của GV.\n- HS kể thêm nơi cần nói nhỏ."},{"ten":"3. Trò chơi \"Đọc to – đọc nhỏ\"","gv":"- GV chia lớp thành 2 đội, đọc câu đồng dao ngắn hoặc câu hát trong bài Vào rừng hoa: đội A đọc to, đội B đọc nhỏ nhắc lại như tiếng vọng, rồi đổi vai.\n- GV dùng tay chỉ huy: tay giơ cao – hát to, tay hạ thấp – hát nhỏ; cho cả lớp hát bài Vào rừng hoa theo tay GV.\n- GV cho HS gõ thanh phách to – nhỏ theo thẻ hiệu lệnh, xen kẽ với hát.","hs":"- HS đọc theo đội, chú ý đọc to rõ hoặc nhỏ nhẹ như tiếng vọng.\n- HS quan sát tay GV, hát to – nhỏ theo hiệu lệnh.\n- HS gõ thanh phách to – nhỏ."},{"ten":"4. Đọc nhạc Đô – Rê – Mi to – nhỏ theo ý thích","gv":"- GV đàn, cho HS đọc lại Đô – Rê – Mi, Mi – Rê – Đô kết hợp kí hiệu bàn tay.\n- GV làm mẫu đọc chuỗi nốt lần 1 to, lần 2 nhỏ; sau đó cho từng nhóm tự chọn đọc to hay nhỏ, các nhóm khác đoán.\n- GV mời vài HS lên tự nghĩ cách đọc 3 nốt (to dần, nhỏ dần) và biểu diễn; GV khen ngợi.","hs":"- HS đọc nhạc kết hợp kí hiệu tay.\n- HS nhóm chọn cách đọc to hoặc nhỏ, nhóm khác đoán.\n- HS xung phong thể hiện cách đọc riêng của mình."},{"ten":"5. Tích hợp Năng lực số & AI","gv":"- (Miền 3: Sáng tạo nội dung số — Cơ bản, bậc 1) GV dùng điện thoại ghi âm phần cả lớp đọc Đô – Rê – Mi lần to, lần nhỏ rồi mở lại qua loa; HS nghe và nói đoạn nào to, đoạn nào nhỏ, đoạn nào chưa rõ để làm lại; GV thao tác thiết bị, HS chỉ nghe và trả lời.\n- (Miền 1: Khai thác dữ liệu và thông tin — Cơ bản, bậc 1) GV mở một đoạn nhạc ngắn từ học liệu số có chỗ to, chỗ nhỏ, chiếu hình \"loa to\" – \"loa nhỏ\" thay đổi theo nhạc; HS nghe – nhìn rồi giơ tay cao khi nhạc to, hạ tay khi nhạc nhỏ.\n⚠ (Miền 4: An toàn) GV chỉnh âm lượng loa vừa phải, không tăng quá to khi minh họa \"to\"; bản ghi âm giọng HS chỉ dùng tại lớp, không chia sẻ lên mạng; nhạc minh họa lấy từ học liệu của bộ sách.","hs":"- HS nghe lại bản thu đọc nhạc to – nhỏ của lớp, nói được đoạn nào to, đoạn nào nhỏ và đọc lại cho rõ hơn.\n- HS nghe đoạn nhạc, nhìn hình loa trên màn hình, giơ tay cao – thấp đúng lúc nhạc to – nhỏ."}],"status":"checked","source":"KHBD Âm nhạc 1 KNTT (Bút Xanh, theo SGV) — Tiết 4"},
{"lop":1,"mon":"Âm nhạc","tuan":5,"tiet":5,"bai":"Chủ đề 2: Việt Nam yêu thương — Học hát: Tổ quốc ta (Mộng Lân)","yccd":"1. Năng lực âm nhạc\n- Nhớ tên bài hát, tên tác giả; hát rõ lời, đúng giai điệu bài Tổ quốc ta.\n- Bước đầu cảm nhận tính chất trang nghiêm, tự hào của bài hát.\n- Biết hát kết hợp vỗ tay theo phách.\n2. Năng lực chung\n- Tự chủ và tự học: tự tập hát lại câu hát chưa thuộc.\n- Giao tiếp và hợp tác: hát hòa giọng cùng cả lớp, biết lắng nghe bạn hát.\n3. Phẩm chất\n- Yêu quê hương, đất nước; tự hào về Tổ quốc Việt Nam.\n4. Tích hợp\n- Năng lực số 3.3 CB1a: Xác định được các quy tắc đơn giản về bản quyền và giấy phép áp dụng cho dữ liệu, thông tin và nội dung số: HS nói được tên bài hát Tổ quốc ta cùng tên tác giả Mộng Lân.","dodung":"- Giáo viên: đàn phím điện tử, loa, tranh ảnh cảnh đẹp đất nước (biển, núi, cánh đồng, lá cờ Tổ quốc), thanh phách, thiết bị trình chiếu mở học liệu số.\n- Học sinh: SGK Âm nhạc 1, thanh phách.","hoatdong":[{"ten":"1. Khởi động","gv":"- GV chiếu một số hình ảnh cảnh đẹp đất nước (biển, núi, cánh đồng lúa, lá cờ đỏ sao vàng), hỏi: Các em thấy gì? Đây là những cảnh đẹp ở đâu?\n- GV cho HS hát lại bài Vào rừng hoa kết hợp vỗ tay theo phách để khởi động giọng.\n- GV giới thiệu chủ đề Việt Nam yêu thương, tên bài hát Tổ quốc ta và tác giả Mộng Lân.","hs":"- HS quan sát, trả lời: biển, núi, lá cờ... ở đất nước Việt Nam.\n- HS hát và vỗ tay theo phách.\n- HS nhắc lại tên bài hát, tên tác giả."},{"ten":"2. Khám phá — Học hát: Tổ quốc ta","gv":"- GV mở bản hát mẫu từ học liệu số 1–2 lần, hỏi: Bài hát vui nhộn hay trang nghiêm? Em thấy bài hát nói về điều gì?\n- GV chia bài thành các câu ngắn (khoảng 4 câu), đọc lời từng câu theo tiết tấu cho HS đọc theo, giải thích từ \"Tổ quốc\" là đất nước của mình.\n- GV đàn giai điệu và hát mẫu từng câu 2 lần rồi bắt nhịp cho HS hát; ghép câu 1–2, câu 3–4, rồi hát cả bài.\n- GV nhắc HS hát với tư thế ngay ngắn, giọng đầy đặn, rõ lời, thể hiện tình cảm tự hào; sửa chỗ hát sai cao độ.","hs":"- HS nghe, trả lời: bài hát trang nghiêm, nói về đất nước.\n- HS đọc lời ca theo GV, hiểu từ Tổ quốc.\n- HS hát từng câu theo tiếng đàn, hát nối câu, hát cả bài.\n- HS hát với tư thế ngay ngắn, sửa chỗ hát chưa đúng."},{"ten":"3. Luyện tập","gv":"- GV mở nhạc đệm, cho cả lớp hát 2 lần; hát theo dãy, theo tổ, GV nghe và sửa.\n- GV làm mẫu vỗ tay theo phách rồi cho HS hát kết hợp vỗ tay; sau đó gõ thanh phách theo phách.\n- GV cho HS hát nối tiếp: nhóm nữ hát câu 1–2, nhóm nam hát câu 3–4 rồi đổi lại.","hs":"- HS hát cả bài theo nhạc đệm, hát theo dãy, tổ.\n- HS hát kết hợp vỗ tay, gõ thanh phách theo phách.\n- HS hát nối tiếp theo nhóm."},{"ten":"4. Vận dụng","gv":"- GV mời 2–3 nhóm lên hát trước lớp với tư thế nghiêm trang, kết hợp gõ đệm theo phách; GV nhận xét, khen ngợi.\n- GV hỏi: Em làm gì để thể hiện tình yêu với Tổ quốc? (chăm học, giữ vệ sinh trường lớp, đứng nghiêm khi chào cờ...).\n- GV dặn HS về nhà hát cho người thân nghe và chuẩn bị nhạc cụ trống con cho tiết sau.","hs":"- HS xung phong biểu diễn, các bạn nhận xét.\n- HS trả lời theo suy nghĩ của mình.\n- HS ghi nhớ nhiệm vụ."},{"ten":"5. Tích hợp Năng lực số & AI","gv":"- (Miền 1: Khai thác dữ liệu và thông tin — Cơ bản, bậc 1) GV mở bản hát mẫu bài “Tổ quốc ta” từ học liệu số của bộ sách, chiếu màn hình có tên bài hát và tên tác giả Mộng Lân kèm hình ảnh đất nước; GV mở từng câu ngắn, dừng cho HS nghe rồi hát nối tiếp, câu nào chưa đúng thì mở lại câu đó.\n- (Miền 3: Sáng tạo nội dung số — Cơ bản, bậc 1) GV dùng điện thoại ghi âm phần cả lớp hát kết hợp gõ phách rồi mở lại qua loa ngay tại lớp; HS nghe và chỉ ra chỗ hát chưa rõ lời hoặc chưa đều phách; GV thao tác thiết bị, HS chỉ nghe và nhận xét.\n⚠ (Miền 4: An toàn) Bản thu chỉ lấy từ học liệu của bộ sách hoặc kênh chính thức, không tải từ trang lạ vì có thể sai lời và kèm quảng cáo không phù hợp; giới thiệu bài hát phải nói rõ tên tác giả; mở loa vừa đủ nghe.","hs":"- HS nghe bản hát mẫu, nói được tên bài hát “Tổ quốc ta” và tên tác giả Mộng Lân, hát đúng lời theo từng câu.\n- HS nghe lại bản ghi âm của lớp, chỉ ra một chỗ hát chưa rõ lời hoặc gõ chưa đúng phách rồi hát lại."}],"status":"checked","source":"KHBD Âm nhạc 1 KNTT (Bút Xanh, theo SGV) — Tiết 5"},
{"lop":1,"mon":"Âm nhạc","tuan":6,"tiet":6,"bai":"Chủ đề 2: Việt Nam yêu thương — Ôn bài hát Tổ quốc ta; Nhạc cụ: Trống con","yccd":"1. Năng lực âm nhạc\n- Hát thuộc lời, đúng giai điệu bài Tổ quốc ta; biết hát kết hợp vận động đơn giản.\n- Nhận biết trống con: hình dáng, âm thanh; biết cách cầm dùi và gõ trống.\n- Gõ được hình tiết tấu đơn giản (đen – đen – trắng) bằng trống con.\n2. Năng lực chung\n- Tự chủ và tự học: tự cầm dùi, gõ trống đúng cách.\n- Giao tiếp và hợp tác: gõ đúng lượt, không gõ chen khi bạn đang gõ.\n3. Phẩm chất\n- Yêu Tổ quốc; biết giữ gìn nhạc cụ của lớp.\n4. Tích hợp\n- Năng lực số 1.1 CB1a: Tìm được thông tin theo hướng dẫn: HS xem đoạn phim ngắn GV mở và nói được trống con được gõ như thế nào, dùng ở đâu.","dodung":"- Giáo viên: đàn phím điện tử, loa, 3–4 trống con và dùi, tranh ảnh trống con và đội trống ở trường học/lễ hội, bảng hình tiết tấu đen – đen – trắng, thiết bị trình chiếu.\n- Học sinh: SGK Âm nhạc 1, thanh phách (thay trống nếu thiếu).","hoatdong":[{"ten":"1. Khởi động","gv":"- GV gõ một tiếng trống con sau lưng, hỏi HS: Đó là tiếng gì? Rồi đưa trống ra giới thiệu chủ đề tiết học.\n- GV mở nhạc dạo bài Tổ quốc ta, HS đoán tên bài và tác giả.","hs":"- HS lắng nghe, đoán: tiếng trống.\n- HS trả lời: bài Tổ quốc ta của tác giả Mộng Lân."},{"ten":"2. Ôn bài hát Tổ quốc ta","gv":"- GV cho cả lớp hát theo nhạc đệm 1–2 lần, nhắc hát rõ lời, giọng đầy đặn, tư thế nghiêm trang.\n- GV hướng dẫn vận động đơn giản: câu 1–2 tay đưa từ trái sang phải như chỉ cảnh đẹp, câu 3–4 đặt tay lên ngực rồi mở rộng ra.\n- GV cho hát theo tổ, nhóm kết hợp vận động; mời 1–2 nhóm biểu diễn.","hs":"- HS hát cả bài theo nhạc đệm.\n- HS quan sát và làm theo động tác, hát kết hợp vận động.\n- HS hát theo tổ, nhóm; biểu diễn trước lớp."},{"ten":"3. Nhạc cụ: Trống con","gv":"- GV giới thiệu trống con: mặt trống tròn căng bằng da, thân trống bằng gỗ, gõ bằng dùi; chiếu tranh đội trống ở trường và lễ hội, gõ mẫu cho HS nghe.\n- GV hướng dẫn cách cầm: tay trái giữ trống (hoặc đeo trống trước bụng), tay phải cầm dùi ở khoảng 1/3 chiều dài, gõ vào giữa mặt trống rồi nhấc dùi lên ngay; làm mẫu gõ nhẹ – gõ mạnh.\n- GV treo bảng hình tiết tấu đen – đen – trắng, đọc \"đen – đen – trắng\" kết hợp vỗ tay, rồi gõ trống mẫu; cho HS vỗ tay theo trước, sau đó lần lượt từng nhóm gõ trống, HS chưa có trống gõ thanh phách hoặc vỗ tay.\n- GV nhắc: gõ đúng lượt, không gõ khi GV đang nói; giữ trống cẩn thận.","hs":"- HS quan sát trống con, nghe tiếng trống, nhắc lại các bộ phận.\n- HS tập cầm trống, cầm dùi, gõ thử nhẹ – mạnh theo GV.\n- HS đọc tiết tấu, vỗ tay theo, rồi gõ trống con theo hình tiết tấu, luân phiên theo nhóm.\n- HS thực hiện nề nếp khi dùng nhạc cụ."},{"ten":"4. Vận dụng","gv":"- GV cho HS gõ trống con theo hình tiết tấu đen – đen – trắng làm nền trong khi GV hát bài Tổ quốc ta; sau đó đổi: nhóm hát, nhóm gõ.\n- GV tổ chức trò chơi \"Truyền trống\": trống được chuyền theo hàng, HS nhận trống gõ đúng hình tiết tấu rồi chuyền tiếp.\n- GV dặn HS về nhà tập gõ hình tiết tấu bằng bàn tay lên mặt bàn.","hs":"- HS gõ trống theo tiết tấu làm nền, đổi vai hát – gõ.\n- HS tham gia trò chơi, gõ đúng rồi chuyền trống.\n- HS ghi nhớ nhiệm vụ."},{"ten":"5. Tích hợp Năng lực số & AI","gv":"- (Miền 1: Khai thác dữ liệu và thông tin — Cơ bản, bậc 1) GV mở đoạn phim ngắn từ học liệu số về đội trống của thiếu nhi (đeo trống, cầm dùi, gõ đều), dừng ở từng hình để HS chỉ ra cách cầm dùi, cách đeo trống; chiếu bảng hình tiết tấu đen – đen – trắng, GV bấm phát âm thanh trống theo tiết tấu cho HS gõ theo.\n- (Miền 3: Sáng tạo nội dung số — Cơ bản, bậc 1) GV ghi âm phần nhóm gõ trống con theo hình tiết tấu và mở lại qua loa; HS nghe xem tiếng gõ đã đều chưa, tiếng \"trắng\" đã ngân dài hơn tiếng \"đen\" chưa; GV thao tác thiết bị, HS chỉ nghe và nhận xét.\n⚠ (Miền 4: An toàn) Đoạn phim lấy từ học liệu của bộ sách hoặc kênh chính thức, GV xem trước, không có quảng cáo; mở loa vừa đủ nghe vì tiếng trống dễ gây ồn; HS không gõ dùi vào thiết bị hay bàn ghế.","hs":"- HS xem đoạn phim, nói được cách cầm dùi, cách đeo trống của các bạn trong phim; gõ trống theo tiếng mẫu phát ra từ loa.\n- HS nghe lại bản thu tiếng trống của nhóm, nói tiếng gõ đã đều chưa và gõ lại cho đúng."}],"status":"checked","source":"KHBD Âm nhạc 1 KNTT (Bút Xanh, theo SGV) — Tiết 6"},
{"lop":1,"mon":"Âm nhạc","tuan":7,"tiet":7,"bai":"Chủ đề 2: Việt Nam yêu thương — Nhạc cụ: Gõ đệm trống con cho bài Tổ quốc ta; Nghe nhạc: Quốc ca (Văn Cao)","yccd":"1. Năng lực âm nhạc\n- Gõ đệm được theo phách cho bài Tổ quốc ta bằng trống con (hoặc thanh phách), giữ được nhịp đều.\n- Biết bài Quốc ca Việt Nam do nhạc sĩ Văn Cao sáng tác; nghe và cảm nhận tính chất hùng tráng, trang nghiêm.\n- Biết tư thế đứng nghiêm, mắt hướng lên lá cờ khi nghe Quốc ca.\n2. Năng lực chung\n- Tự chủ và tự học: tự giữ nhịp gõ đều khi hát.\n- Giao tiếp và hợp tác: phối hợp nhóm hát – nhóm gõ đệm.\n3. Phẩm chất\n- Yêu nước, tôn trọng Quốc kì, Quốc ca; nghiêm túc trong giờ chào cờ.\n4. Tích hợp\n- Năng lực số 3.3 CB1a: Xác định được các quy tắc đơn giản về bản quyền và giấy phép áp dụng cho dữ liệu, thông tin và nội dung số: HS nói được bài Quốc ca do nhạc sĩ Văn Cao sáng tác.","dodung":"- Giáo viên: đàn phím điện tử, loa, trống con và dùi, thanh phách, bản thu Quốc ca (từ học liệu chính thức), tranh lễ chào cờ ở trường, ảnh nhạc sĩ Văn Cao, thiết bị trình chiếu.\n- Học sinh: SGK Âm nhạc 1, thanh phách.","hoatdong":[{"ten":"1. Khởi động","gv":"- GV gõ trống con theo hình tiết tấu đen – đen – trắng, HS vỗ tay nhắc lại; đổi vài mẫu ngắn khác.\n- GV cho cả lớp hát bài Tổ quốc ta 1 lần theo nhạc đệm để nhớ bài.","hs":"- HS nghe và vỗ tay nhắc lại tiết tấu.\n- HS hát bài Tổ quốc ta."},{"ten":"2. Nhạc cụ: Gõ đệm trống con cho bài Tổ quốc ta","gv":"- GV nhắc lại cách cầm dùi, gõ trống; làm mẫu gõ theo phách: mỗi phách một tiếng gõ đều, tiếng đầu nhịp gõ mạnh hơn một chút.\n- GV hát chậm câu 1 và gõ trống theo phách cho HS quan sát; sau đó cho HS vỗ tay theo phách cả bài trước, rồi mới gõ trống.\n- GV chia lớp: nhóm 1 hát, nhóm 2 gõ trống con, nhóm 3 gõ thanh phách; đổi vai sau mỗi lượt; GV giữ nhịp bằng đàn.\n- GV sửa cho HS gõ nhanh hơn nhạc hoặc gõ quá mạnh át tiếng hát.","hs":"- HS quan sát, nhắc lại cách gõ theo phách.\n- HS vỗ tay theo phách cả bài, rồi gõ trống theo phách.\n- HS thực hiện theo nhóm hát – gõ trống – gõ phách, đổi vai.\n- HS điều chỉnh gõ đều, vừa phải."},{"ten":"3. Nghe nhạc: Quốc ca (Văn Cao)","gv":"- GV chiếu tranh lễ chào cờ ở sân trường, hỏi: Trong giờ chào cờ các em nghe bài hát gì? Giới thiệu bài Quốc ca Việt Nam do nhạc sĩ Văn Cao sáng tác, giới thiệu ảnh nhạc sĩ.\n- GV hướng dẫn tư thế nghe: đứng nghiêm, hai tay thẳng theo thân, mắt hướng lên lá cờ, không nói chuyện; mở bản Quốc ca cho HS nghe lần 1.\n- GV hỏi: Bài hát nghe mạnh mẽ hay nhẹ nhàng? Em cảm thấy thế nào khi nghe? Cho HS nghe lần 2, đứng nghiêm và hát nhẩm theo nếu đã biết.\n- GV giáo dục: Quốc ca là bài hát của cả nước, khi nghe phải đứng nghiêm trang để thể hiện lòng yêu nước.","hs":"- HS quan sát tranh, trả lời: bài Quốc ca; nhắc lại tên tác giả Văn Cao.\n- HS đứng nghiêm, lắng nghe Quốc ca.\n- HS trả lời: bài hát mạnh mẽ, hùng tráng; nghe lần 2 với tư thế nghiêm.\n- HS lắng nghe, nhắc lại việc cần làm khi chào cờ."},{"ten":"4. Vận dụng","gv":"- GV cho HS biểu diễn bài Tổ quốc ta theo nhóm: 2–3 HS gõ trống con đệm theo phách, các bạn còn lại hát; GV nhận xét, khen ngợi.\n- GV cho HS tập lại tư thế chào cờ tại lớp trong 1 phút với nhạc Quốc ca.\n- GV dặn HS thực hiện nghiêm túc khi chào cờ đầu tuần.","hs":"- HS biểu diễn theo nhóm, các bạn nhận xét.\n- HS đứng nghiêm, thực hành tư thế chào cờ.\n- HS ghi nhớ nhiệm vụ."},{"ten":"5. Tích hợp Năng lực số & AI","gv":"- (Miền 1: Khai thác dữ liệu và thông tin — Cơ bản, bậc 1) GV mở bản thu Quốc ca từ học liệu chính thức, chiếu hình lá cờ Tổ quốc và tên nhạc sĩ Văn Cao; HS nghe và nói tên bài hát, tên tác giả; GV chiếu tiếp ảnh lễ chào cờ ở trường để HS chỉ ra bạn nào đứng đúng tư thế.\n- (Miền 3: Sáng tạo nội dung số — Cơ bản, bậc 1) GV ghi âm phần nhóm hát Tổ quốc ta có gõ trống con đệm theo phách, mở lại qua loa; HS nghe và nói tiếng trống đã đều theo hát chưa, có át tiếng hát không; GV thao tác thiết bị, HS chỉ nghe và nhận xét.\n⚠ (Miền 4: An toàn) Bản Quốc ca phải lấy từ nguồn chính thức, không dùng bản phối lạ; khi mở Quốc ca cả lớp đứng nghiêm, không đùa nghịch; mở loa vừa đủ nghe; bản thu của lớp chỉ dùng tại lớp.","hs":"- HS nghe Quốc ca từ loa, nói được tên bài hát và tên nhạc sĩ Văn Cao; nhìn ảnh chào cờ và chỉ ra tư thế đúng.\n- HS nghe lại bản thu của nhóm, nhận xét tiếng trống có đều theo phách không và gõ lại."}],"status":"checked","source":"KHBD Âm nhạc 1 KNTT (Bút Xanh, theo SGV) — Tiết 7"},
{"lop":1,"mon":"Âm nhạc","tuan":8,"tiet":8,"bai":"Chủ đề 2: Việt Nam yêu thương — Vận dụng – Sáng tạo: Cao – Thấp","yccd":"1. Năng lực âm nhạc\n- Nghe và nhắc lại được các âm thanh bằng âm \"la\" đúng cao độ tương đối.\n- Phân biệt được âm thanh cao – thấp khi nghe đàn, giọng hát, tiếng kêu con vật.\n- Nghe nhạc và vận động cơ thể theo hướng lên – xuống của âm thanh.\n2. Năng lực chung\n- Tự chủ và tự học: tự thể hiện âm cao – thấp bằng giọng và động tác.\n- Giao tiếp và hợp tác: chơi trò chơi theo nhóm, chờ đến lượt.\n3. Phẩm chất\n- Yêu âm nhạc, mạnh dạn, tự tin.\n4. Tích hợp\n- Năng lực số 1.1 CB1a: Tìm được thông tin theo hướng dẫn: HS nghe âm thanh GV mở từ học liệu số và nói được âm nào cao, âm nào thấp.","dodung":"- Giáo viên: đàn phím điện tử, loa, tranh con vật kêu cao – thấp (chim nhỏ – bò, gà con – gà trống), thẻ mũi tên lên – xuống, bản nhạc không lời có nét giai điệu lên – xuống rõ (từ học liệu), thanh phách, thiết bị trình chiếu.\n- Học sinh: SGK Âm nhạc 1, thanh phách.","hoatdong":[{"ten":"1. Khởi động","gv":"- GV cho HS xem tranh chim nhỏ và con bò, bắt chước tiếng kêu: chim \"chíp chíp\" giọng cao, bò \"ùm bò\" giọng thấp; hỏi tiếng nào cao, tiếng nào thấp.\n- GV cho cả lớp hát bài Tổ quốc ta kết hợp vỗ tay theo phách.","hs":"- HS bắt chước tiếng kêu, trả lời: tiếng chim cao, tiếng bò thấp.\n- HS hát và vỗ tay theo phách."},{"ten":"2. Nghe và nhắc lại âm thanh bằng âm \"la\"","gv":"- GV đàn một nốt, hát mẫu \"la\" rồi cho HS nhắc lại; đàn nốt cao hơn – thấp hơn, HS nhắc lại bằng \"la\".\n- GV đàn các mẫu 2–3 nốt (Đô – Mi, Mi – Đô, Đô – Rê – Mi), hát \"la la la\" và cho HS hát nhắc lại theo dãy, nhóm, cá nhân.\n- GV sửa cho HS hát \"la\" đúng cao độ, giọng nhẹ nhàng, không gào.","hs":"- HS lắng nghe, hát nhắc lại bằng âm \"la\".\n- HS hát nhắc lại các mẫu ngắn theo dãy, nhóm, cá nhân.\n- HS điều chỉnh giọng theo hướng dẫn."},{"ten":"3. Phân biệt âm thanh cao – thấp","gv":"- GV đàn 2 nốt cách xa nhau, HS giơ tay cao nếu nghe nốt cao, đặt tay xuống đùi nếu nghe nốt thấp; làm nhiều lần, đổi thứ tự.\n- GV dùng thẻ mũi tên lên – xuống: GV đàn chuỗi nốt đi lên hay đi xuống, HS chọn thẻ đúng.\n- GV cho HS chơi \"Thang máy\": GV đàn nốt đi lên thì HS từ từ đứng dậy, đi xuống thì từ từ ngồi thấp; ai làm sai ngồi xuống chờ lượt.\n- GV kết luận: âm thanh có âm cao, âm thấp; trong bài hát cũng có chỗ hát cao, chỗ hát thấp.","hs":"- HS nghe, giơ tay cao – thấp theo âm thanh.\n- HS chọn thẻ mũi tên đúng hướng.\n- HS chơi trò chơi, vận động lên – xuống theo tiếng đàn.\n- HS nhắc lại kết luận."},{"ten":"4. Nghe nhạc và vận động","gv":"- GV mở bản nhạc không lời ngắn có nét giai điệu lên – xuống rõ, hướng dẫn HS đưa tay lên khi nhạc cao, hạ tay xuống khi nhạc thấp; cho nghe 2 lần.\n- GV cho HS tự chọn động tác (nhún, vẫy tay, lắc lư) và vận động tự do theo nhạc, chỗ cao vươn người, chỗ thấp cúi thấp.\n- GV mời vài HS lên thể hiện, khen ngợi; dặn HS về nhà nghe và tìm tiếng con vật kêu cao – thấp ở nhà.","hs":"- HS nghe nhạc, đưa tay lên – xuống theo giai điệu.\n- HS vận động tự do theo ý thích, đúng hướng cao – thấp.\n- HS xung phong biểu diễn; ghi nhớ nhiệm vụ."},{"ten":"5. Tích hợp Năng lực số & AI","gv":"- (Miền 1: Khai thác dữ liệu và thông tin — Cơ bản, bậc 1) GV mở từ học liệu số các đoạn âm thanh cao – thấp (tiếng chim, tiếng bò, tiếng sáo, tiếng trống) và tiếng đàn các nốt, chiếu hình mũi tên lên – xuống chạy theo âm thanh; HS nghe – nhìn rồi nói âm nào cao, âm nào thấp và giơ tay theo.\n- (Miền 3: Sáng tạo nội dung số — Cơ bản, bậc 1) GV ghi âm phần cả lớp hát \"la\" nhắc lại mẫu cao – thấp và mở lại qua loa; HS nghe xem lớp đã hát đúng cao – thấp theo đàn chưa; GV thao tác thiết bị, HS chỉ nghe và nhận xét.\n⚠ (Miền 4: An toàn) Âm thanh lấy từ học liệu của bộ sách hoặc kho âm thanh có ghi rõ nguồn; mở loa vừa đủ nghe, tránh âm quá cao chói tai; HS ngồi cách màn hình đủ xa; bản thu chỉ dùng tại lớp.","hs":"- HS nghe từng đoạn âm thanh từ loa, nhìn mũi tên trên màn hình, nói đúng âm cao – thấp và giơ tay cao – hạ tay theo.\n- HS nghe lại bản thu lớp hát \"la\", nói chỗ nào hát chưa đúng cao – thấp và hát lại."}],"status":"checked","source":"KHBD Âm nhạc 1 KNTT (Bút Xanh, theo SGV) — Tiết 8"},
{"lop":1,"mon":"Âm nhạc","tuan":9,"tiet":9,"bai":"Chủ đề 3: Mái trường thân yêu — Học hát: Lớp Một thân yêu (Bùi Anh Tôn)","yccd":"1. Năng lực âm nhạc\n- Nhớ tên bài hát, tên tác giả; hát rõ lời, đúng giai điệu bài Lớp Một thân yêu.\n- Bước đầu cảm nhận tính chất vui tươi, hồn nhiên của bài hát.\n- Biết hát kết hợp vỗ tay theo phách.\n2. Năng lực chung\n- Tự chủ và tự học: mạnh dạn hát trước lớp, tự tập lại câu hát chưa thuộc.\n- Giao tiếp và hợp tác: hát hòa giọng, hát nối tiếp cùng các bạn.\n3. Phẩm chất\n- Yêu trường lớp, yêu quý thầy cô và bạn bè; chăm chỉ học tập.\n4. Tích hợp\n- Năng lực số 3.3 CB1a: Xác định được các quy tắc đơn giản về bản quyền và giấy phép áp dụng cho dữ liệu, thông tin và nội dung số: HS nói được tên bài hát Lớp Một thân yêu cùng tên tác giả Bùi Anh Tôn.","dodung":"- Giáo viên: đàn phím điện tử, loa, tranh ảnh lớp học, cô giáo và các bạn lớp Một, thanh phách, thiết bị trình chiếu mở học liệu số.\n- Học sinh: SGK Âm nhạc 1, thanh phách.","hoatdong":[{"ten":"1. Khởi động","gv":"- GV chiếu tranh lớp học có cô giáo và các bạn nhỏ, hỏi: Các em đang học lớp mấy? Lớp mình có những ai? Em thích điều gì ở lớp?\n- GV cho HS chơi \"Truyền tin theo phách\": vỗ tay theo phách nhạc đệm bài Tổ quốc ta, ai được chỉ thì nói tên một bạn trong lớp.\n- GV giới thiệu chủ đề Mái trường thân yêu, tên bài hát Lớp Một thân yêu và tác giả Bùi Anh Tôn.","hs":"- HS quan sát, trả lời: lớp Một, có cô giáo, các bạn...\n- HS vỗ tay theo phách, tham gia trò chơi.\n- HS nhắc lại tên bài hát, tên tác giả."},{"ten":"2. Khám phá — Học hát: Lớp Một thân yêu","gv":"- GV mở bản hát mẫu từ học liệu số 1–2 lần, hỏi: Bài hát vui hay buồn? Bài hát nói về ai, về điều gì?\n- GV chia bài thành các câu ngắn (khoảng 4 câu), đọc lời từng câu theo tiết tấu cho HS đọc theo.\n- GV đàn giai điệu và hát mẫu từng câu 2 lần rồi bắt nhịp cho HS hát; ghép câu 1–2, câu 3–4, rồi hát cả bài.\n- GV sửa các tiếng hát luyến, ngân; nhắc HS hát tươi vui, rõ lời, không hát quá to.","hs":"- HS nghe, trả lời: bài hát vui, nói về lớp Một, về cô giáo và bạn bè.\n- HS đọc lời ca từng câu theo GV.\n- HS hát từng câu theo tiếng đàn, hát nối câu, hát cả bài.\n- HS sửa chỗ hát chưa đúng."},{"ten":"3. Luyện tập","gv":"- GV mở nhạc đệm, cho cả lớp hát 2 lần; hát theo dãy, tổ; GV nghe và sửa.\n- GV làm mẫu vỗ tay theo phách rồi cho HS hát kết hợp vỗ tay; sau đó gõ thanh phách theo phách.\n- GV cho HS hát nối tiếp: tổ 1 câu 1, tổ 2 câu 2, tổ 3 câu 3, cả lớp câu 4.","hs":"- HS hát cả bài theo nhạc đệm, hát theo dãy, tổ.\n- HS hát kết hợp vỗ tay, gõ thanh phách theo phách.\n- HS hát nối tiếp theo tổ, nghe bạn để vào đúng câu."},{"ten":"4. Vận dụng","gv":"- GV mời 2–3 nhóm lên hát trước lớp kết hợp vỗ tay theo phách, có thể nhún chân theo nhịp; GV nhận xét, khen ngợi.\n- GV hỏi: Em cần làm gì để lớp mình luôn vui và sạch đẹp? (đoàn kết với bạn, giữ vệ sinh lớp, nghe lời cô...).\n- GV dặn HS về nhà hát cho người thân nghe.","hs":"- HS xung phong biểu diễn, các bạn cổ vũ.\n- HS trả lời theo suy nghĩ.\n- HS ghi nhớ nhiệm vụ."},{"ten":"5. Tích hợp Năng lực số & AI","gv":"- (Miền 1: Khai thác dữ liệu và thông tin — Cơ bản, bậc 1) GV mở bản hát mẫu bài “Lớp Một thân yêu” từ học liệu số của bộ sách, chiếu màn hình có tên bài hát và tên tác giả Bùi Anh Tôn kèm hình ảnh lớp học; GV mở từng câu ngắn, dừng cho HS nghe rồi hát nối tiếp, câu nào chưa đúng thì mở lại câu đó.\n- (Miền 3: Sáng tạo nội dung số — Cơ bản, bậc 1) GV dùng điện thoại ghi âm phần cả lớp hát kết hợp vỗ tay theo phách rồi mở lại qua loa ngay tại lớp; HS nghe và chỉ ra chỗ hát chưa rõ lời hoặc vỗ chưa đều; GV thao tác thiết bị, HS chỉ nghe và nhận xét.\n⚠ (Miền 4: An toàn) Bản thu chỉ lấy từ học liệu của bộ sách hoặc kênh chính thức, không tải từ trang lạ vì có thể sai lời và kèm quảng cáo không phù hợp; giới thiệu bài hát phải nói rõ tên tác giả; mở loa vừa đủ nghe; bản ghi âm giọng HS chỉ dùng tại lớp.","hs":"- HS nghe bản hát mẫu, nói được tên bài hát “Lớp Một thân yêu” và tên tác giả Bùi Anh Tôn, hát đúng lời theo từng câu.\n- HS nghe lại bản ghi âm của lớp, chỉ ra một chỗ hát chưa rõ lời hoặc vỗ tay chưa đúng phách rồi hát lại."}],"status":"checked","source":"KHBD Âm nhạc 1 KNTT (Bút Xanh, theo SGV) — Tiết 9"},
{"lop":1,"mon":"Âm nhạc","tuan":10,"tiet":10,"bai":"Chủ đề 3: Mái trường thân yêu — Ôn bài hát Lớp Một thân yêu; Đọc nhạc: Ban nhạc Đô – Rê – Mi","yccd":"1. Năng lực âm nhạc\n- Hát thuộc lời, đúng giai điệu bài Lớp Một thân yêu; hát kết hợp vỗ tay theo phách và vận động đơn giản.\n- Đọc được ba nốt Đô – Rê – Mi theo kí hiệu bàn tay bằng âm “la” và bằng tên nốt; bước đầu đọc được bài Ban nhạc Đô – Rê – Mi.\n- Biết sắm vai thành viên “ban nhạc”, đọc nối tiếp theo hiệu lệnh tay của GV.\n2. Năng lực chung\n- Tự chủ và tự học: tự làm kí hiệu bàn tay khi đọc nốt.\n- Giao tiếp và hợp tác: phối hợp với bạn trong nhóm “ban nhạc” để đọc đúng lượt.\n3. Phẩm chất\n- Yêu trường lớp, thầy cô, bạn bè; hào hứng tham gia hoạt động tập thể.\n4. Tích hợp\n- Năng lực số 1.1 CB1a: Tìm được thông tin đơn giản theo hướng dẫn: HS nhìn màn hình nhận ra hình bàn tay ứng với nốt Đô, Rê, Mi khi GV chiếu.","dodung":"- Giáo viên: đàn Organ (hoặc nhạc đệm), loa, tranh hình bậc thang Đô – Rê – Mi, thẻ hình kí hiệu bàn tay 3 nốt, thanh phách, thiết bị trình chiếu.\n- Học sinh: SGK Âm nhạc 1, thanh phách.","hoatdong":[{"ten":"1. Khởi động","gv":"- GV mở nhạc đệm bài Lớp Một thân yêu, cho HS nghe lại giai điệu và đoán tên bài hát.\n- GV bắt nhịp cho cả lớp hát 1 lần, vừa hát vừa nhún chân theo nhịp.","hs":"- HS nghe, nói tên bài hát và tên tác giả Bùi Anh Tôn.\n- HS hát cùng nhạc đệm, nhún chân theo nhịp."},{"ten":"2. Ôn bài hát Lớp Một thân yêu","gv":"- GV cho HS hát cả bài theo nhạc đệm, lưu ý chỗ ngân dài cuối câu và hát rõ lời.\n- GV hướng dẫn hát kết hợp vỗ tay theo phách, sau đó thay bằng gõ thanh phách.\n- GV chia lớp thành 2 dãy hát nối tiếp từng câu; mời 1–2 nhóm hát kết hợp vận động (vẫy tay, lắc lư).","hs":"- HS hát cả bài, sửa chỗ GV nhắc.\n- HS hát kết hợp vỗ tay, gõ thanh phách theo phách.\n- HS hát nối tiếp theo dãy; nhóm xung phong hát và vận động trước lớp."},{"ten":"3. Đọc nhạc: Ban nhạc Đô – Rê – Mi","gv":"- GV treo tranh bậc thang Đô – Rê – Mi, làm mẫu kí hiệu bàn tay từng nốt (Đô: nắm tay, Rê: bàn tay nghiêng, Mi: bàn tay ngang), đàn cao độ và đọc mẫu bằng âm “la” rồi bằng tên nốt.\n- GV cho HS đọc theo thứ tự đi lên Đô – Rê – Mi, đi xuống Mi – Rê – Đô, vừa đọc vừa làm kí hiệu bàn tay.\n- GV đàn từng câu ngắn của bài đọc nhạc Ban nhạc Đô – Rê – Mi (2–3 nốt mỗi câu), HS nghe và đọc lại; ghép các câu thành bài, đọc theo tay GV.","hs":"- HS quan sát, làm kí hiệu bàn tay và đọc theo GV bằng âm “la” rồi bằng tên nốt.\n- HS đọc đi lên, đi xuống kết hợp kí hiệu bàn tay.\n- HS nghe đàn, đọc lại từng câu rồi đọc cả bài theo tay GV."},{"ten":"4. Vận dụng — Sắm vai “ban nhạc”","gv":"- GV chia lớp thành 3 nhóm: nhóm Đô, nhóm Rê, nhóm Mi; GV chỉ tay đến nốt nào thì nhóm đó đọc và làm kí hiệu bàn tay.\n- GV đổi vai các nhóm, mời 1 HS lên làm “nhạc trưởng” chỉ tay cho cả lớp đọc; khen nhóm đọc đúng lượt, đúng cao độ.","hs":"- HS đứng theo nhóm, đọc đúng nốt của nhóm mình khi được chỉ.\n- HS đổi vai, một bạn làm “nhạc trưởng”, các bạn khác đọc theo."},{"ten":"5. Tích hợp Năng lực số & AI","gv":"- (Miền 1: Khai thác dữ liệu và thông tin — Cơ bản, bậc 1) GV chiếu hình ba kí hiệu bàn tay Đô – Rê – Mi lấy từ học liệu số của bộ sách, bật âm mẫu từng nốt trên phần mềm đàn phím cho HS nghe và bắt chước; GV che tên nốt, chỉ vào hình bàn tay để HS đoán và đọc nốt.\n- (Miền 3: Sáng tạo nội dung số — Cơ bản, bậc 1) GV dùng điện thoại quay ngắn phần “ban nhạc Đô – Rê – Mi” của một nhóm rồi mở lại trên màn hình; HS xem lại kí hiệu bàn tay của mình đã đúng chưa; GV thao tác thiết bị, HS chỉ xem và nhận xét.\n⚠ (Miền 4: An toàn) Âm mẫu và hình kí hiệu bàn tay lấy từ học liệu của bộ sách, không dùng hình tải từ trang lạ; đoạn quay chỉ dùng tại lớp, không đăng lên mạng khi chưa được cha mẹ HS đồng ý; mở loa vừa đủ nghe.","hs":"- HS nhìn hình bàn tay trên màn hình, nghe âm mẫu và đọc đúng tên nốt Đô, Rê, Mi.\n- HS xem lại đoạn quay của nhóm, chỉ ra một bạn làm kí hiệu bàn tay chưa đúng và cùng làm lại."}],"status":"checked","source":"KHBD Âm nhạc 1 KNTT (Bút Xanh, theo SGV) — Tiết 10"},
{"lop":1,"mon":"Âm nhạc","tuan":11,"tiet":11,"bai":"Chủ đề 3: Mái trường thân yêu — Ôn đọc nhạc Ban nhạc Đô – Rê – Mi; Nghe nhạc: Những bông hoa những bài ca (Hoàng Long)","yccd":"1. Năng lực âm nhạc\n- Đọc đúng cao độ ba nốt Đô – Rê – Mi theo kí hiệu bàn tay; đọc được bài Ban nhạc Đô – Rê – Mi theo nhóm, cá nhân.\n- Biết lắng nghe bài Những bông hoa những bài ca; nêu được cảm nhận đơn giản (vui, nhộn nhịp) và nói được bài hát nói về ai.\n- Biết vận động cơ thể (vỗ tay, lắc lư, bước chân) phù hợp với nhịp điệu bài nghe.\n2. Năng lực chung\n- Tự chủ và tự học: chủ động làm kí hiệu bàn tay khi đọc nhạc.\n- Giao tiếp và hợp tác: cùng bạn vận động theo nhạc, chia sẻ cảm nhận sau khi nghe.\n3. Phẩm chất\n- Kính yêu, biết ơn thầy cô giáo; yêu mái trường.\n4. Tích hợp\n- Năng lực số 3.3 CB1a: Xác định được các quy tắc đơn giản về bản quyền và giấy phép áp dụng cho dữ liệu, thông tin và nội dung số: HS nói được tên bài nghe nhạc và tên tác giả Hoàng Long.","dodung":"- Giáo viên: đàn Organ, loa, bản thu bài Những bông hoa những bài ca (học liệu số của bộ sách), tranh minh hoạ HS tặng hoa thầy cô, thẻ kí hiệu bàn tay Đô – Rê – Mi, thiết bị trình chiếu.\n- Học sinh: SGK Âm nhạc 1, thanh phách.","hoatdong":[{"ten":"1. Khởi động","gv":"- GV chơi trò “Bàn tay biết nói”: GV làm kí hiệu bàn tay không đọc thành tiếng, HS nhìn tay và đọc tên nốt.\n- GV đàn 3 nốt theo thứ tự bất kì, HS nghe và giơ kí hiệu bàn tay tương ứng.","hs":"- HS nhìn tay GV, đọc Đô – Rê – Mi đúng nốt.\n- HS nghe đàn, giơ kí hiệu bàn tay đúng nốt vừa nghe."},{"ten":"2. Ôn đọc nhạc: Ban nhạc Đô – Rê – Mi","gv":"- GV đàn giai điệu bài đọc nhạc 1 lần, cho HS đọc bằng âm “la” rồi đọc tên nốt kết hợp kí hiệu bàn tay.\n- GV cho HS đọc theo nhóm, mỗi nhóm đọc một câu nối tiếp; sửa cao độ nốt Mi (HS thường đọc thấp).\n- GV hướng dẫn đọc kết hợp gõ thanh phách theo phách; mời 2–3 HS đọc cá nhân.","hs":"- HS đọc bằng “la”, đọc tên nốt và làm kí hiệu bàn tay.\n- HS đọc nối tiếp theo nhóm, chú ý sửa nốt Mi.\n- HS đọc kết hợp gõ phách; HS xung phong đọc cá nhân."},{"ten":"3. Nghe nhạc: Những bông hoa những bài ca","gv":"- GV cho HS xem tranh, giới thiệu tên bài hát và tác giả Hoàng Long; nêu câu hỏi trước khi nghe: Bài hát nói về ai? Các bạn nhỏ đang làm gì?\n- GV mở bản thu lần 1, HS nghe im lặng; mở lần 2, GV gợi ý HS vỗ tay nhẹ theo phách.\n- GV hỏi: Bài hát vui hay buồn? Em thích đoạn nào? GV chốt: bài hát thể hiện tình cảm của HS với thầy cô.","hs":"- HS xem tranh, nhắc lại tên bài, tên tác giả.\n- HS nghe lần 1 im lặng; lần 2 vỗ tay nhẹ theo phách.\n- HS trả lời: bài hát vui, nói về các bạn nhỏ tặng hoa, hát tặng thầy cô."},{"ten":"4. Vận dụng — Nghe nhạc và vận động","gv":"- GV mở lại bài hát, làm mẫu vài động tác đơn giản (đưa tay như tặng hoa, lắc lư, bước chân tại chỗ) cho HS làm theo.\n- GV mời từng nhóm lên vận động theo nhạc theo ý thích; khen ngợi nhóm vận động đều, đúng nhịp.","hs":"- HS nghe nhạc, bắt chước động tác của GV.\n- HS theo nhóm vận động tự do theo nhạc trước lớp."},{"ten":"5. Tích hợp Năng lực số & AI","gv":"- (Miền 1: Khai thác dữ liệu và thông tin — Cơ bản, bậc 1) GV mở bản thu bài “Những bông hoa những bài ca” từ học liệu số, chiếu màn hình có tên bài và tên tác giả Hoàng Long cùng tranh minh hoạ; GV dừng ở đoạn nhộn nhịp và hỏi HS bài hát đang vui hay buồn.\n- (Miền 6: Ứng dụng trí tuệ nhân tạo — Cơ bản, bậc 1) GV dùng phần mềm đàn phím trên máy tính bật từng nốt Đô, Rê, Mi để HS đọc lại; máy hiển thị tên nốt vừa vang lên để HS đối chiếu với kí hiệu bàn tay của mình; GV thao tác thiết bị, HS chỉ nghe – nhìn – đọc.\n⚠ (Miền 4: An toàn) Bản thu lấy từ học liệu của bộ sách hoặc kênh chính thức, nêu rõ tên tác giả; không mở video có quảng cáo; mở loa vừa đủ nghe; HS không tự chạm vào thiết bị.","hs":"- HS nghe bản thu, nói được tên bài hát và tên tác giả Hoàng Long, nói được bài hát vui.\n- HS nghe từng nốt máy phát, đọc tên nốt và làm kí hiệu bàn tay rồi đối chiếu với tên nốt hiện trên màn hình."}],"status":"checked","source":"KHBD Âm nhạc 1 KNTT (Bút Xanh, theo SGV) — Tiết 11"},
{"lop":1,"mon":"Âm nhạc","tuan":12,"tiet":12,"bai":"Chủ đề 3: Mái trường thân yêu — Vận dụng – Sáng tạo: To – Nhỏ, Cao – Thấp","yccd":"1. Năng lực âm nhạc\n- Phân biệt và thể hiện được âm thanh to – nhỏ, cao – thấp bằng giọng đọc, giọng hát và tiếng vỗ tay.\n- Đọc được câu nhạc Đô – Rê – Mi to – nhỏ theo hình kí hiệu; hát bài Lớp Một thân yêu với sắc thái to – nhỏ theo hiệu lệnh.\n- Biết nghe nhạc và vận động theo ý thích, thể hiện cao – thấp bằng động tác cơ thể.\n2. Năng lực chung\n- Tự chủ và tự học: tự chọn cách thể hiện to – nhỏ, cao – thấp.\n- Giải quyết vấn đề và sáng tạo: nghĩ ra động tác hoặc âm thanh mới để thể hiện cao – thấp.\n3. Phẩm chất\n- Chăm chỉ, mạnh dạn, biết lắng nghe bạn.\n4. Tích hợp\n- Năng lực số 1.1 CB1a: Tìm được thông tin đơn giản theo hướng dẫn: HS nhìn hình sóng âm trên màn hình và nói âm thanh nào to, âm thanh nào nhỏ.","dodung":"- Giáo viên: đàn Organ, loa, thẻ hình to – nhỏ (bàn tay to/nhỏ, loa to/nhỏ), thẻ hình cao – thấp (chim trên cây, mèo dưới đất), nhạc đệm bài Lớp Một thân yêu, bản thu Những bông hoa những bài ca, thiết bị trình chiếu.\n- Học sinh: SGK Âm nhạc 1, thanh phách.","hoatdong":[{"ten":"1. Khởi động","gv":"- GV chơi trò “Làm theo tôi nói”: GV nói to – HS vỗ tay to, GV nói nhỏ – HS vỗ tay nhỏ; GV giơ tay cao – HS đọc “la” cao, GV hạ tay thấp – HS đọc “la” thấp.\n- GV hỏi: Vừa rồi các em đã làm những gì?","hs":"- HS chơi, vỗ tay to – nhỏ, đọc “la” cao – thấp theo hiệu lệnh.\n- HS trả lời: vỗ tay to – nhỏ, đọc cao – thấp."},{"ten":"2. Đọc to – nhỏ, cao – thấp câu nhạc Đô – Rê – Mi","gv":"- GV chiếu hình câu nhạc Đô – Rê – Mi kèm kí hiệu to (chữ to, hình loa to) và nhỏ (chữ nhỏ, hình loa nhỏ); GV đọc mẫu.\n- GV chỉ vào hình, HS đọc câu nhạc to hoặc nhỏ theo hình; đổi hình nhiều lần, đổi nhanh dần.\n- GV đàn nốt Đô (thấp) và Mi (cao), HS đọc và làm kí hiệu bàn tay thấp – cao; mở rộng: HS tự chọn đọc Đô – Mi cao – thấp theo ý thích.","hs":"- HS quan sát hình, nghe đọc mẫu.\n- HS đọc câu nhạc to – nhỏ theo hình GV chỉ.\n- HS đọc Đô thấp, Mi cao kết hợp kí hiệu bàn tay; tự chọn cách đọc."},{"ten":"3. Vỗ tay to – nhỏ theo hình","gv":"- GV treo dãy hình bàn tay to – nhỏ xen kẽ (ví dụ: to – to – nhỏ – nhỏ), làm mẫu vỗ tay theo hình.\n- GV cho HS vỗ tay theo hình cả lớp, theo dãy; đổi bằng gõ thanh phách mạnh – nhẹ.\n- GV mời HS tự xếp thứ tự thẻ to – nhỏ mới, cả lớp vỗ theo bạn.","hs":"- HS quan sát, vỗ tay theo mẫu.\n- HS vỗ tay, gõ phách to – nhỏ đúng hình.\n- HS xếp thẻ mới, cả lớp vỗ theo bạn."},{"ten":"4. Vận dụng — Hát và vận động theo ý thích","gv":"- GV bắt nhịp hát bài Lớp Một thân yêu: GV giơ tay cao – hát to, hạ tay – hát nhỏ.\n- GV mở bài Những bông hoa những bài ca, HS nghe và vận động theo ý thích, thể hiện cao – thấp bằng động tác (kiễng chân, ngồi xổm).\n- GV nhận xét, khen HS có cách thể hiện sáng tạo.","hs":"- HS hát to – nhỏ theo tay GV.\n- HS vận động theo nhạc, kiễng chân khi nhạc cao, ngồi thấp khi nhạc thấp.\n- HS lắng nghe nhận xét."},{"ten":"5. Tích hợp Năng lực số & AI","gv":"- (Miền 1: Khai thác dữ liệu và thông tin — Cơ bản, bậc 1) GV mở ứng dụng ghi âm có hình sóng âm trên màn hình, cho cả lớp đọc “la” to rồi nhỏ; HS nhìn sóng âm lớn – nhỏ để nhận ra âm thanh to – nhỏ; GV chiếu tiếp hình chim hót (cao) và tiếng trống (thấp) từ học liệu số, bật âm mẫu.\n- (Miền 3: Sáng tạo nội dung số — Cơ bản, bậc 1) GV ghi âm một nhóm đọc câu nhạc Đô – Rê – Mi to – nhỏ theo hình, mở lại qua loa; cả lớp nghe và nói bạn đã đọc đúng to – nhỏ chưa; GV thao tác thiết bị, HS chỉ nghe và trả lời.\n⚠ (Miền 4: An toàn) Không để HS hét quá to vào micro; loa mở vừa đủ nghe, không để sát tai; âm mẫu lấy từ học liệu bộ sách; bản ghi âm chỉ dùng trong lớp.","hs":"- HS đọc “la” to – nhỏ, nhìn sóng âm trên màn hình và nói khi nào âm to, khi nào âm nhỏ; nghe âm mẫu và nói âm nào cao, âm nào thấp.\n- HS nghe lại bản ghi của nhóm bạn, nhận xét bạn đã đọc đúng to – nhỏ theo hình chưa."}],"status":"checked","source":"KHBD Âm nhạc 1 KNTT (Bút Xanh, theo SGV) — Tiết 12"},
{"lop":1,"mon":"Âm nhạc","tuan":13,"tiet":13,"bai":"Chủ đề 4: Vòng tay bè bạn — Học hát: Chào người bạn mới đến (Lương Bằng Vinh)","yccd":"1. Năng lực âm nhạc\n- Nhớ tên bài hát, tên tác giả; hát đúng giai điệu, rõ lời bài Chào người bạn mới đến.\n- Bước đầu cảm nhận tính chất vui tươi, thân thiện của bài hát.\n- Biết hát kết hợp vỗ tay theo phách và động tác chào, bắt tay bạn.\n2. Năng lực chung\n- Tự chủ và tự học: mạnh dạn hát trước lớp.\n- Giao tiếp và hợp tác: biết hát cùng bạn, thể hiện thái độ thân thiện khi lớp có bạn mới.\n3. Phẩm chất\n- Nhân ái: yêu quý, đoàn kết, biết chào đón bạn bè.\n4. Tích hợp\n- Năng lực số 3.3 CB1a: Xác định được các quy tắc đơn giản về bản quyền và giấy phép áp dụng cho dữ liệu, thông tin và nội dung số: HS nói được tên bài hát và tên tác giả Lương Bằng Vinh.","dodung":"- Giáo viên: đàn Organ (hoặc nhạc đệm), loa, bản hát mẫu từ học liệu số, tranh minh hoạ các bạn nhỏ chào đón bạn mới, thanh phách, thiết bị trình chiếu.\n- Học sinh: SGK Âm nhạc 1, thanh phách.","hoatdong":[{"ten":"1. Khởi động","gv":"- GV cho HS xem tranh các bạn nhỏ nắm tay chào một bạn mới và hỏi: Khi lớp có bạn mới, em sẽ làm gì?\n- GV cho HS đứng dậy, quay sang bạn bên cạnh chào và bắt tay theo nhịp vỗ tay của GV.","hs":"- HS quan sát, trả lời: chào bạn, làm quen, rủ bạn cùng chơi.\n- HS chào, bắt tay bạn theo nhịp."},{"ten":"2. Khám phá — Học hát Chào người bạn mới đến","gv":"- GV giới thiệu tên bài hát và tác giả Lương Bằng Vinh; mở bản hát mẫu 1–2 lần, hỏi HS bài hát vui hay buồn.\n- GV chia bài thành các câu ngắn, đọc lời ca từng câu cho HS đọc theo.\n- GV đàn giai điệu và hát mẫu từng câu, bắt nhịp cho HS hát nối tiếp câu 1, câu 2… đến hết bài; sửa chỗ hát chưa đúng cao độ và chỗ lấy hơi.","hs":"- HS nhắc lại tên bài, tên tác giả; nghe và nêu cảm nhận: bài hát vui.\n- HS đọc lời ca theo GV.\n- HS hát từng câu theo đàn, hát nối các câu thành bài."},{"ten":"3. Luyện tập","gv":"- GV cho HS hát cả bài theo nhạc đệm; hát theo dãy, tổ, cá nhân; nhắc hát rõ lời, gương mặt tươi vui.\n- GV hướng dẫn hát kết hợp vỗ tay theo phách, sau đó gõ thanh phách.","hs":"- HS hát cả bài theo nhạc đệm; hát theo dãy, tổ, xung phong hát cá nhân.\n- HS hát kết hợp vỗ tay, gõ thanh phách theo phách."},{"ten":"4. Vận dụng","gv":"- GV hướng dẫn HS đứng thành vòng tròn, vừa hát vừa làm động tác chào, bắt tay bạn bên cạnh.\n- GV mời 1–2 nhóm biểu diễn; dặn HS về hát cho người thân nghe và hát khi chào đón bạn mới.","hs":"- HS đứng vòng tròn, hát kết hợp động tác chào, bắt tay.\n- Nhóm HS biểu diễn; HS ghi nhớ nhiệm vụ."},{"ten":"5. Tích hợp Năng lực số & AI","gv":"- (Miền 1: Khai thác dữ liệu và thông tin — Cơ bản, bậc 1) GV mở bản hát mẫu bài “Chào người bạn mới đến” từ học liệu số, chiếu màn hình có tên bài và tên tác giả Lương Bằng Vinh; GV mở từng câu ngắn, dừng cho HS nghe rồi hát nối tiếp; câu nào chưa đúng thì mở lại câu đó.\n- (Miền 2: Giao tiếp và hợp tác trong môi trường số — Cơ bản, bậc 1) GV dùng điện thoại quay đoạn cả lớp hát kết hợp động tác chào bạn, mở lại trên màn hình để HS xem; GV nói sẽ gửi đoạn quay vào nhóm Zalo của lớp cho cha mẹ xem khi được đồng ý; HS nói lời chào muốn gửi tới cha mẹ; GV thao tác thiết bị, HS không dùng điện thoại.\n⚠ (Miền 4: An toàn) Bản hát mẫu lấy từ học liệu của bộ sách hoặc kênh chính thức, nêu rõ tên tác giả; đoạn quay chỉ gửi vào nhóm lớp khi cha mẹ đồng ý, không đăng công khai; loa mở vừa đủ nghe.","hs":"- HS nghe bản hát mẫu, nói được tên bài hát và tên tác giả Lương Bằng Vinh, hát nối tiếp đúng từng câu.\n- HS xem lại đoạn quay của lớp, nói một lời chào ngắn muốn gửi tới cha mẹ qua nhóm lớp."}],"status":"checked","source":"KHBD Âm nhạc 1 KNTT (Bút Xanh, theo SGV) — Tiết 13"},
{"lop":1,"mon":"Âm nhạc","tuan":14,"tiet":14,"bai":"Chủ đề 4: Vòng tay bè bạn — Ôn bài hát Chào người bạn mới đến; Nhạc cụ: Trống con gõ đệm","yccd":"1. Năng lực âm nhạc\n- Hát thuộc lời, đúng giai điệu bài Chào người bạn mới đến; hát kết hợp vận động.\n- Nhớ cách cầm trống con và dùi; gõ được hình tiết tấu đơn giản (đen – đen – trắng; đen – đen – đen – lặng) bằng trống con.\n- Biết gõ trống con đệm theo phách cho bài hát cùng các bạn.\n2. Năng lực chung\n- Tự chủ và tự học: tự tập gõ tiết tấu theo mẫu.\n- Giao tiếp và hợp tác: phối hợp nhóm hát – nhóm gõ đệm đúng lượt.\n3. Phẩm chất\n- Trách nhiệm: giữ gìn nhạc cụ, không gõ khi chưa có hiệu lệnh.\n4. Tích hợp\n- Năng lực số 1.1 CB1a: Tìm được thông tin đơn giản theo hướng dẫn: HS xem video ngắn và nói lại được cách cầm dùi, cách gõ trống con.","dodung":"- Giáo viên: đàn Organ (hoặc nhạc đệm), loa, trống con và dùi, bảng hình tiết tấu (đen – đen – trắng; đen – đen – đen – lặng), video ngắn cách gõ trống con từ học liệu số, thiết bị trình chiếu.\n- Học sinh: SGK Âm nhạc 1, trống con (hoặc thanh phách, hộp gõ tự tạo).","hoatdong":[{"ten":"1. Khởi động","gv":"- GV gõ trống con theo tiết tấu câu đầu bài Chào người bạn mới đến, HS đoán tên bài hát.\n- GV bắt nhịp cho cả lớp hát 1 lần theo nhạc đệm.","hs":"- HS nghe tiết tấu, đoán tên bài hát.\n- HS hát cùng nhạc đệm."},{"ten":"2. Ôn bài hát Chào người bạn mới đến","gv":"- GV cho HS hát cả bài theo nhạc đệm, sửa chỗ hát sai lời, sai cao độ; nhắc thể hiện nét mặt vui tươi.\n- GV cho HS hát nối tiếp theo dãy, hát kết hợp động tác chào, bắt tay bạn đã học.\n- GV mời 1–2 HS hát đơn ca, một nhóm hát tốp ca; cả lớp nhận xét bằng cách vỗ tay.","hs":"- HS hát cả bài, sửa chỗ GV nhắc.\n- HS hát nối tiếp theo dãy kết hợp động tác.\n- HS xung phong hát đơn ca, tốp ca; cả lớp vỗ tay khen bạn."},{"ten":"3. Nhạc cụ: Trống con gõ theo hình tiết tấu","gv":"- GV cho HS nhắc lại cách cầm trống con và dùi (tay trái giữ trống, tay phải cầm dùi, gõ vào mặt trống), làm mẫu lại.\n- GV treo hình tiết tấu 1 (đen – đen – trắng), đọc mẫu “ta – ta – ta-a” rồi gõ; HS đọc và gõ theo; tương tự với hình tiết tấu 2 (đen – đen – đen – lặng: “ta – ta – ta – nghỉ”).\n- GV cho HS gõ theo nhóm luân phiên, nhóm không có trống gõ thanh phách hoặc vỗ tay; sửa những em gõ dồn, gõ quá mạnh.","hs":"- HS nhắc lại cách cầm trống, cầm dùi; quan sát mẫu.\n- HS đọc tiết tấu bằng âm “ta”, gõ theo hình tiết tấu 1 rồi hình tiết tấu 2.\n- HS gõ theo nhóm, đổi nhạc cụ; sửa theo GV nhắc."},{"ten":"4. Vận dụng — Gõ đệm trống con cho bài hát","gv":"- GV hát và gõ trống con đệm theo phách bài Chào người bạn mới đến làm mẫu.\n- GV chia lớp: nhóm hát – nhóm gõ trống theo phách – nhóm gõ thanh phách; đổi vai sau mỗi lượt.\n- GV mời nhóm biểu diễn hát kết hợp gõ đệm; nhận xét, khen ngợi; nhắc HS cất trống đúng chỗ.","hs":"- HS quan sát mẫu.\n- HS hát và gõ đệm theo phách theo nhóm, đổi vai.\n- Nhóm HS biểu diễn; HS cất nhạc cụ gọn gàng."},{"ten":"5. Tích hợp Năng lực số & AI","gv":"- (Miền 1: Khai thác dữ liệu và thông tin — Cơ bản, bậc 1) GV mở video ngắn từ học liệu số giới thiệu cách cầm và gõ trống con, dừng hình ở tư thế cầm dùi để HS nhìn rõ và làm theo; GV bật âm thanh trống con thu sẵn, HS nghe và nói đó là tiếng trống con.\n- (Miền 3: Sáng tạo nội dung số — Cơ bản, bậc 1) GV dùng điện thoại ghi âm phần cả lớp hát kết hợp gõ trống đệm theo phách, mở lại qua loa; HS nghe và nói tiếng trống đã đều với nhịp hát chưa; GV thao tác thiết bị, HS chỉ nghe và nhận xét.\n⚠ (Miền 4: An toàn) Video và âm thanh mẫu lấy từ học liệu của bộ sách; loa mở vừa đủ nghe, không gõ trống sát tai bạn; bản ghi âm chỉ dùng trong lớp, không đăng lên mạng.","hs":"- HS xem video, làm lại đúng tư thế cầm trống, cầm dùi; nghe và nhận ra tiếng trống con.\n- HS nghe lại bản ghi âm của lớp, nói tiếng trống đã đều theo phách chưa và gõ lại cho đúng."}],"status":"checked","source":"KHBD Âm nhạc 1 KNTT (Bút Xanh, theo SGV) — Tiết 14"},
{"lop":1,"mon":"Âm nhạc","tuan":15,"tiet":15,"bai":"Chủ đề 4: Vòng tay bè bạn — Thường thức âm nhạc: Trống cái; Nghe nhạc: Vũ khúc thiên nga (Trai-cốp-xki)","yccd":"1. Năng lực âm nhạc\n- Nhận biết trống cái qua hình dáng (to, tròn, mặt bịt da, đặt trên giá), âm thanh (trầm, vang xa) và nơi thường dùng (trường học, lễ hội, đình làng).\n- Biết gõ và đọc theo hình tiết tấu đơn giản, mô phỏng tiếng trống trường bằng âm “tùng”.\n- Biết lắng nghe trích đoạn Vũ khúc thiên nga; nêu cảm nhận đơn giản (nhẹ nhàng, êm ái) và vận động tay mềm mại theo nhạc.\n2. Năng lực chung\n- Tự chủ và tự học: tập trung lắng nghe, nói được điều mình cảm nhận.\n- Giao tiếp và hợp tác: cùng bạn gõ tiết tấu, vận động theo nhạc.\n3. Phẩm chất\n- Yêu nước: trân trọng nhạc cụ dân tộc; biết giữ trật tự khi nghe hiệu lệnh trống trường.\n4. Tích hợp\n- Năng lực số 1.1 CB1a: Tìm được thông tin đơn giản theo hướng dẫn: HS xem hình, nghe âm thanh trên màn hình và nói được đó là trống cái hay trống con.","dodung":"- Giáo viên: hình ảnh, video trống cái ở trường học và lễ hội, bản thu tiếng trống cái, trống con, bảng hình tiết tấu, bản thu trích đoạn Vũ khúc thiên nga (học liệu số), hình ảnh thiên nga bơi trên hồ, loa, thiết bị trình chiếu.\n- Học sinh: SGK Âm nhạc 1, trống con hoặc thanh phách.","hoatdong":[{"ten":"1. Khởi động","gv":"- GV mở bản thu tiếng trống trường và hỏi: Đây là tiếng gì? Các em nghe thấy tiếng này khi nào?\n- GV cho HS bắt chước tiếng trống bằng miệng “tùng… tùng…” theo nhịp tay GV.","hs":"- HS nghe, trả lời: tiếng trống trường, nghe lúc vào lớp, ra chơi.\n- HS bắt chước tiếng trống theo nhịp."},{"ten":"2. Thường thức âm nhạc: Trống cái","gv":"- GV chiếu hình trống cái, giới thiệu: trống to, thân gỗ, mặt bịt da, đặt trên giá, gõ bằng dùi to; tiếng trống trầm, vang xa.\n- GV chiếu hình trống cái ở trường học (trống báo giờ), ở lễ hội, đình làng; hỏi HS đã thấy trống cái ở đâu.\n- GV đặt trống con cạnh hình trống cái, gõ cho HS nghe để so sánh to – nhỏ, tiếng trầm – cao.","hs":"- HS quan sát, nhắc lại đặc điểm trống cái.\n- HS kể nơi đã thấy trống cái: ở trường, lễ hội, múa lân.\n- HS so sánh: trống cái to hơn, tiếng trầm hơn trống con."},{"ten":"3. Gõ và đọc theo hình tiết tấu","gv":"- GV treo hình tiết tấu (đen – đen – trắng), đọc mẫu bằng âm “tùng – tùng – tùng-g” và gõ trống con theo.\n- GV cho HS đọc và vỗ tay theo hình tiết tấu, sau đó gõ trống con hoặc thanh phách; chia nhóm gõ nối tiếp như “trống trường – trống hội”.\n- GV mời 1 HS lên gõ trống làm “bác bảo vệ đánh trống trường”, cả lớp đọc theo.","hs":"- HS nghe mẫu, đọc “tùng” theo hình tiết tấu.\n- HS vỗ tay, gõ nhạc cụ theo hình tiết tấu, gõ nối tiếp theo nhóm.\n- HS xung phong gõ trống, cả lớp đọc theo bạn."},{"ten":"4. Nghe nhạc: Vũ khúc thiên nga","gv":"- GV chiếu hình thiên nga bơi trên hồ, giới thiệu trích đoạn Vũ khúc thiên nga của nhạc sĩ Trai-cốp-xki, nhạc múa ba lê Hồ thiên nga.\n- GV mở bản thu lần 1, HS nhắm mắt lắng nghe; hỏi: Nhạc nhanh hay chậm? Nhẹ nhàng hay mạnh mẽ?\n- GV mở lần 2, làm mẫu động tác tay mềm mại như cánh thiên nga, HS vận động theo; nhận xét, khen ngợi.","hs":"- HS quan sát hình, nhắc lại tên bản nhạc, tên nhạc sĩ.\n- HS nghe, trả lời: nhạc chậm, nhẹ nhàng, êm ái.\n- HS vận động tay mềm mại theo nhạc cùng GV và bạn."},{"ten":"5. Tích hợp Năng lực số & AI","gv":"- (Miền 1: Khai thác dữ liệu và thông tin — Cơ bản, bậc 1) GV chiếu hình và video ngắn trống cái ở trường học, lễ hội lấy từ học liệu số, bật lần lượt tiếng trống cái và tiếng trống con thu sẵn để HS nghe và chỉ vào hình đúng nhạc cụ; GV chiếu tên bản nhạc “Vũ khúc thiên nga” và tên nhạc sĩ Trai-cốp-xki khi mở nhạc.\n- (Miền 6: Ứng dụng trí tuệ nhân tạo — Cơ bản, bậc 1) GV chuẩn bị trước một đoạn giới thiệu ngắn 2–3 câu về đàn thiên nga trong vở ba lê Hồ thiên nga do trợ lí AI đọc bằng giọng tiếng Việt; GV kiểm tra nội dung trước, mở cho HS nghe rồi hỏi lại: Thiên nga múa ở đâu? Nhạc nghe thế nào?\n⚠ (Miền 4: An toàn) Hình, video, bản thu lấy từ học liệu của bộ sách hoặc kênh chính thức; nội dung do AI đọc phải được GV xem trước, HS không tự dùng trợ lí AI; loa mở vừa đủ nghe, tiếng trống không bật quá to.","hs":"- HS xem hình, nghe âm thanh và chỉ đúng hình trống cái, trống con; nói được tên bản nhạc và tên nhạc sĩ Trai-cốp-xki.\n- HS nghe đoạn giới thiệu do AI đọc, trả lời được thiên nga múa trên hồ, nhạc nhẹ nhàng."}],"status":"checked","source":"KHBD Âm nhạc 1 KNTT (Bút Xanh, theo SGV) — Tiết 15"},
{"lop":1,"mon":"Âm nhạc","tuan":16,"tiet":16,"bai":"Chủ đề 4: Vòng tay bè bạn — Ôn tập cuối học kì I","yccd":"1. Năng lực âm nhạc\n- Hát thuộc, đúng giai điệu 4 bài hát đã học: Vào rừng hoa, Tổ quốc ta, Lớp Một thân yêu, Chào người bạn mới đến; nhìn tranh nói được tên bài hát.\n- Đọc đúng 2 bài đọc nhạc Bậc thang Đô – Rê – Mi và Ban nhạc Đô – Rê – Mi theo kí hiệu bàn tay.\n- Gõ đúng mẫu tiết tấu 1 và 2 bằng trống con, thanh phách; biết trình bày theo hình thức đồng ca, tốp ca, song ca, đơn ca kết hợp gõ đệm hoặc vận động.\n2. Năng lực chung\n- Tự chủ và tự học: tự chọn bài và hình thức trình bày.\n- Giao tiếp và hợp tác: phối hợp với bạn trong tốp ca, song ca.\n3. Phẩm chất\n- Chăm chỉ, tự tin; tôn trọng, cổ vũ phần trình bày của bạn.\n4. Tích hợp\n- Năng lực số 1.1 CB1a: Tìm được thông tin đơn giản theo hướng dẫn: HS nhìn tranh và nghe đoạn nhạc trên màn hình để nói tên bài hát.","dodung":"- Giáo viên: đàn Organ, loa, nhạc đệm 4 bài hát học kì I, tranh minh hoạ 4 bài hát, bảng hình tiết tấu 1 và 2, thẻ kí hiệu bàn tay Đô – Rê – Mi, trống con, thanh phách, bản thu một số âm thanh (chim hót, mưa, trống, đàn) cho trò chơi, thiết bị trình chiếu.\n- Học sinh: SGK Âm nhạc 1, thanh phách hoặc trống con.","hoatdong":[{"ten":"1. Khởi động — Trò chơi “Vũ điệu âm thanh”","gv":"- GV mở lần lượt các âm thanh (tiếng chim, tiếng mưa, tiếng trống, tiếng đàn); mỗi âm thanh HS thể hiện một động tác (vẫy cánh, xoè tay làm mưa rơi, gõ trống, gảy đàn).\n- GV đổi nhanh âm thanh, HS đổi động tác; khen nhóm phản ứng nhanh, đúng.","hs":"- HS nghe, làm động tác tương ứng với từng âm thanh.\n- HS đổi động tác theo âm thanh, vui vẻ tham gia."},{"ten":"2. Ôn tập: Gõ theo mẫu tiết tấu 1 và 2","gv":"- GV treo hình tiết tấu 1 (đen – đen – trắng) và tiết tấu 2 (đen – đen – đen – lặng), đọc mẫu và gõ mẫu.\n- GV cho HS gõ từng mẫu bằng trống con và thanh phách; nhóm trống gõ mẫu 1, nhóm phách gõ mẫu 2 rồi đổi lại.\n- GV ghép hai mẫu nối tiếp nhau và cho cả lớp gõ theo nhịp đàn.","hs":"- HS đọc và vỗ tay theo mẫu.\n- HS gõ nhạc cụ theo nhóm, đổi mẫu.\n- HS gõ nối tiếp mẫu 1 – mẫu 2 theo nhịp đàn."},{"ten":"3. Ôn tập: Xem tranh kể tên bài hát và ôn 4 bài hát","gv":"- GV chiếu lần lượt 4 tranh minh hoạ, HS nói tên bài hát và tác giả; GV đàn một câu ngắn để gợi ý nếu HS chưa nhớ.\n- GV cho cả lớp hát đồng ca từng bài theo nhạc đệm, kết hợp gõ đệm theo phách hoặc vận động đã học.\n- GV mời các nhóm tự chọn bài và hình thức: tốp ca, song ca, đơn ca; GV góp ý về lời, cao độ và sự tự tin.","hs":"- HS xem tranh, nói tên bài hát, tác giả.\n- HS hát đồng ca 4 bài kết hợp gõ đệm hoặc vận động.\n- Nhóm HS chọn bài, trình bày tốp ca, song ca, đơn ca."},{"ten":"4. Ôn tập: Đọc nhạc Bậc thang Đô – Rê – Mi và Ban nhạc Đô – Rê – Mi","gv":"- GV đàn cao độ Đô – Rê – Mi, HS đọc kết hợp kí hiệu bàn tay đi lên, đi xuống.\n- GV cho HS đọc 2 bài đọc nhạc theo đàn: cả lớp rồi theo nhóm; sửa chỗ đọc chưa đúng cao độ.\n- GV chơi trò “Nhìn tay đọc nốt” với một số HS cá nhân.","hs":"- HS đọc Đô – Rê – Mi kết hợp kí hiệu bàn tay.\n- HS đọc 2 bài theo đàn, theo nhóm.\n- HS nhìn tay GV đọc nốt."},{"ten":"5. Vận dụng — Chuẩn bị cho tiết đánh giá","gv":"- GV giới thiệu tiết sau mỗi em hoặc mỗi nhóm chọn một nội dung yêu thích (hát, đọc nhạc, gõ đệm, vận động) để trình bày.\n- GV cho HS đăng kí nhóm và nội dung, dặn tập luyện ở nhà.","hs":"- HS lắng nghe, chọn nội dung mình thích.\n- HS đăng kí nhóm, ghi nhớ nhiệm vụ."},{"ten":"6. Tích hợp Năng lực số & AI","gv":"- (Miền 1: Khai thác dữ liệu và thông tin — Cơ bản, bậc 1) GV chiếu lần lượt tranh 4 bài hát kèm đoạn nhạc dạo ngắn từ học liệu số; HS nhìn tranh, nghe nhạc và nói tên bài hát, tên tác giả; GV mở tiếp hình 2 mẫu tiết tấu và âm gõ mẫu để HS gõ theo.\n- (Miền 3: Sáng tạo nội dung số — Cơ bản, bậc 1) GV dùng điện thoại quay phần trình bày tốp ca, song ca của các nhóm, mở lại trên màn hình để HS tự xem và nói mình cần sửa gì trước tiết đánh giá; GV thao tác thiết bị, HS chỉ xem và nhận xét.\n⚠ (Miền 4: An toàn) Nhạc, tranh lấy từ học liệu của bộ sách; đoạn quay chỉ dùng trong lớp, không đăng lên mạng khi chưa được cha mẹ đồng ý; loa mở vừa đủ nghe.","hs":"- HS nhìn tranh, nghe nhạc dạo và nói đúng tên 4 bài hát cùng tác giả; gõ theo mẫu tiết tấu hiện trên màn hình.\n- HS xem lại đoạn quay của nhóm, nói một điều cần sửa (hát rõ lời, gõ đều, đứng thẳng) để chuẩn bị cho tiết đánh giá."}],"status":"checked","source":"KHBD Âm nhạc 1 KNTT (Bút Xanh, theo SGV) — Tiết 16"},
{"lop":1,"mon":"Âm nhạc","tuan":17,"tiet":17,"bai":"Chủ đề 4: Vòng tay bè bạn — Đánh giá cuối học kì I","yccd":"1. Năng lực âm nhạc\n- Tự chọn và trình bày được một nội dung đã học trong học kì I (hát, đọc nhạc, gõ đệm, vận động) trước lớp một cách tự tin.\n- Hát đúng giai điệu, rõ lời; đọc đúng cao độ Đô – Rê – Mi; gõ đúng mẫu tiết tấu.\n- Biết lắng nghe, nhận xét đơn giản phần trình bày của bạn.\n2. Năng lực chung\n- Tự chủ và tự học: tự tin trình bày, tự đánh giá mình đã làm được gì.\n- Giao tiếp và hợp tác: phối hợp nhóm khi trình bày, cổ vũ bạn.\n3. Phẩm chất\n- Trung thực khi tự nhận xét; tôn trọng bạn.\n4. Tích hợp\n- Năng lực số 4.1 CB1a: Sử dụng thiết bị số an toàn theo hướng dẫn: HS đứng đúng vị trí trước máy quay, micro; không tự chạm vào thiết bị.","dodung":"- Giáo viên: đàn Organ, loa, nhạc đệm các bài hát học kì I, thẻ kí hiệu bàn tay, hình tiết tấu, trống con, thanh phách, bảng theo dõi đánh giá 3 mức Biết – Hiểu – Vận dụng, phiếu mặt cười, thiết bị trình chiếu.\n- Học sinh: SGK Âm nhạc 1, nhạc cụ gõ đã chuẩn bị.","hoatdong":[{"ten":"1. Khởi động","gv":"- GV cho cả lớp hát chung bài Chào người bạn mới đến kết hợp vỗ tay theo phách để tạo không khí vui tươi.\n- GV nêu cách làm việc: từng nhóm hoặc cá nhân lên trình bày nội dung đã chọn, các bạn khác lắng nghe và vỗ tay; GV nhận xét, không cho điểm.","hs":"- HS hát chung, vỗ tay theo phách.\n- HS lắng nghe, nhắc lại nhiệm vụ."},{"ten":"2. Chuẩn bị trình bày","gv":"- GV cho các nhóm 3–5 phút ôn lại nội dung đã đăng kí (hát, đọc nhạc, gõ đệm hay vận động); phát nhạc cụ theo nhu cầu.\n- GV đi từng nhóm, gợi ý cách đứng, cách bắt nhịp; nhắc nhóm hát chọn một hình thức: đơn ca, song ca hoặc tốp ca.","hs":"- HS ôn lại theo nhóm, nhận nhạc cụ.\n- HS nghe gợi ý, thống nhất trong nhóm ai hát, ai gõ đệm."},{"ten":"3. Trình bày và đánh giá","gv":"- GV mời lần lượt từng nhóm hoặc cá nhân lên trình bày; đệm đàn hoặc mở nhạc đệm phù hợp; cả lớp vỗ tay theo phách cổ vũ.\n- Sau mỗi phần, GV hỏi 1–2 HS: Bạn hát, đọc, gõ có đúng không? Em thích điều gì ở phần trình bày của bạn?\n- GV nhận xét ngắn theo 3 mức: Biết (nhớ tên bài, hát, đọc, gõ được theo GV), Hiểu (hát đúng giai điệu, đọc đúng nốt, gõ đúng mẫu), Vận dụng (trình bày tự tin, kết hợp gõ đệm hoặc vận động phù hợp); ghi vào bảng theo dõi, không cho điểm.","hs":"- HS lên trình bày nội dung đã chọn; HS dưới lớp vỗ tay theo phách.\n- HS nhận xét bạn bằng câu ngắn.\n- HS lắng nghe nhận xét của GV."},{"ten":"4. Vận dụng — Tự đánh giá và tổng kết","gv":"- GV cho HS tự đánh giá bằng phiếu mặt cười: giơ mặt cười to nếu thấy mình làm tốt, mặt cười nhỏ nếu cần tập thêm.\n- GV khen ngợi cả lớp, nêu điều tiến bộ chung, gợi ý nội dung cần tập thêm trong học kì II; dặn HS hát cho gia đình nghe.","hs":"- HS tự đánh giá bằng phiếu mặt cười.\n- HS lắng nghe, vỗ tay chúc mừng nhau."},{"ten":"5. Tích hợp Năng lực số & AI","gv":"- (Miền 3: Sáng tạo nội dung số — Cơ bản, bậc 1) GV dùng điện thoại quay phần trình bày của từng nhóm, cuối tiết mở lại vài đoạn tiêu biểu trên màn hình để HS xem lại và nói mình đã đạt mức Biết, Hiểu hay Vận dụng; GV lưu đoạn quay làm minh chứng đánh giá; GV thao tác thiết bị, HS chỉ xem và trả lời.\n- (Miền 2: Giao tiếp và hợp tác trong môi trường số — Cơ bản, bậc 1) GV cho HS biết đoạn quay phần trình bày sẽ được gửi vào nhóm Zalo của lớp cho cha mẹ xem khi được đồng ý; HS nói một câu ngắn muốn nhắn cha mẹ về tiết học.\n⚠ (Miền 4: An toàn) HS đứng đúng vị trí, không tự cầm điện thoại, micro; đoạn quay chỉ lưu trong hồ sơ lớp và gửi nhóm cha mẹ khi được đồng ý, không đăng công khai; loa mở vừa đủ nghe.","hs":"- HS xem lại đoạn quay của nhóm mình, nói mình đạt mức nào và cần tập thêm gì.\n- HS nói một câu ngắn muốn nhắn cha mẹ về phần trình bày; HS đứng đúng vị trí, không chạm vào thiết bị."}],"status":"checked","source":"KHBD Âm nhạc 1 KNTT (Bút Xanh, theo SGV) — Tiết 17"},
{"lop":1,"mon":"Âm nhạc","tuan":18,"tiet":18,"bai":"Chủ đề 5: Nhịp điệu mùa xuân — Học hát: Xúc xắc xúc xẻ (Nhạc: Nguyễn Ngọc Thiện, lời: phỏng theo đồng dao)","yccd":"1. Năng lực âm nhạc\n- Nhớ tên bài hát, hát rõ lời, đúng giai điệu bài Xúc xắc xúc xẻ.\n- Bước đầu cảm nhận tính chất vui tươi, rộn ràng của bài hát gắn với không khí ngày Tết.\n- Biết hát kết hợp vỗ tay hoặc gõ đệm theo phách.\n2. Năng lực chung\n- Tự chủ và tự học: mạnh dạn hát theo GV, tự tập lại câu hát còn chưa thuộc.\n- Giao tiếp và hợp tác: biết hát hòa giọng, hát nối tiếp cùng các bạn.\n3. Phẩm chất\n- Yêu quý phong tục đón Tết của quê hương, vui vẻ chúc Tết ông bà, cha mẹ.\n4. Tích hợp\n- Năng lực số 3.3 CB1a: Xác định được các quy tắc đơn giản về bản quyền và giấy phép áp dụng cho dữ liệu, thông tin và nội dung số: HS nói được tên bài hát cùng tên tác giả phần nhạc và nguồn lời ca phỏng theo đồng dao.","dodung":"- Giáo viên: đàn Organ (hoặc file nhạc đệm), loa, tranh cảnh ngày Tết (bánh chưng, hoa đào, hoa mai, trẻ em chúc Tết), thanh phách, thiết bị trình chiếu mở học liệu số.\n- Học sinh: SGK Âm nhạc 1, thanh phách (hoặc nhạc cụ gõ tự tạo).","hoatdong":[{"ten":"1. Khởi động","gv":"- GV cho HS xem tranh cảnh ngày Tết và hỏi: Trong tranh có gì? Ngày Tết các em thường làm gì cùng gia đình?\n- GV cho HS nghe một đoạn nhạc rộn ràng, cả lớp vỗ tay theo phách rồi dẫn vào bài hát Xúc xắc xúc xẻ.","hs":"- HS quan sát tranh, trả lời: bánh chưng, hoa đào, đi chúc Tết ông bà...\n- HS vỗ tay theo nhạc, lắng nghe GV giới thiệu bài."},{"ten":"2. Khám phá — Nghe và học hát","gv":"- GV mở bản hát mẫu từ học liệu số cho HS nghe 1–2 lần, giới thiệu tác giả phần nhạc là nhạc sĩ Nguyễn Ngọc Thiện, lời ca phỏng theo bài đồng dao trẻ em thường đọc khi đi chúc Tết.\n- GV đọc lời ca theo tiết tấu, chia bài thành 4–5 câu ngắn, cho HS đọc theo từng câu.\n- GV đàn giai điệu, hát mẫu từng câu và bắt nhịp cho HS hát nối tiếp câu 1, câu 2... đến hết bài; chú ý những tiếng hát nhanh, gọn.","hs":"- HS lắng nghe, nói tên bài hát, nêu cảm nhận: bài hát vui, rộn ràng.\n- HS đọc lời ca từng câu theo GV.\n- HS tập hát từng câu, hát nối các câu thành cả bài."},{"ten":"3. Luyện tập","gv":"- GV cho HS hát cả bài theo nhạc đệm, nghe và sửa những tiếng hát chưa rõ, chưa đúng cao độ.\n- GV làm mẫu hát kết hợp vỗ tay theo phách, sau đó cho HS thay bằng gõ thanh phách.\n- GV cho HS hát theo dãy, theo tổ, hát nối tiếp từng câu giữa các tổ.","hs":"- HS hát cả bài theo nhạc đệm, hát lại chỗ GV sửa.\n- HS hát kết hợp vỗ tay, gõ thanh phách theo phách.\n- HS hát theo dãy, tổ, hát nối tiếp."},{"ten":"4. Vận dụng","gv":"- GV mời vài nhóm/cá nhân lên hát trước lớp kết hợp gõ đệm, khen ngợi HS hát tự tin.\n- GV hỏi: Bài hát nói về ngày gì? Các em sẽ hát bài này cho ai nghe trong dịp Tết?\n- GV dặn HS về nhà hát cho ông bà, bố mẹ nghe.","hs":"- HS xung phong biểu diễn, các bạn khác vỗ tay cổ vũ.\n- HS trả lời: bài hát về ngày Tết, sẽ hát khi chúc Tết ông bà...\n- HS ghi nhớ nhiệm vụ."},{"ten":"5. Tích hợp Năng lực số & AI","gv":"- (Miền 1: Khai thác dữ liệu và thông tin — Cơ bản, bậc 1) GV mở bản hát mẫu bài “Xúc xắc xúc xẻ” từ học liệu số, chiếu màn hình có tên bài, tên tác giả phần nhạc Nguyễn Ngọc Thiện và dòng chữ “lời phỏng theo đồng dao”; GV mở từng câu ngắn, dừng cho HS nghe rồi hát nối tiếp, câu nào chưa đúng thì mở lại câu đó.\n- (Miền 3: Sáng tạo nội dung số — Cơ bản, bậc 1) GV dùng điện thoại ghi âm cả lớp hát kết hợp gõ đệm theo phách rồi mở lại qua loa; HS nghe và chỉ ra chỗ hát chưa đều, chưa rõ lời; GV thao tác thiết bị, HS chỉ nghe và nhận xét.\n⚠ (Miền 4: An toàn) Bản thu chỉ lấy từ học liệu của bộ sách hoặc kênh chính thức, không tải nhạc từ trang lạ vì có thể sai lời, kèm quảng cáo không phù hợp; giới thiệu bài phải nói rõ tên tác giả; mở loa vừa đủ nghe.","hs":"- HS nghe bản hát mẫu, nói được tên bài hát “Xúc xắc xúc xẻ” và tên nhạc sĩ Nguyễn Ngọc Thiện, hát đúng lời theo từng câu.\n- HS nghe lại bản ghi âm của lớp, chỉ ra một chỗ hát chưa rõ hoặc gõ đệm chưa đều rồi hát lại."}],"status":"checked","source":"KHBD Âm nhạc 1 KNTT (Bút Xanh, theo SGV) — Tiết 18"},
{"lop":1,"mon":"Âm nhạc","tuan":19,"tiet":19,"bai":"Chủ đề 5: Nhịp điệu mùa xuân — Ôn bài hát Xúc xắc xúc xẻ; Đọc nhạc: Những người bạn của Đô – Rê – Mi","yccd":"1. Năng lực âm nhạc\n- Hát thuộc lời, đúng giai điệu bài Xúc xắc xúc xẻ, biết hát kết hợp gõ đệm và vận động đơn giản.\n- Nhớ tên và làm được kí hiệu bàn tay của hai nốt mới Pha, Son; đọc được bài đọc nhạc Những người bạn của Đô – Rê – Mi theo kí hiệu bàn tay của GV.\n2. Năng lực chung\n- Tự chủ và tự học: tự làm lại kí hiệu bàn tay các nốt đã học.\n- Giao tiếp và hợp tác: biết đọc nhạc nối tiếp, sắm vai cùng bạn trong nhóm.\n3. Phẩm chất\n- Chăm chỉ luyện tập, vui vẻ, đoàn kết với bạn khi hoạt động nhóm.\n4. Tích hợp\n- Năng lực số 1.1 CB1a: Tìm được thông tin đơn giản theo hướng dẫn: HS nhìn hình kí hiệu bàn tay trên màn hình, nói đúng tên nốt Pha, Son.","dodung":"- Giáo viên: đàn Organ (hoặc file nhạc đệm), loa, tranh 5 nốt Đô – Rê – Mi – Pha – Son kèm kí hiệu bàn tay, bảng hình bậc thang 5 nốt, thanh phách, thiết bị trình chiếu.\n- Học sinh: SGK Âm nhạc 1, thanh phách.","hoatdong":[{"ten":"1. Khởi động","gv":"- GV mở nhạc đệm, cả lớp hát bài Xúc xắc xúc xẻ kết hợp vỗ tay theo phách.\n- GV làm kí hiệu bàn tay Đô, Rê, Mi và đàn cao độ, cho HS đọc bằng âm “la” để nhớ lại 3 nốt đã học.","hs":"- HS hát và vỗ tay theo phách.\n- HS nhìn tay GV, đọc Đô – Rê – Mi bằng âm “la” rồi bằng tên nốt."},{"ten":"2. Ôn bài hát Xúc xắc xúc xẻ","gv":"- GV cho HS hát cả bài theo nhạc đệm, sửa những chỗ hát chưa rõ lời, chưa đúng nhịp.\n- GV hướng dẫn hát kết hợp gõ thanh phách theo phách; hướng dẫn vài động tác vận động đơn giản (nhún chân, vẫy tay như đang đi chúc Tết).\n- GV chia lớp thành các tổ hát nối tiếp, sau đó mời nhóm lên biểu diễn.","hs":"- HS hát cả bài, hát lại chỗ được sửa.\n- HS hát kết hợp gõ đệm, vận động theo GV.\n- HS hát nối tiếp theo tổ, nhóm xung phong biểu diễn."},{"ten":"3. Đọc nhạc: Những người bạn của Đô – Rê – Mi","gv":"- GV treo tranh 5 nốt, giới thiệu hai người bạn mới của Đô – Rê – Mi là Pha và Son; GV làm mẫu kí hiệu bàn tay: Pha – bàn tay nắm hờ, ngón cái chỉ xuống; Son – bàn tay mở dựng đứng, lòng bàn tay hướng vào người.\n- GV đàn cao độ từng nốt, cho HS nghe rồi đọc theo bằng âm “la”, sau đó đọc tên nốt kết hợp làm kí hiệu bàn tay; đọc đi lên Đô – Rê – Mi – Pha – Son và đi xuống.\n- GV đọc mẫu bài đọc nhạc theo từng câu ngắn, làm kí hiệu bàn tay chậm để HS đọc theo; ghép các câu thành cả bài.","hs":"- HS quan sát, làm theo kí hiệu bàn tay nốt Pha, Son.\n- HS nghe đàn, đọc cao độ bằng âm “la”, rồi đọc tên nốt kết hợp kí hiệu bàn tay.\n- HS đọc từng câu theo tay GV, đọc cả bài."},{"ten":"4. Vận dụng","gv":"- GV tổ chức trò chơi: GV chỉ làm kí hiệu bàn tay, không đọc; HS nhìn và đọc đúng tên nốt; đổi vai cho một HS làm kí hiệu để cả lớp đọc.\n- GV cho HS đọc bài đọc nhạc theo nhóm, nhóm đọc – nhóm làm kí hiệu bàn tay.\n- GV nhận xét, dặn HS về tập lại 5 kí hiệu bàn tay.","hs":"- HS nhìn tay GV, đọc tên nốt; HS xung phong làm “nhạc trưởng”.\n- HS đọc nhạc theo nhóm, đổi vai.\n- HS ghi nhớ nhiệm vụ."},{"ten":"5. Tích hợp Năng lực số & AI","gv":"- (Miền 1: Khai thác dữ liệu và thông tin — Cơ bản, bậc 1) GV chiếu hình 5 nốt Đô – Rê – Mi – Pha – Son kèm kí hiệu bàn tay trên màn hình, bấm vào từng nốt để phát cao độ; HS nhìn hình, nói tên nốt và làm kí hiệu bàn tay tương ứng; GV thao tác, HS chỉ nhìn và trả lời.\n- (Miền 3: Sáng tạo nội dung số — Cơ bản, bậc 1) GV quay đoạn video ngắn cả lớp đọc bài Những người bạn của Đô – Rê – Mi kết hợp kí hiệu bàn tay, mở lại trên màn hình để HS xem tay mình làm đã đúng chưa.\n⚠ (Miền 4: An toàn) Video của lớp chỉ dùng xem tại lớp, không đăng lên mạng khi chưa được cha mẹ HS đồng ý; hình ảnh, âm thanh lấy từ học liệu bộ sách; HS không tự cầm thiết bị của GV.","hs":"- HS nhìn hình trên màn hình, nói đúng tên nốt Pha, Son và làm kí hiệu bàn tay.\n- HS xem lại video của lớp, nhận ra bạn nào làm kí hiệu chưa đúng và sửa lại cùng nhau."}],"status":"checked","source":"KHBD Âm nhạc 1 KNTT (Bút Xanh, theo SGV) — Tiết 19"},
{"lop":1,"mon":"Âm nhạc","tuan":20,"tiet":20,"bai":"Chủ đề 5: Nhịp điệu mùa xuân — Thường thức âm nhạc: Nhạc sĩ Mô-da (Câu chuyện \"Thần đồng âm nhạc Mô-da\"); Nghe nhạc: Khát vọng mùa xuân","yccd":"1. Năng lực âm nhạc\n- Nhớ tên nhạc sĩ Mô-da, kể lại được 1–2 điều về ông theo câu chuyện: sinh ở nước Áo, biết chơi đàn và sáng tác nhạc từ khi còn rất nhỏ.\n- Nghe và cảm nhận được tính chất nhẹ nhàng, tươi vui của bản nhạc Khát vọng mùa xuân; biết vận động nhịp nhàng theo nhạc.\n2. Năng lực chung\n- Tự chủ và tự học: chăm chú nghe chuyện, nghe nhạc, mạnh dạn nêu cảm nhận.\n- Giao tiếp và hợp tác: biết cùng bạn vận động theo nhạc, trả lời câu hỏi theo nhóm.\n3. Phẩm chất\n- Chăm chỉ, kiên trì luyện tập như tấm gương nhạc sĩ Mô-da; yêu thích âm nhạc.\n4. Tích hợp\n- Năng lực số 1.1 CB1a: Tìm được thông tin đơn giản theo hướng dẫn: HS xem hình, nghe GV giới thiệu và nói được tên nhạc sĩ Mô-da, tên bản nhạc vừa nghe.","dodung":"- Giáo viên: tranh/ảnh chân dung Mô-da và hình cậu bé Mô-da chơi đàn, bản nhạc Khát vọng mùa xuân (file âm thanh), loa, đàn Organ, thiết bị trình chiếu.\n- Học sinh: SGK Âm nhạc 1.","hoatdong":[{"ten":"1. Khởi động","gv":"- GV mở nhạc đệm, cả lớp hát bài Xúc xắc xúc xẻ kết hợp vận động.\n- GV hỏi: Các em có biết ai là người sáng tác ra các bài hát, bản nhạc không? Hôm nay cô/thầy kể cho các em nghe về một cậu bé rất giỏi âm nhạc.","hs":"- HS hát, vận động theo nhạc.\n- HS trả lời theo hiểu biết: nhạc sĩ; lắng nghe GV dẫn vào bài."},{"ten":"2. Thường thức âm nhạc: Nhạc sĩ Mô-da","gv":"- GV chiếu chân dung Mô-da, giới thiệu: Mô-da là nhạc sĩ nổi tiếng thế giới, sinh ở nước Áo; từ khi còn nhỏ ông đã biết chơi đàn rất giỏi và tự sáng tác ra những bản nhạc.\n- GV kể câu chuyện “Thần đồng âm nhạc Mô-da” theo tranh, giọng chậm, rõ; dừng ở từng tranh hỏi: Cậu bé Mô-da đang làm gì? Mọi người thấy cậu như thế nào?\n- GV hỏi thêm: Vì sao Mô-da được gọi là thần đồng âm nhạc? Chúng ta học được điều gì ở Mô-da?","hs":"- HS quan sát chân dung, nhắc lại tên nhạc sĩ Mô-da.\n- HS nghe kể chuyện, trả lời câu hỏi theo từng tranh.\n- HS trả lời: vì Mô-da chơi đàn, sáng tác từ rất nhỏ; học được sự chăm chỉ luyện tập."},{"ten":"3. Nghe nhạc: Khát vọng mùa xuân","gv":"- GV giới thiệu: bản nhạc Khát vọng mùa xuân là một sáng tác của nhạc sĩ Mô-da; GV mở cho HS nghe lần 1, yêu cầu ngồi ngay ngắn, lắng nghe.\n- GV hỏi cảm nhận: Bản nhạc nhanh hay chậm? Vui hay buồn? Nghe nhạc em nghĩ đến điều gì của mùa xuân?\n- GV mở nghe lần 2, hướng dẫn HS đung đưa người, vẫy tay nhẹ nhàng theo nhịp; lần 3 cho HS tự vận động theo ý thích.","hs":"- HS nghe nhạc lần 1, giữ trật tự.\n- HS nêu cảm nhận: nhạc nhẹ nhàng, vui; nghĩ đến hoa nở, chim hót...\n- HS nghe và vận động theo nhạc, tự sáng tạo động tác."},{"ten":"4. Vận dụng","gv":"- GV mời vài nhóm lên vận động theo bản nhạc Khát vọng mùa xuân trước lớp, khen ngợi nhóm vận động nhịp nhàng, đẹp.\n- GV hỏi lại: Hôm nay các em biết thêm nhạc sĩ nào? Ông sinh ở nước nào? Bản nhạc vừa nghe tên là gì?\n- GV dặn HS về kể lại chuyện Mô-da cho người thân nghe.","hs":"- HS xung phong vận động theo nhạc trước lớp.\n- HS trả lời: nhạc sĩ Mô-da, nước Áo, bản Khát vọng mùa xuân.\n- HS ghi nhớ nhiệm vụ."},{"ten":"5. Tích hợp Năng lực số & AI","gv":"- (Miền 1: Khai thác dữ liệu và thông tin — Cơ bản, bậc 1) GV chiếu chân dung Mô-da và tranh minh họa câu chuyện trên màn hình, mở bản Khát vọng mùa xuân từ học liệu số, chiếu tên bản nhạc và tên nhạc sĩ; HS nhìn hình, nghe và trả lời tên nhạc sĩ, tên bản nhạc; GV thao tác, HS không tự tra mạng.\n- (Miền 6: Ứng dụng trí tuệ nhân tạo — Cơ bản, bậc 1) GV dùng một ứng dụng AI đọc to đoạn ngắn kể về tuổi thơ Mô-da bằng giọng máy, hỏi HS: giọng vừa nghe là giọng người hay giọng máy? GV giải thích máy tính có thể đọc chữ thành tiếng nhưng câu chuyện vẫn do GV chọn và kiểm tra.\n⚠ (Miền 4: An toàn) Hình ảnh, bản nhạc lấy từ học liệu bộ sách hoặc kênh chính thức; thông tin về nhạc sĩ do GV kiểm tra trước khi kể; mở loa vừa đủ nghe, HS không tự cầm thiết bị.","hs":"- HS xem hình, nghe nhạc trên màn hình, nói được tên nhạc sĩ Mô-da và tên bản nhạc Khát vọng mùa xuân.\n- HS nghe đoạn giọng máy đọc, nhận ra đó là giọng máy và nhắc lại một điều về Mô-da vừa nghe."}],"status":"checked","source":"KHBD Âm nhạc 1 KNTT (Bút Xanh, theo SGV) — Tiết 20"},
{"lop":1,"mon":"Âm nhạc","tuan":21,"tiet":21,"bai":"Chủ đề 5: Nhịp điệu mùa xuân — Vận dụng – Sáng tạo: Dài – Ngắn","yccd":"1. Năng lực âm nhạc\n- Nghe và phân biệt được âm thanh dài – ngắn; nhắc lại được âm thanh dài, ngắn bằng âm “la”.\n- Đọc và thể hiện được âm thanh dài – ngắn theo hình vẽ (nét dài – nét ngắn, hình tiết tấu đơn giản).\n- Tham gia trò chơi “Ai hót dài hơn?” đúng luật, tự tin.\n2. Năng lực chung\n- Tự chủ và tự học: tự thể hiện âm thanh dài, ngắn theo ý mình.\n- Giao tiếp và hợp tác: biết thi đua, cổ vũ bạn trong trò chơi.\n3. Phẩm chất\n- Vui vẻ, mạnh dạn, tôn trọng bạn khi chơi.\n4. Tích hợp\n- Năng lực số 3.1 CB1a: Tạo được nội dung số đơn giản với sự hỗ trợ của GV: HS thể hiện âm thanh dài – ngắn để GV ghi âm, nghe lại và nhận xét.","dodung":"- Giáo viên: đàn Organ, loa, bảng hình vẽ âm thanh dài – ngắn (nét dài, nét ngắn; hình tiết tấu đen – trắng), tranh chim hót, còi hoặc kèn nhỏ, thiết bị ghi âm/trình chiếu.\n- Học sinh: SGK Âm nhạc 1, thanh phách.","hoatdong":[{"ten":"1. Khởi động","gv":"- GV mở nhạc, cả lớp hát bài Xúc xắc xúc xẻ kết hợp vỗ tay theo phách.\n- GV thổi còi (hoặc đàn) một tiếng dài rồi một tiếng ngắn, hỏi: Tiếng nào kêu lâu hơn? Tiếng nào kêu ngắn hơn?","hs":"- HS hát, vỗ tay theo phách.\n- HS lắng nghe, trả lời: tiếng thứ nhất dài, tiếng thứ hai ngắn."},{"ten":"2. Nghe và nhắc lại âm thanh dài – ngắn","gv":"- GV đàn một nốt ngân dài, một nốt ngắn, cho HS nhắc lại bằng âm “la”: “la___” (dài) và “la” (ngắn).\n- GV đàn xen kẽ dài – ngắn theo thứ tự khác nhau (dài – ngắn – ngắn, ngắn – dài...), HS nghe rồi nhắc lại; GV kết hợp động tác tay: kéo tay dài cho âm dài, chấm tay cho âm ngắn.\n- GV cho HS đọc theo dãy, cá nhân; sửa HS ngân chưa đủ dài hoặc ngắt chưa gọn.","hs":"- HS nghe, nhắc lại âm dài, âm ngắn bằng âm “la”.\n- HS nghe chuỗi âm thanh, nhắc lại đúng thứ tự, kết hợp động tác tay.\n- HS đọc theo dãy, cá nhân."},{"ten":"3. Đọc và thể hiện âm thanh dài – ngắn theo hình","gv":"- GV treo bảng hình vẽ: nét dài tương ứng âm dài, nét ngắn tương ứng âm ngắn; GV chỉ vào từng hình, đọc mẫu bằng âm “la”.\n- GV chỉ hình theo các dãy khác nhau, HS nhìn hình đọc; sau đó thay bằng hình tiết tấu đen – đen – trắng, cho HS gõ thanh phách: nốt đen gõ gọn, nốt trắng gõ rồi ngân.\n- GV mời HS lên chỉ hình để cả lớp đọc.","hs":"- HS quan sát, đọc theo GV.\n- HS nhìn hình đọc bằng âm “la”, gõ thanh phách theo hình tiết tấu.\n- HS xung phong lên chỉ hình, cả lớp đọc."},{"ten":"4. Trò chơi “Ai hót dài hơn?”","gv":"- GV nêu luật chơi: hai bạn lên sắm vai chú chim, cùng lấy hơi rồi hót bằng âm “la” theo cao độ GV đàn, bạn nào ngân dài hơn thì thắng; cả lớp làm trọng tài, đếm nhịp bằng tay.\n- GV cho chơi 3–4 lượt, sau đó chơi theo tổ: mỗi tổ cử một bạn, tổ hót dài nhất được khen.\n- GV nhận xét, nhắc HS lấy hơi sâu, ngân giọng đều; kết luận: âm thanh có lúc dài, lúc ngắn.","hs":"- HS lắng nghe luật chơi, xung phong tham gia.\n- HS chơi theo cặp, theo tổ, cả lớp đếm nhịp cổ vũ.\n- HS nhắc lại: âm thanh có dài, có ngắn."},{"ten":"5. Tích hợp Năng lực số & AI","gv":"- (Miền 1: Khai thác dữ liệu và thông tin — Cơ bản, bậc 1) GV mở từ học liệu số các đoạn âm thanh dài – ngắn (tiếng còi tàu, tiếng chim hót, tiếng chuông), chiếu kèm hình nét dài – nét ngắn; HS nghe và chỉ đúng hình tương ứng; GV thao tác thiết bị.\n- (Miền 3: Sáng tạo nội dung số — Cơ bản, bậc 1) GV dùng điện thoại ghi âm phần “hót” của các bạn trong trò chơi Ai hót dài hơn?, mở lại qua loa và cho HS xem vạch sóng âm dài – ngắn trên màn hình để thấy ai ngân dài hơn.\n⚠ (Miền 4: An toàn) Âm thanh lấy từ học liệu bộ sách; bản ghi giọng HS chỉ dùng tại lớp, không chia sẻ lên mạng; mở loa vừa đủ nghe, không đặt loa sát tai HS.","hs":"- HS nghe âm thanh trên loa, chỉ đúng hình nét dài hoặc nét ngắn.\n- HS nghe lại bản ghi âm, nhìn vạch sóng âm và nói bạn nào ngân dài hơn."}],"status":"checked","source":"KHBD Âm nhạc 1 KNTT (Bút Xanh, theo SGV) — Tiết 21"},
{"lop":1,"mon":"Âm nhạc","tuan":22,"tiet":22,"bai":"Chủ đề 6: Về miền dân ca — Học hát: Gà gáy (Dân ca Cống Khao, lời mới: Huy Trân)","yccd":"1. Năng lực âm nhạc\n- Nhớ tên bài hát, biết Gà gáy là dân ca Cống Khao của đồng bào miền núi phía Bắc, lời mới do Huy Trân viết.\n- Hát rõ lời, đúng giai điệu, ngân đủ ở cuối các câu hát; hát với tính chất vui tươi, trong sáng.\n- Biết hát kết hợp vỗ tay theo phách.\n2. Năng lực chung\n- Tự chủ và tự học: tự tập lại những câu hát chưa thuộc.\n- Giao tiếp và hợp tác: biết hát hòa giọng, hát nối tiếp cùng bạn.\n3. Phẩm chất\n- Yêu quý làn điệu dân ca các dân tộc, yêu cảnh sớm mai ở bản làng; chăm chỉ dậy sớm đi học.\n4. Tích hợp\n- Năng lực số 3.3 CB1a: Xác định được các quy tắc đơn giản về bản quyền và giấy phép áp dụng cho dữ liệu, thông tin và nội dung số: HS nói được bài Gà gáy là dân ca Cống Khao và người viết lời mới là Huy Trân.","dodung":"- Giáo viên: đàn Organ (hoặc file nhạc đệm), loa, tranh cảnh bản làng miền núi buổi sáng có gà gáy, bản đồ/tranh trang phục đồng bào miền núi phía Bắc, thanh phách, thiết bị trình chiếu.\n- Học sinh: SGK Âm nhạc 1, thanh phách.","hoatdong":[{"ten":"1. Khởi động","gv":"- GV cho HS nghe tiếng gà gáy (GV bắt chước hoặc mở âm thanh), hỏi: Đó là tiếng con gì? Gà thường gáy vào lúc nào?\n- GV cho HS xem tranh bản làng miền núi lúc sớm mai, giới thiệu: đồng bào dân tộc Cống ở miền núi phía Bắc có bài dân ca về tiếng gà gáy gọi mọi người dậy đi làm, đi học.","hs":"- HS trả lời: tiếng gà, gà gáy vào buổi sáng sớm.\n- HS quan sát tranh, lắng nghe GV giới thiệu."},{"ten":"2. Khám phá — Nghe và học hát","gv":"- GV mở bản hát mẫu từ học liệu số cho HS nghe 1–2 lần, giới thiệu: bài Gà gáy là dân ca Cống Khao, lời mới của Huy Trân.\n- GV đọc lời ca theo tiết tấu, chia bài thành 4 câu ngắn, cho HS đọc theo; giải thích từ khó nếu có.\n- GV đàn giai điệu, hát mẫu từng câu và bắt nhịp cho HS hát nối tiếp câu 1, câu 2, câu 3, câu 4; chú ý tiếng cuối câu ngân dài, GV đếm nhịp bằng tay để HS ngân đủ.","hs":"- HS lắng nghe, nhắc lại tên bài, nêu cảm nhận: bài hát vui, trong sáng.\n- HS đọc lời ca từng câu theo GV.\n- HS tập hát từng câu, ngân đủ tiếng cuối câu, hát nối các câu thành cả bài."},{"ten":"3. Luyện tập","gv":"- GV cho HS hát cả bài theo nhạc đệm, nghe và sửa những chỗ hát chưa rõ lời, ngân chưa đủ.\n- GV làm mẫu hát kết hợp vỗ tay theo phách, sau đó cho HS gõ thanh phách.\n- GV cho HS hát theo dãy, tổ, hát nối tiếp từng câu; hát nhỏ dần ở câu cuối như tiếng gà xa dần.","hs":"- HS hát cả bài theo nhạc đệm, hát lại chỗ được sửa.\n- HS hát kết hợp vỗ tay, gõ thanh phách theo phách.\n- HS hát theo dãy, tổ, hát nối tiếp."},{"ten":"4. Vận dụng","gv":"- GV mời vài nhóm/cá nhân lên hát trước lớp kết hợp gõ đệm, khen ngợi HS hát tự tin.\n- GV hỏi: Bài hát là dân ca của dân tộc nào? Tiếng gà gáy nhắc mọi người làm gì buổi sáng?\n- GV dặn HS về hát cho người thân nghe, dậy sớm đi học đúng giờ.","hs":"- HS xung phong biểu diễn, các bạn cổ vũ.\n- HS trả lời: dân ca Cống Khao; nhắc mọi người thức dậy đi làm, đi học.\n- HS ghi nhớ nhiệm vụ."},{"ten":"5. Tích hợp Năng lực số & AI","gv":"- (Miền 1: Khai thác dữ liệu và thông tin — Cơ bản, bậc 1) GV mở bản hát mẫu bài “Gà gáy” từ học liệu số, chiếu màn hình có tên bài, dòng chữ “Dân ca Cống Khao – lời mới: Huy Trân” và hình ảnh bản làng miền núi phía Bắc; GV mở từng câu, dừng cho HS nghe rồi hát nối tiếp, câu ngân dài mở lại để HS nghe kĩ.\n- (Miền 3: Sáng tạo nội dung số — Cơ bản, bậc 1) GV dùng điện thoại ghi âm cả lớp hát kết hợp gõ đệm rồi mở lại qua loa; HS nghe và chỉ ra chỗ ngân chưa đủ, chưa rõ lời; GV thao tác thiết bị, HS chỉ nghe và nhận xét.\n⚠ (Miền 4: An toàn) Bản thu chỉ lấy từ học liệu bộ sách hoặc kênh chính thức; giới thiệu bài phải nói rõ là dân ca Cống Khao và tên người viết lời mới; mở loa vừa đủ nghe.","hs":"- HS nghe bản hát mẫu, nói được bài “Gà gáy” là dân ca Cống Khao, lời mới Huy Trân; hát đúng lời theo từng câu.\n- HS nghe lại bản ghi âm của lớp, chỉ ra một chỗ ngân chưa đủ hoặc hát chưa rõ rồi hát lại."}],"status":"checked","source":"KHBD Âm nhạc 1 KNTT (Bút Xanh, theo SGV) — Tiết 22"},
{"lop":1,"mon":"Âm nhạc","tuan":23,"tiet":23,"bai":"Chủ đề 6: Về miền dân ca — Ôn bài hát Gà gáy; Thường thức âm nhạc: \"Câu chuyện về thanh phách\"","yccd":"1. Năng lực âm nhạc\n- Hát thuộc lời, đúng giai điệu bài Gà gáy; biết hát kết hợp gõ đệm theo phách và vận động đơn giản.\n- Nghe và kể lại được 1–2 ý trong câu chuyện về thanh phách: thanh phách làm bằng tre, gõ vào nhau phát ra tiếng “cách cách”, thường dùng để gõ đệm khi hát dân ca.\n2. Năng lực chung\n- Tự chủ và tự học: chăm chú nghe chuyện, tự nhắc lại điều đã nghe.\n- Giao tiếp và hợp tác: biết hát, gõ đệm hòa cùng nhóm.\n3. Phẩm chất\n- Yêu quý nhạc cụ dân tộc và các làn điệu dân ca của quê hương.\n4. Tích hợp\n- Năng lực số 1.1 CB1a: Tìm được thông tin đơn giản theo hướng dẫn: HS xem hình, nghe âm thanh trên màn hình và nói đúng tên nhạc cụ thanh phách.","dodung":"- Giáo viên: đàn Organ (hoặc file nhạc đệm), loa, thanh phách thật, tranh minh họa câu chuyện về thanh phách (cây tre, người làm thanh phách, người hát dân ca gõ phách), thiết bị trình chiếu.\n- Học sinh: SGK Âm nhạc 1, thanh phách.","hoatdong":[{"ten":"1. Khởi động","gv":"- GV bắt chước tiếng gà gáy, cho HS đoán tên bài hát đã học ở tiết trước.\n- GV mở nhạc đệm, cả lớp hát bài Gà gáy kết hợp vỗ tay theo phách.","hs":"- HS đoán: bài Gà gáy.\n- HS hát, vỗ tay theo phách."},{"ten":"2. Ôn bài hát Gà gáy","gv":"- GV cho HS hát cả bài theo nhạc đệm, sửa những chỗ hát chưa rõ lời, ngân chưa đủ ở cuối câu.\n- GV hướng dẫn hát kết hợp gõ thanh phách theo phách; hướng dẫn vài động tác vận động: tay làm cánh gà vỗ nhẹ, nghiêng đầu như gà gáy, đưa tay lên như mặt trời mọc.\n- GV chia tổ hát nối tiếp, mời nhóm lên biểu diễn kết hợp gõ đệm hoặc vận động.","hs":"- HS hát cả bài, hát lại chỗ được sửa.\n- HS hát kết hợp gõ thanh phách, vận động theo GV.\n- HS hát nối tiếp theo tổ, nhóm xung phong biểu diễn."},{"ten":"3. Thường thức âm nhạc: Câu chuyện về thanh phách","gv":"- GV giơ thanh phách thật, gõ vài tiếng và hỏi: Đây là nhạc cụ gì? Các em đã dùng nó để làm gì?\n- GV kể câu chuyện về thanh phách theo tranh: thanh phách được làm từ tre, gồm hai thanh nhỏ gõ vào nhau kêu “cách cách”; từ xưa ông bà ta đã dùng thanh phách để gõ nhịp khi hát dân ca; GV dừng ở từng tranh hỏi: Thanh phách làm bằng gì? Người ta dùng thanh phách khi nào?\n- GV cho HS nghe một đoạn hát dân ca có gõ thanh phách, chỉ cho HS nghe tiếng phách nổi lên theo nhịp.","hs":"- HS trả lời: thanh phách, dùng để gõ đệm khi hát.\n- HS nghe kể chuyện, trả lời câu hỏi: làm bằng tre; dùng khi hát dân ca.\n- HS nghe, giơ tay khi nghe thấy tiếng phách."},{"ten":"4. Vận dụng","gv":"- GV cho HS cầm thanh phách gõ theo phách và hát bài Gà gáy, thử gõ vào các cạnh khác nhau để nghe tiếng to – nhỏ.\n- GV hỏi lại: Thanh phách làm bằng gì? Dùng khi nào? Em thích nhất điều gì trong câu chuyện?\n- GV dặn HS về kể chuyện thanh phách cho người thân nghe.","hs":"- HS gõ thanh phách đệm cho bài hát, thử nghe tiếng to – nhỏ.\n- HS trả lời câu hỏi.\n- HS ghi nhớ nhiệm vụ."},{"ten":"5. Tích hợp Năng lực số & AI","gv":"- (Miền 1: Khai thác dữ liệu và thông tin — Cơ bản, bậc 1) GV chiếu tranh minh họa câu chuyện về thanh phách và mở đoạn âm thanh tiếng phách gõ, đoạn hát dân ca có phách đệm từ học liệu số; HS xem hình, nghe và nói tên nhạc cụ, nói thanh phách làm bằng tre; GV thao tác, HS chỉ nhìn – nghe – trả lời.\n- (Miền 6: Ứng dụng trí tuệ nhân tạo — Cơ bản, bậc 1) GV mở một ứng dụng AI tạo hình ảnh, nhập yêu cầu vẽ “hai thanh phách bằng tre”, chiếu hình cho HS so với thanh phách thật và hỏi: hình máy vẽ giống hay khác thanh phách thật ở chỗ nào?\n⚠ (Miền 4: An toàn) Hình do máy vẽ chỉ để so sánh, thanh phách thật mới là chuẩn; âm thanh, tranh lấy từ học liệu bộ sách; HS không tự cầm thiết bị của GV; mở loa vừa đủ nghe.","hs":"- HS xem hình, nghe tiếng phách trên loa, nói đúng tên nhạc cụ thanh phách và vật liệu làm ra nó.\n- HS so sánh hình máy vẽ với thanh phách thật, nói một điểm giống hoặc khác."}],"status":"checked","source":"KHBD Âm nhạc 1 KNTT (Bút Xanh, theo SGV) — Tiết 23"},
{"lop":1,"mon":"Âm nhạc","tuan":24,"tiet":24,"bai":"Chủ đề 6: Về miền dân ca — Nhạc cụ: Thanh phách; Nghe nhạc: Lí cây bông (Dân ca Nam Bộ)","yccd":"1. Năng lực âm nhạc\n- Biết tên, hình dáng thanh phách; cầm và gõ thanh phách đúng cách; gõ được theo hình tiết tấu đơn giản (đen – đen – trắng; đen – đen – đen – lặng).\n- Gõ thanh phách đệm theo phách cho bài hát Gà gáy.\n- Nghe và cảm nhận được tính chất vui tươi, dí dỏm của bài Lí cây bông (dân ca Nam Bộ); biết vận động theo nhạc.\n2. Năng lực chung\n- Tự chủ và tự học: tự luyện gõ theo hình tiết tấu.\n- Giao tiếp và hợp tác: biết gõ đệm đều với nhóm, hát – gõ phối hợp cùng bạn.\n3. Phẩm chất\n- Yêu quý nhạc cụ dân tộc, dân ca các miền của đất nước; giữ gìn nhạc cụ cẩn thận.\n4. Tích hợp\n- Năng lực số 4.1 CB1a: Sử dụng thiết bị số an toàn theo hướng dẫn: HS ngồi đúng khoảng cách với màn hình, nghe loa vừa đủ khi xem, nghe bài Lí cây bông.","dodung":"- Giáo viên: thanh phách (đủ cho GV và mẫu cho HS), bảng hình tiết tấu 1 (đen – đen – trắng) và 2 (đen – đen – đen – lặng), file bài Lí cây bông, tranh miền sông nước Nam Bộ và hoa lê, hoa lựu, loa, đàn Organ, thiết bị trình chiếu.\n- Học sinh: SGK Âm nhạc 1, thanh phách.","hoatdong":[{"ten":"1. Khởi động","gv":"- GV mở nhạc đệm, cả lớp hát bài Gà gáy kết hợp vỗ tay theo phách.\n- GV gõ thanh phách một đoạn tiết tấu ngắn, hỏi: Cô/thầy vừa gõ bằng nhạc cụ gì? Thanh phách làm bằng gì (đã nghe ở tiết trước)?","hs":"- HS hát, vỗ tay theo phách.\n- HS trả lời: thanh phách, làm bằng tre."},{"ten":"2. Nhạc cụ: Thanh phách — cách cầm và gõ","gv":"- GV giới thiệu hình dáng thanh phách: hai thanh tre nhỏ, dài bằng nhau; hướng dẫn cách cầm: mỗi tay cầm một thanh, cầm chắc ở phần cuối, gõ hai thanh vào nhau ở phần đầu, tay gõ dứt khoát rồi nhấc lên.\n- GV làm mẫu gõ theo hình tiết tấu 1: đen – đen – trắng (gõ – gõ – gõ ngân) và hình tiết tấu 2: đen – đen – đen – lặng (gõ – gõ – gõ – nghỉ); GV đọc “ta – ta – ta-a” và “ta – ta – ta – nghỉ” khi gõ.\n- GV cho HS gõ theo từng hình tiết tấu, theo dãy, cá nhân; sửa HS cầm phách chưa đúng, gõ chưa đều.","hs":"- HS quan sát, cầm thanh phách đúng cách, gõ thử vài tiếng.\n- HS đọc tiết tấu và gõ theo GV hình 1, hình 2.\n- HS gõ theo dãy, cá nhân, sửa cách cầm."},{"ten":"3. Nhạc cụ: Gõ đệm thanh phách cho bài Gà gáy","gv":"- GV hát bài Gà gáy kết hợp gõ thanh phách theo phách để HS quan sát.\n- GV cho HS hát và gõ đệm theo phách; chia lớp thành 2 nhóm: nhóm hát – nhóm gõ, rồi đổi lại.\n- GV mời nhóm lên biểu diễn hát kết hợp gõ thanh phách.","hs":"- HS quan sát GV làm mẫu.\n- HS hát kết hợp gõ đệm theo phách, luân phiên theo nhóm.\n- HS xung phong biểu diễn."},{"ten":"4. Nghe nhạc: Lí cây bông","gv":"- GV cho HS xem tranh miền sông nước Nam Bộ, giới thiệu bài Lí cây bông là dân ca Nam Bộ, hát về những bông hoa đẹp; GV mở cho HS nghe lần 1.\n- GV hỏi cảm nhận: Bài hát vui hay buồn? Trong bài nhắc đến hoa gì? Em thích bài hát không?\n- GV mở lần 2, hướng dẫn HS gõ thanh phách nhẹ theo phách hoặc đung đưa người theo nhịp; lần 3 cho HS vận động theo ý thích.","hs":"- HS xem tranh, nghe nhạc lần 1, giữ trật tự.\n- HS nêu cảm nhận: bài hát vui, nhắc đến hoa lê, hoa lựu...\n- HS nghe và gõ phách nhẹ hoặc vận động theo nhạc."},{"ten":"5. Tích hợp Năng lực số & AI","gv":"- (Miền 1: Khai thác dữ liệu và thông tin — Cơ bản, bậc 1) GV chiếu hình tiết tấu 1, 2 trên màn hình, bấm phát tiếng phách mẫu theo từng hình để HS nghe rồi gõ theo; sau đó mở bài Lí cây bông từ học liệu số, chiếu tên bài và dòng chữ “Dân ca Nam Bộ” kèm hình miền sông nước; GV thao tác, HS chỉ nghe – nhìn – gõ.\n- (Miền 3: Sáng tạo nội dung số — Cơ bản, bậc 1) GV ghi âm cả lớp hát Gà gáy kết hợp gõ thanh phách rồi mở lại qua loa; HS nghe và nhận xét tiếng phách đã đều, đã đúng phách chưa.\n⚠ (Miền 4: An toàn) HS ngồi cách màn hình đủ xa, không nhìn quá lâu; loa mở vừa đủ nghe; bản Lí cây bông lấy từ học liệu bộ sách, nói rõ là dân ca Nam Bộ; bản ghi âm của lớp chỉ dùng tại lớp.","hs":"- HS nghe tiếng phách mẫu trên loa, gõ đúng theo hình tiết tấu; nghe bài Lí cây bông và nói được đó là dân ca Nam Bộ.\n- HS nghe lại bản ghi âm, nói tiếng phách đã đều chưa, gõ lại chỗ chưa đều; ngồi đúng khoảng cách với màn hình."}],"status":"checked","source":"KHBD Âm nhạc 1 KNTT (Bút Xanh, theo SGV) — Tiết 24"},
{"lop":1,"mon":"Âm nhạc","tuan":25,"tiet":25,"bai":"Chủ đề 6: Về miền dân ca — Vận dụng – Sáng tạo: Dài – Ngắn","yccd":"1. Năng lực âm nhạc\n- Thể hiện được âm thanh dài – ngắn bằng giọng (tiếng gà gáy dài, ngắn) và bằng thanh phách theo hình tiết tấu.\n- Tham gia trò chơi “Hãy là chú gà trống siêng năng” đúng luật, tự tin.\n- Nghe nhạc và vận động cùng hai nốt Pha – Son theo kí hiệu bàn tay; đọc được Pha, Son dài – ngắn theo tay GV.\n2. Năng lực chung\n- Tự chủ và tự học: tự nghĩ ra cách thể hiện tiếng gà gáy dài, ngắn.\n- Giao tiếp và hợp tác: biết thi đua và phối hợp với bạn trong trò chơi, trong nhóm vận động.\n3. Phẩm chất\n- Chăm chỉ, dậy sớm đúng giờ như chú gà trống siêng năng; vui vẻ, đoàn kết.\n4. Tích hợp\n- Năng lực số 2.1 CB1a: Giao tiếp qua kênh số đơn giản với sự hỗ trợ của GV: HS nói lời chào buổi sáng để GV ghi lại thành lời nhắn gửi bạn lớp bên.","dodung":"- Giáo viên: đàn Organ, loa, mũ hoặc tranh gà trống, bảng hình tiết tấu dài – ngắn, thẻ kí hiệu bàn tay Pha – Son, file nhạc vui tươi để vận động, thanh phách, thiết bị ghi âm/trình chiếu.\n- Học sinh: SGK Âm nhạc 1, thanh phách.","hoatdong":[{"ten":"1. Khởi động","gv":"- GV mở nhạc đệm, cả lớp hát bài Gà gáy kết hợp gõ thanh phách theo phách.\n- GV gáy “ò ó o” một tiếng dài và một tiếng ngắn, hỏi: Tiếng gáy nào dài hơn? Cả lớp thử gáy dài, gáy ngắn theo tay GV (kéo tay dài – chấm tay ngắn).","hs":"- HS hát và gõ thanh phách theo phách.\n- HS trả lời, bắt chước gáy dài – ngắn theo tay GV."},{"ten":"2. Trò chơi “Hãy là chú gà trống siêng năng”","gv":"- GV nêu luật chơi: một bạn đội mũ gà trống làm “gà trống siêng năng”, khi GV đàn nốt dài thì gáy dài, đàn nốt ngắn thì gáy ngắn bằng âm “ò ó o”; cả lớp làm “gà con” gáy đáp lại đúng dài – ngắn; bạn nào gáy sai dài – ngắn phải nhường mũ cho bạn khác.\n- GV cho chơi 4–5 lượt, đổi cao độ và thứ tự dài – ngắn khác nhau (dài – ngắn – ngắn; ngắn – ngắn – dài...).\n- GV nhận xét, khen chú gà trống gáy đúng và siêng năng, nhắc HS chăm chỉ dậy sớm.","hs":"- HS nghe luật chơi, xung phong làm gà trống.\n- HS chơi: gà trống gáy, gà con đáp đúng dài – ngắn.\n- HS vỗ tay khen bạn, nhắc lại lời dặn."},{"ten":"3. Thể hiện âm thanh dài – ngắn bằng thanh phách","gv":"- GV treo bảng hình tiết tấu có nét dài – nét ngắn, làm mẫu gõ thanh phách: nét ngắn gõ gọn, nét dài gõ rồi giữ phách ngân (đọc “ta” và “ta-a”).\n- GV chỉ hình theo các thứ tự khác nhau cho HS gõ theo dãy, tổ; mời HS lên tự xếp thẻ dài – ngắn thành dãy để các bạn gõ.","hs":"- HS quan sát, gõ thanh phách theo mẫu dài – ngắn.\n- HS gõ theo dãy, tổ; HS xung phong xếp thẻ, cả lớp gõ theo."},{"ten":"4. Nghe nhạc và vận động cùng Pha – Son","gv":"- GV làm kí hiệu bàn tay Pha, Son và đàn cao độ, cho HS đọc lại hai nốt; sau đó đọc Pha dài – Son ngắn, Son dài – Pha ngắn theo tay GV.\n- GV mở bản nhạc vui tươi, hướng dẫn HS vận động: nghe nốt Son thì giơ tay cao làm kí hiệu Son, nghe nốt Pha thì làm kí hiệu Pha, âm dài thì đưa tay chậm, âm ngắn thì đưa tay nhanh.\n- GV chia nhóm, mỗi nhóm vận động theo cách riêng; mời nhóm lên thể hiện, nhận xét, khen ngợi.","hs":"- HS làm kí hiệu bàn tay, đọc Pha – Son dài – ngắn theo tay GV.\n- HS nghe nhạc, vận động kết hợp kí hiệu bàn tay.\n- HS vận động theo nhóm, xung phong thể hiện trước lớp."},{"ten":"5. Tích hợp Năng lực số & AI","gv":"- (Miền 1: Khai thác dữ liệu và thông tin — Cơ bản, bậc 1) GV mở từ học liệu số các tiếng gà gáy dài – ngắn khác nhau kèm hình nét dài – nét ngắn trên màn hình; HS nghe và chỉ đúng hình, gáy đáp lại đúng dài – ngắn; GV thao tác thiết bị.\n- (Miền 2: Giao tiếp và hợp tác trong môi trường số — Cơ bản, bậc 1) GV dùng điện thoại ghi âm cả lớp gáy “ò ó o” thật hay và nói lời chào buổi sáng, giới thiệu đây là lời nhắn âm thanh GV sẽ gửi cho lớp bên qua nhóm Zalo của GV; GV mở lại cho HS nghe trước khi gửi.\n⚠ (Miền 4: An toàn) Lời nhắn chỉ có giọng cả lớp, không nêu tên riêng, không kèm hình mặt HS; GV là người gửi, HS không tự dùng điện thoại; âm thanh mẫu lấy từ học liệu bộ sách; loa vừa đủ nghe.","hs":"- HS nghe tiếng gà gáy trên loa, chỉ đúng hình dài – ngắn và gáy đáp lại.\n- HS cùng gáy và nói lời chào để GV ghi âm, nghe lại lời nhắn và nói lời nhắn có được nêu tên riêng của bạn không."}],"status":"checked","source":"KHBD Âm nhạc 1 KNTT (Bút Xanh, theo SGV) — Tiết 25"},
{"lop":1,"mon":"Âm nhạc","tuan":26,"tiet":26,"bai":"Chủ đề 7: Gia đình — Học hát: Cây gia đình (Nhạc: Quỳnh Hợp, lời thơ: Nguyễn Thị Mai)","yccd":"1. Năng lực âm nhạc\n- Nhớ tên bài hát Cây gia đình, tên tác giả phần nhạc Quỳnh Hợp và tác giả lời thơ Nguyễn Thị Mai.\n- Hát rõ lời, đúng giai điệu; bước đầu thể hiện tình cảm tha thiết, trìu mến của bài hát.\n- Biết hát kết hợp vỗ tay theo phách.\n2. Năng lực chung\n- Tự chủ và tự học: tự tập lại câu hát chưa thuộc, mạnh dạn hát trước lớp.\n- Giao tiếp và hợp tác: biết hát hòa giọng, hát nối tiếp cùng bạn.\n3. Phẩm chất\n- Yêu thương, kính trọng ông bà, cha mẹ; quý trọng gia đình.\n4. Tích hợp\n- Năng lực số 3.3 CB1a: Xác định được các quy tắc đơn giản về bản quyền và giấy phép áp dụng cho dữ liệu, thông tin và nội dung số: HS nói được tên bài hát cùng tên tác giả nhạc và tác giả lời thơ.","dodung":"- Giáo viên: đàn Organ (hoặc file nhạc đệm), loa, tranh “cây gia đình” (ông bà là gốc, bố mẹ là cành, các con là lá, quả), thanh phách, thiết bị trình chiếu mở học liệu số.\n- Học sinh: SGK Âm nhạc 1, thanh phách, ảnh gia đình (nếu có).","hoatdong":[{"ten":"1. Khởi động","gv":"- GV cho HS xem tranh “cây gia đình”, hỏi: Trong tranh có những ai? Gia đình em có mấy người, gồm những ai?\n- GV giới thiệu: gia đình như một cái cây, ông bà là gốc, bố mẹ là cành, các con là lá, quả; hôm nay lớp học bài hát Cây gia đình.","hs":"- HS quan sát tranh, kể về gia đình mình: ông bà, bố mẹ, anh chị em.\n- HS lắng nghe GV giới thiệu bài."},{"ten":"2. Khám phá — Nghe và học hát","gv":"- GV mở bản hát mẫu từ học liệu số cho HS nghe 1–2 lần, giới thiệu tác giả phần nhạc là nhạc sĩ Quỳnh Hợp, lời dựa theo thơ của Nguyễn Thị Mai.\n- GV đọc lời ca theo tiết tấu, chia bài thành 4–6 câu ngắn, cho HS đọc theo từng câu; giải thích ý mỗi câu bằng cách chỉ vào tranh cây gia đình.\n- GV đàn giai điệu, hát mẫu từng câu và bắt nhịp cho HS hát nối tiếp câu 1, câu 2... đến hết bài; nhắc HS hát nhẹ nhàng, tha thiết, ngân đủ ở cuối câu.","hs":"- HS lắng nghe, nói tên bài hát, nêu cảm nhận: bài hát nhẹ nhàng, tình cảm.\n- HS đọc lời ca từng câu theo GV.\n- HS tập hát từng câu, hát nối các câu thành cả bài."},{"ten":"3. Luyện tập","gv":"- GV cho HS hát cả bài theo nhạc đệm, nghe và sửa những chỗ hát chưa rõ lời, chưa đúng cao độ.\n- GV làm mẫu hát kết hợp vỗ tay theo phách, sau đó cho HS gõ thanh phách nhẹ nhàng.\n- GV cho HS hát theo dãy, theo tổ, hát nối tiếp từng câu; hát với nét mặt vui tươi, trìu mến.","hs":"- HS hát cả bài theo nhạc đệm, hát lại chỗ được sửa.\n- HS hát kết hợp vỗ tay, gõ thanh phách theo phách.\n- HS hát theo dãy, tổ, hát nối tiếp."},{"ten":"4. Vận dụng","gv":"- GV mời vài nhóm/cá nhân lên hát trước lớp kết hợp gõ đệm, khen ngợi HS hát tự tin, tình cảm.\n- GV hỏi: Bài hát nói về điều gì? Em sẽ làm gì để ông bà, bố mẹ vui?\n- GV dặn HS về hát tặng gia đình và nói một lời yêu thương với người thân.","hs":"- HS xung phong biểu diễn, các bạn cổ vũ.\n- HS trả lời: bài hát về gia đình; em ngoan, vâng lời, giúp việc nhà...\n- HS ghi nhớ nhiệm vụ."},{"ten":"5. Tích hợp Năng lực số & AI","gv":"- (Miền 1: Khai thác dữ liệu và thông tin — Cơ bản, bậc 1) GV mở bản hát mẫu bài “Cây gia đình” từ học liệu số, chiếu màn hình có tên bài, tên tác giả nhạc Quỳnh Hợp và tác giả lời thơ Nguyễn Thị Mai cùng tranh cây gia đình; GV mở từng câu ngắn, dừng cho HS nghe rồi hát nối tiếp, câu nào chưa đúng thì mở lại.\n- (Miền 3: Sáng tạo nội dung số — Cơ bản, bậc 1) GV dùng điện thoại ghi âm cả lớp hát bài Cây gia đình kết hợp gõ đệm, mở lại qua loa; HS nghe và chỉ ra chỗ hát chưa rõ, chưa tình cảm; GV giới thiệu có thể gửi bản thu này cho cha mẹ HS nghe qua nhóm lớp.\n⚠ (Miền 4: An toàn) Bản thu chỉ lấy từ học liệu bộ sách hoặc kênh chính thức; giới thiệu bài phải nói rõ tên tác giả nhạc và lời thơ; bản ghi giọng lớp chỉ gửi cho cha mẹ HS trong nhóm lớp, do GV gửi; mở loa vừa đủ nghe.","hs":"- HS nghe bản hát mẫu, nói được tên bài “Cây gia đình”, tác giả nhạc Quỳnh Hợp, lời thơ Nguyễn Thị Mai; hát đúng lời theo từng câu.\n- HS nghe lại bản ghi âm của lớp, chỉ ra một chỗ hát chưa rõ rồi hát lại cho hay hơn để gửi tặng gia đình."}],"status":"checked","source":"KHBD Âm nhạc 1 KNTT (Bút Xanh, theo SGV) — Tiết 26"},
{"lop":1,"mon":"Âm nhạc","tuan":27,"tiet":27,"bai":"Chủ đề 7: Gia đình — Ôn bài hát Cây gia đình; Đọc nhạc: Hát cùng Đô – Rê – Mi – Pha – Son","yccd":"1. Năng lực âm nhạc\n- Hát thuộc lời, đúng giai điệu bài Cây gia đình; biết hát kết hợp vỗ tay theo phách và vận động nhẹ nhàng.\n- Đọc được 5 nốt Đô – Rê – Mi – Pha – Son theo kí hiệu bàn tay bằng âm “la” và tên nốt; bước đầu đọc đúng cao độ bài đọc nhạc Hát cùng Đô – Rê – Mi – Pha – Son.\n- Phân biệt được âm cao – thấp khi đọc các nốt đi lên, đi xuống.\n2. Năng lực chung\n- Tự chủ và tự học: tự làm đúng kí hiệu bàn tay khi đọc nhạc.\n- Giao tiếp và hợp tác: đọc nhạc nối tiếp theo nhóm, nghe bạn đọc để đọc theo.\n3. Phẩm chất\n- Yêu quý, kính trọng ông bà, cha mẹ; chăm chỉ luyện tập.\n4. Tích hợp\n- Năng lực số 1.1 CB1a: Tìm được thông tin đơn giản theo hướng dẫn: HS nghe bản đọc nhạc mẫu từ học liệu số, nói được tên 5 nốt vừa nghe theo thứ tự.","dodung":"- Giáo viên: đàn Organ (hoặc file nhạc đệm), loa, tranh kí hiệu bàn tay 5 nốt Đô – Rê – Mi – Pha – Son, hình bậc thang 5 nốt, thanh phách, thiết bị trình chiếu/loa mở học liệu số.\n- Học sinh: SGK Âm nhạc 1, thanh phách.","hoatdong":[{"ten":"1. Khởi động","gv":"- GV mở nhạc đệm bài Cây gia đình, cho cả lớp đứng tại chỗ vận động theo nhịp và hát nhẩm.\n- GV hỏi: Bài hát nói về những ai trong gia đình em? Em thích câu hát nào nhất?","hs":"- HS vận động theo nhạc, hát nhẩm theo.\n- HS trả lời: ông bà, bố mẹ, anh chị em...; nêu câu hát mình thích."},{"ten":"2. Ôn bài hát Cây gia đình","gv":"- GV hát mẫu lại một lần, nhắc HS hát rõ lời, lấy hơi ở cuối mỗi câu, hát nhẹ nhàng, tình cảm.\n- GV cho HS hát cả bài theo nhạc đệm; sửa những chỗ hát chưa đúng cao độ (thường ở câu cuối).\n- GV hướng dẫn hát kết hợp vỗ tay theo phách, rồi hát kết hợp vận động: hai tay đưa lên như cành cây, nghiêng người sang hai bên theo nhịp.\n- GV cho hát theo tổ, nhóm; mời 1–2 nhóm lên trình bày.","hs":"- HS nghe, hát lại cả bài theo nhạc đệm.\n- HS hát lại những câu GV sửa.\n- HS hát kết hợp vỗ tay theo phách, sau đó hát kết hợp vận động theo hướng dẫn.\n- HS hát theo tổ, nhóm; nhận xét bạn hát đúng nhạc, rõ lời."},{"ten":"3. Đọc nhạc: Hát cùng Đô – Rê – Mi – Pha – Son","gv":"- GV treo tranh 5 nốt trên bậc thang, đọc mẫu tên từng nốt kết hợp kí hiệu bàn tay: Đô (nắm tay), Rê (bàn tay nghiêng), Mi (bàn tay ngang), Pha (bàn tay nghiêng, ngón cái chúc xuống), Son (bàn tay dựng đứng, lòng bàn tay hướng vào người).\n- GV đàn từng nốt đi lên Đô – Rê – Mi – Pha – Son rồi đi xuống, cho HS đọc bằng âm “la” trước, sau đó đọc bằng tên nốt kèm kí hiệu tay.\n- GV mở bản đọc nhạc mẫu Hát cùng Đô – Rê – Mi – Pha – Son, đọc mẫu từng câu ngắn (2–3 câu) kết hợp kí hiệu bàn tay; bắt nhịp cho HS đọc nối tiếp đến hết bài.\n- GV làm kí hiệu tay không đọc thành tiếng, cho HS nhìn tay và đọc đúng tên nốt.","hs":"- HS quan sát, đọc tên nốt và làm kí hiệu bàn tay theo GV.\n- HS đọc 5 nốt đi lên, đi xuống bằng âm “la”, rồi bằng tên nốt kèm kí hiệu tay.\n- HS nghe mẫu, đọc từng câu theo GV, đọc nối các câu.\n- HS nhìn tay GV đọc đúng tên nốt; đọc theo dãy, theo nhóm."},{"ten":"4. Vận dụng","gv":"- GV chia lớp thành 5 nhóm, mỗi nhóm “giữ” một nốt; GV chỉ tay đến nốt nào, nhóm đó đứng lên đọc nốt ấy.\n- GV mời 2–3 HS làm “nhạc trưởng” làm kí hiệu tay cho cả lớp đọc.\n- GV nhận xét, dặn HS về nhà tập kí hiệu tay 5 nốt và hát bài Cây gia đình cho người thân nghe.","hs":"- HS tham gia trò chơi, đứng lên đọc đúng nốt của nhóm mình.\n- HS xung phong làm “nhạc trưởng”, cả lớp đọc theo tay bạn.\n- HS ghi nhớ nhiệm vụ."},{"ten":"5. Tích hợp Năng lực số & AI","gv":"- (Miền 1: Khai thác dữ liệu và thông tin — Cơ bản, bậc 1) GV mở bản đọc nhạc mẫu Hát cùng Đô – Rê – Mi – Pha – Son từ học liệu số, chiếu hình bậc thang 5 nốt có tô màu; GV bấm phát từng câu, dừng lại để HS nói tên các nốt vừa nghe rồi đọc theo; câu nào HS đọc sai cao độ, GV mở lại câu đó.\n- (Miền 3: Sáng tạo nội dung số — Cơ bản, bậc 1) GV dùng điện thoại quay đoạn ngắn cả lớp đọc nhạc kết hợp kí hiệu bàn tay, mở lại trên màn hình; HS xem và chỉ ra bạn nào làm kí hiệu tay chưa đúng nốt; GV thao tác thiết bị, HS chỉ xem và nhận xét.\n⚠ (Miền 4: An toàn) Bản đọc nhạc mẫu lấy từ học liệu của bộ sách, không tải từ trang lạ; đoạn quay chỉ dùng xem tại lớp, không đăng lên mạng khi chưa được cha mẹ HS đồng ý; mở loa vừa đủ nghe.","hs":"- HS nghe từng câu đọc nhạc mẫu, nói đúng tên các nốt vừa nghe và đọc lại theo kí hiệu bàn tay.\n- HS xem đoạn quay của lớp, chỉ ra một chỗ làm kí hiệu tay chưa đúng và làm lại cho đúng."}],"status":"checked","source":"KHBD Âm nhạc 1 KNTT (Bút Xanh, theo SGV) — Tiết 27"},
{"lop":1,"mon":"Âm nhạc","tuan":28,"tiet":28,"bai":"Chủ đề 7: Gia đình — Ôn đọc nhạc; Nghe nhạc: Con chim vành khuyên (Hoàng Vân)","yccd":"1. Năng lực âm nhạc\n- Đọc đúng tên nốt, cao độ bài đọc nhạc Hát cùng Đô – Rê – Mi – Pha – Son kết hợp kí hiệu bàn tay và gõ đệm theo phách.\n- Nhớ tên bài hát Con chim vành khuyên và tác giả Hoàng Vân; kể lại được nội dung ngắn gọn (chú chim vành khuyên ngoan ngoãn, lễ phép chào hỏi mọi người).\n- Biết vận động cơ thể phù hợp với tính chất vui tươi, nhí nhảnh của bài nghe nhạc.\n2. Năng lực chung\n- Tự chủ và tự học: chú ý lắng nghe, mạnh dạn nêu cảm nhận.\n- Giao tiếp và hợp tác: cùng bạn đọc nhạc đối đáp, vận động theo nhóm.\n3. Phẩm chất\n- Lễ phép, biết chào hỏi người lớn; yêu thương các con vật.\n4. Tích hợp\n- Năng lực số 3.3 CB1a: Xác định được các quy tắc đơn giản về bản quyền và giấy phép áp dụng cho dữ liệu, thông tin và nội dung số: HS nói được tên bài hát Con chim vành khuyên và tên nhạc sĩ Hoàng Vân.","dodung":"- Giáo viên: đàn Organ (hoặc file nhạc đệm), loa, bản thu bài Con chim vành khuyên, tranh chú chim vành khuyên, bảng kí hiệu bàn tay 5 nốt, thanh phách, thiết bị trình chiếu mở học liệu số.\n- Học sinh: SGK Âm nhạc 1, thanh phách.","hoatdong":[{"ten":"1. Khởi động","gv":"- GV cho HS chơi “Nghe tiếng đoán nốt”: GV đàn một nốt trong 5 nốt đã học, HS làm kí hiệu bàn tay tương ứng; chơi 4–5 lượt.\n- GV nhận xét, dẫn vào phần ôn đọc nhạc.","hs":"- HS nghe đàn, làm kí hiệu bàn tay đúng nốt.\n- HS lắng nghe."},{"ten":"2. Ôn đọc nhạc: Hát cùng Đô – Rê – Mi – Pha – Son","gv":"- GV đàn 5 nốt đi lên, đi xuống, cho HS đọc bằng tên nốt kết hợp kí hiệu tay.\n- GV mở nhạc, cho cả lớp đọc lại bài đọc nhạc 2 lần; sửa chỗ đọc chưa đúng cao độ (thường nhầm Pha – Son).\n- GV hướng dẫn đọc nhạc kết hợp gõ thanh phách theo phách; cho đọc đối đáp: dãy A đọc câu 1, dãy B đọc câu 2.\n- GV mời nhóm 3–4 HS lên đọc kết hợp kí hiệu tay; nhận xét.","hs":"- HS đọc 5 nốt đi lên, đi xuống kết hợp kí hiệu tay.\n- HS đọc cả bài theo nhạc; đọc lại chỗ GV sửa.\n- HS đọc nhạc kết hợp gõ thanh phách; đọc đối đáp theo dãy.\n- HS lên trình bày theo nhóm; nhận xét bạn."},{"ten":"3. Nghe nhạc: Con chim vành khuyên","gv":"- GV cho HS xem tranh chú chim vành khuyên, hỏi: Đây là con gì? Chú chim có gì đáng yêu?\n- GV giới thiệu tên bài hát Con chim vành khuyên, tác giả Hoàng Vân; mở bản thu lần 1, nhắc HS ngồi ngay ngắn lắng nghe.\n- GV hỏi: Chú chim trong bài đã làm gì khi gặp mọi người? Bài hát vui hay buồn? GV chốt: chú chim ngoan ngoãn, gặp ai cũng chào lễ phép.\n- GV mở lần 2, hướng dẫn HS vận động: hai tay vẫy nhẹ như cánh chim, gặp bạn thì cúi đầu chào theo nhịp.","hs":"- HS quan sát tranh, trả lời.\n- HS nghe bài hát lần 1, nói được tên bài và tên tác giả.\n- HS trả lời: chú chim chào hỏi mọi người; bài hát vui.\n- HS nghe lần 2 và vận động theo hướng dẫn, kết hợp động tác chào bạn."},{"ten":"4. Vận dụng","gv":"- GV mời 2–3 HS kể lại ngắn gọn nội dung bài hát: chú chim vành khuyên đã chào những ai.\n- GV liên hệ: Khi gặp thầy cô, người lớn, các em cần làm gì?\n- GV dặn HS về đọc lại bài đọc nhạc kết hợp kí hiệu tay cho người thân xem.","hs":"- HS kể lại theo ý hiểu.\n- HS trả lời: chào hỏi lễ phép.\n- HS ghi nhớ nhiệm vụ."},{"ten":"5. Tích hợp Năng lực số & AI","gv":"- (Miền 1: Khai thác dữ liệu và thông tin — Cơ bản, bậc 1) GV mở bản thu Con chim vành khuyên từ học liệu số, chiếu tranh minh họa cùng tên bài, tên nhạc sĩ Hoàng Vân; GV dừng ở đoạn chú chim chào hỏi, hỏi HS chú chim đang chào ai; mở lại lần 2 cho HS vận động.\n- (Miền 2: Giao tiếp và hợp tác trong môi trường số — Cơ bản, bậc 1) GV gửi bản thu bài hát lên nhóm lớp (Zalo) để cha mẹ mở cho HS nghe lại ở nhà và kể lại nội dung bài; GV thao tác gửi, HS chỉ nghe cùng người lớn.\n⚠ (Miền 4: An toàn) Bản thu lấy từ học liệu bộ sách, không tải từ trang lạ; HS không tự dùng điện thoại, nghe ở nhà cùng người lớn trong thời gian ngắn; mở loa vừa đủ nghe.","hs":"- HS nghe bản thu, nói được tên bài hát và tên nhạc sĩ Hoàng Vân; trả lời chú chim đang chào ai.\n- HS biết về nhà nhờ cha mẹ mở bản GV gửi để nghe lại và kể cho cha mẹ nội dung bài hát."}],"status":"checked","source":"KHBD Âm nhạc 1 KNTT (Bút Xanh, theo SGV) — Tiết 28"},
{"lop":1,"mon":"Âm nhạc","tuan":29,"tiet":29,"bai":"Chủ đề 7: Gia đình — Vận dụng – Sáng tạo: Góc âm nhạc","yccd":"1. Năng lực âm nhạc\n- Biết sắm vai, thể hiện bài hát Cây gia đình với giọng hát và động tác phù hợp từng nhân vật (ông bà, bố mẹ, con).\n- Nghe nhạc và biết hát, vận động theo ý thích phù hợp tính chất bài Con chim vành khuyên.\n- Đọc đúng nốt của mình trong trò chơi Ban nhạc “Những người bạn”; phối hợp với bạn tạo thành nét nhạc ngắn.\n2. Năng lực chung\n- Tự chủ và tự học: tự chọn vai, tự nghĩ động tác.\n- Giao tiếp và hợp tác: phối hợp nhóm khi sắm vai, khi chơi ban nhạc.\n3. Phẩm chất\n- Yêu thương gia đình; tự tin, mạnh dạn.\n4. Tích hợp\n- Năng lực số 3.1 CB1a: Tạo được nội dung số đơn giản với sự hướng dẫn: HS cùng GV tạo được một đoạn ghi hình ban nhạc lớp và xem lại để nhận xét.","dodung":"- Giáo viên: đàn Organ (hoặc file nhạc đệm), loa, bản thu Cây gia đình và Con chim vành khuyên, thẻ vai (ông, bà, bố, mẹ, con), thẻ tên 5 nốt, nhạc cụ gõ, thiết bị trình chiếu mở học liệu số.\n- Học sinh: SGK Âm nhạc 1, thanh phách, trống con.","hoatdong":[{"ten":"1. Khởi động","gv":"- GV mở nhạc, cho HS hát và vận động bài Cây gia đình một lần.\n- GV giới thiệu “Góc âm nhạc” hôm nay có 3 trò chơi: Sắm vai, Nghe nhạc – vận động, Ban nhạc “Những người bạn”.","hs":"- HS hát và vận động theo nhạc.\n- HS lắng nghe, hào hứng."},{"ten":"2. Trò chơi “Sắm vai”","gv":"- GV phát thẻ vai ông, bà, bố, mẹ, con cho từng nhóm 5 HS; gợi ý: ông bà hát chậm rãi, đi lom khom; bố mẹ hát vui, dắt tay con; con hát trong trẻo, nhảy chân sáo.\n- GV mở nhạc bài Cây gia đình, cho từng nhóm sắm vai hát và vận động theo vai của mình.\n- GV nhận xét, khen nhóm thể hiện rõ vai; hỏi: Em thích nhất vai nào? Vì sao?","hs":"- HS nhận thẻ, thảo luận nhanh trong nhóm cách thể hiện vai.\n- HS sắm vai hát và vận động theo nhạc.\n- HS nhận xét nhóm bạn, trả lời câu hỏi."},{"ten":"3. Nghe nhạc, hát và vận động theo ý thích","gv":"- GV mở bài Con chim vành khuyên, gợi ý HS tự nghĩ động tác: vẫy cánh, nghiêng đầu, cúi chào bạn...\n- GV mở lần 2, cho HS hát nhẩm theo đoạn dễ và vận động tự do quanh chỗ ngồi; GV quan sát, khích lệ HS nhút nhát.\n- GV mời vài HS có động tác đẹp lên thể hiện cho cả lớp làm theo.","hs":"- HS nghe, tự nghĩ động tác.\n- HS hát nhẩm và vận động theo ý thích.\n- HS lên thể hiện; cả lớp làm theo bạn."},{"ten":"4. Trò chơi Ban nhạc “Những người bạn”","gv":"- GV mời 5 HS lên, mỗi em đeo thẻ một nốt Đô, Rê, Mi, Pha, Son và đứng theo thứ tự bậc thang.\n- GV làm “nhạc trưởng”: chỉ vào bạn nào, bạn đó đọc nốt của mình bằng âm “la” hoặc tên nốt; cả lớp làm kí hiệu tay theo.\n- GV đổi “nhạc trưởng” là HS; thay ban nhạc khác; nhận xét, khen ngợi.\n- GV dặn HS về chơi ban nhạc với anh chị em ở nhà.","hs":"- 5 HS lên nhận thẻ, xếp hàng đúng thứ tự.\n- HS được chỉ đọc đúng nốt; HS dưới lớp làm kí hiệu tay.\n- HS làm nhạc trưởng, đổi lượt chơi.\n- HS ghi nhớ nhiệm vụ."},{"ten":"5. Tích hợp Năng lực số & AI","gv":"- (Miền 3: Sáng tạo nội dung số — Cơ bản, bậc 1) GV dùng điện thoại quay đoạn ngắn trò chơi Ban nhạc “Những người bạn”, mở lại trên màn hình; HS xem lại, nhận ra bạn đọc đúng nốt và chỗ đọc chưa đúng; GV thao tác thiết bị, HS chỉ xem và nhận xét.\n- (Miền 1: Khai thác dữ liệu và thông tin — Cơ bản, bậc 1) GV mở hai bản thu Cây gia đình và Con chim vành khuyên từ học liệu số, chiếu tranh minh họa từng bài; HS nghe đoạn đầu, nói tên bài và chọn bài mình muốn vận động.\n⚠ (Miền 4: An toàn) Đoạn quay chỉ để xem tại lớp, không đăng lên mạng khi chưa được cha mẹ đồng ý; bản thu lấy từ học liệu bộ sách; HS không tự cầm điện thoại của GV.","hs":"- HS xem lại đoạn quay ban nhạc lớp, nói được bạn nào đọc đúng nốt, chỗ nào cần sửa.\n- HS nghe đoạn đầu bản thu, nói đúng tên bài hát và chọn bài mình thích để vận động."}],"status":"checked","source":"KHBD Âm nhạc 1 KNTT (Bút Xanh, theo SGV) — Tiết 29"},
{"lop":1,"mon":"Âm nhạc","tuan":30,"tiet":30,"bai":"Chủ đề 8: Vui đón hè — Học hát: Ngôi sao lấp lánh (Nhạc nước ngoài, lời Việt: Thanh Vân sưu tầm và biên soạn)","yccd":"1. Năng lực âm nhạc\n- Nhớ tên bài hát Ngôi sao lấp lánh (nhạc nước ngoài, lời Việt do Thanh Vân sưu tầm và biên soạn); hát đúng giai điệu, rõ lời.\n- Bước đầu cảm nhận tính chất nhẹ nhàng, trong sáng của bài hát.\n- Biết hát kết hợp vỗ tay theo phách.\n2. Năng lực chung\n- Tự chủ và tự học: mạnh dạn hát trước lớp, tự tập lại lời ca.\n- Giao tiếp và hợp tác: hát hòa giọng, hát nối tiếp cùng bạn.\n3. Phẩm chất\n- Yêu thiên nhiên, thích khám phá bầu trời đêm; vui vẻ đón mùa hè.\n4. Tích hợp\n- Năng lực số 3.3 CB1a: Xác định được các quy tắc đơn giản về bản quyền và giấy phép áp dụng cho dữ liệu, thông tin và nội dung số: HS nói được tên bài hát và biết đây là bài hát nước ngoài có lời Việt do Thanh Vân sưu tầm, biên soạn.","dodung":"- Giáo viên: đàn Organ (hoặc file nhạc đệm), loa, bản hát mẫu, tranh bầu trời đêm có các ngôi sao, thanh phách, thiết bị trình chiếu/loa mở học liệu số.\n- Học sinh: SGK Âm nhạc 1, thanh phách.","hoatdong":[{"ten":"1. Khởi động","gv":"- GV chiếu tranh bầu trời đêm, hỏi: Ban đêm nhìn lên trời, em thấy gì? Ngôi sao trông như thế nào?\n- GV cho HS chơi “Ngôi sao nhấp nháy”: hai bàn tay xòe ra – nắm lại theo tiếng đàn nhanh – chậm; dẫn vào bài hát.","hs":"- HS quan sát, trả lời: có trăng, có sao; ngôi sao lấp lánh...\n- HS chơi trò chơi theo tiếng đàn."},{"ten":"2. Khám phá — Nghe và học hát","gv":"- GV giới thiệu: Ngôi sao lấp lánh là bài hát nước ngoài quen thuộc với trẻ em nhiều nước, lời Việt do Thanh Vân sưu tầm và biên soạn; mở bản hát mẫu 1–2 lần.\n- GV hỏi: Bài hát nhanh hay chậm? Vui hay buồn? GV chốt: nhẹ nhàng, trong sáng.\n- GV đọc lời ca theo từng câu ngắn (bài chia thành khoảng 6 câu, câu đầu và câu cuối có giai điệu giống nhau), cho HS đọc theo.\n- GV đàn, hát mẫu từng câu, bắt nhịp cho HS hát nối tiếp; lưu ý câu 3 và câu 4 giai điệu giống nhau, nhắc HS hát nhẹ, đúng độ cao.","hs":"- HS lắng nghe, nêu cảm nhận ban đầu.\n- HS trả lời.\n- HS đọc lời ca theo GV.\n- HS tập hát từng câu, hát nối các câu đến hết bài."},{"ten":"3. Luyện tập","gv":"- GV cho HS hát cả bài theo nhạc đệm 2–3 lần; sửa chỗ hát chưa đúng, nhắc hát nhẹ, không gào.\n- GV hướng dẫn hát kết hợp vỗ tay theo phách; hát theo tổ, dãy, nhóm nhỏ.\n- GV cho hát nối tiếp: dãy A hát câu 1–2, dãy B hát câu 3–4, cả lớp hát câu 5–6.","hs":"- HS hát cả bài theo nhạc đệm.\n- HS hát kết hợp vỗ tay theo phách; hát theo tổ, dãy.\n- HS hát nối tiếp theo dãy."},{"ten":"4. Vận dụng","gv":"- GV mời 2–3 nhóm lên hát kết hợp động tác xòe tay lấp lánh trên đầu.\n- GV hỏi: Bài hát tên gì? Lời Việt do ai sưu tầm, biên soạn?\n- GV dặn HS về hát cho gia đình nghe.","hs":"- HS lên biểu diễn; cả lớp cổ vũ.\n- HS trả lời.\n- HS ghi nhớ nhiệm vụ."},{"ten":"5. Tích hợp Năng lực số & AI","gv":"- (Miền 1: Khai thác dữ liệu và thông tin — Cơ bản, bậc 1) GV mở bản hát mẫu Ngôi sao lấp lánh từ học liệu số, chiếu tên bài cùng dòng “Nhạc nước ngoài, lời Việt: Thanh Vân sưu tầm và biên soạn” để HS đọc theo; GV bấm phát từng câu, dừng cho HS hát nối tiếp; câu nào hát chưa đúng thì mở lại câu đó.\n- (Miền 3: Sáng tạo nội dung số — Cơ bản, bậc 1) GV dùng điện thoại ghi âm lớp hát kết hợp vỗ tay theo phách, mở lại qua loa; HS nghe, chỉ ra chỗ hát chưa rõ lời, vỗ tay chưa đều phách; GV thao tác thiết bị, HS chỉ nghe và nhận xét.\n⚠ (Miền 4: An toàn) Bản thu lấy từ học liệu bộ sách hoặc kênh chính thức, không tải bản trên mạng vì nhiều bản khác lời; giới thiệu bài phải nói rõ nguồn nhạc nước ngoài và người biên soạn lời Việt; mở loa vừa đủ nghe.","hs":"- HS nghe từng câu bản hát mẫu, nói được tên bài và người biên soạn lời Việt, hát nối tiếp đúng lời.\n- HS nghe bản ghi âm của lớp, chỉ ra một chỗ hát chưa rõ hoặc vỗ tay chưa đều rồi hát lại."}],"status":"checked","source":"KHBD Âm nhạc 1 KNTT (Bút Xanh, theo SGV) — Tiết 30"},
{"lop":1,"mon":"Âm nhạc","tuan":31,"tiet":31,"bai":"Chủ đề 8: Vui đón hè — Ôn bài hát Ngôi sao lấp lánh; Nhạc cụ: Trai-en-gô","yccd":"1. Năng lực âm nhạc\n- Hát thuộc lời, đúng giai điệu bài Ngôi sao lấp lánh; hát kết hợp vận động nhẹ nhàng.\n- Nhận biết trai-en-gô (nhạc cụ kim loại hình tam giác, có dây treo và dùi gõ); biết cách cầm dây treo, gõ đúng cách để tạo âm thanh ngân vang.\n- Gõ được hình tiết tấu đơn giản (đen – đen – trắng) bằng trai-en-gô; biết gõ đệm theo phách cho bài Ngôi sao lấp lánh.\n2. Năng lực chung\n- Tự chủ và tự học: tự cầm, gõ nhạc cụ đúng cách.\n- Giao tiếp và hợp tác: gõ đệm cùng bạn, chờ đến lượt mình.\n3. Phẩm chất\n- Giữ gìn nhạc cụ, cẩn thận khi sử dụng.\n4. Tích hợp\n- Năng lực số 4.1 CB1a: Biết cách bảo vệ thiết bị số đơn giản khi sử dụng: HS nêu được cách dùng loa, máy tính an toàn trong lớp (không chạm dây điện, không gõ nhạc cụ lên thiết bị).","dodung":"- Giáo viên: đàn Organ (hoặc file nhạc đệm), loa, bản thu Ngôi sao lấp lánh, 3–5 chiếc trai-en-gô, ảnh/video ngắn về trai-en-gô, bảng hình tiết tấu, thiết bị trình chiếu mở học liệu số.\n- Học sinh: SGK Âm nhạc 1, thanh phách, trống con.","hoatdong":[{"ten":"1. Khởi động","gv":"- GV giấu trai-en-gô sau lưng, gõ cho HS nghe và hỏi: Âm thanh này giống tiếng gì? Trong hay đục? Ngân dài hay ngắn?\n- GV mở nhạc, cho cả lớp hát bài Ngôi sao lấp lánh một lần.","hs":"- HS nghe, đoán: giống tiếng chuông; âm trong, ngân dài.\n- HS hát cả bài."},{"ten":"2. Ôn bài hát Ngôi sao lấp lánh","gv":"- GV cho HS hát cả bài theo nhạc đệm, sửa chỗ hát chưa đúng, nhắc hát nhẹ nhàng, rõ lời.\n- GV hướng dẫn hát kết hợp vận động: hai tay xòe trên đầu lắc nhẹ như sao nhấp nháy, nghiêng người theo nhịp; hát theo nhóm, cá nhân.\n- GV nhận xét, khen ngợi.","hs":"- HS hát cả bài theo nhạc đệm.\n- HS hát kết hợp vận động theo nhóm, cá nhân.\n- HS nhận xét bạn."},{"ten":"3. Nhạc cụ: Trai-en-gô","gv":"- GV cho HS xem trai-en-gô, giới thiệu: nhạc cụ bằng kim loại hình tam giác, có một góc hở, có dây treo và dùi gõ; âm thanh trong, ngân vang.\n- GV làm mẫu cách cầm: tay trái cầm dây treo (không nắm vào thân kim loại kẻo tắt tiếng), tay phải cầm dùi gõ vào cạnh đáy; muốn tắt tiếng thì áp bàn tay vào thân.\n- GV gõ mẫu hình tiết tấu đen – đen – trắng, đọc “gõ – gõ – ngân”; cho HS gõ theo bằng trai-en-gô (nhóm được phát) và bằng thanh phách (nhóm còn lại), đổi lượt.\n- GV hướng dẫn gõ đệm theo phách cho bài Ngôi sao lấp lánh: GV hát, HS gõ; sau đó vừa hát vừa gõ; chia nhóm hát, nhóm gõ trai-en-gô, nhóm gõ thanh phách.","hs":"- HS quan sát, nêu hình dáng: hình tam giác, có dây treo, có dùi.\n- HS quan sát cách cầm, tập cầm và gõ thử.\n- HS gõ hình tiết tấu theo GV; đổi lượt dùng trai-en-gô.\n- HS gõ đệm theo phách cho bài hát; thực hiện theo nhóm."},{"ten":"4. Vận dụng","gv":"- GV mời 1–2 nhóm lên biểu diễn: vừa hát vừa gõ đệm bằng trai-en-gô, thanh phách.\n- GV hỏi: Khi cầm trai-en-gô cần chú ý gì?\n- GV dặn HS giữ gìn nhạc cụ, cất đúng chỗ.","hs":"- HS lên biểu diễn.\n- HS trả lời: cầm vào dây treo, gõ nhẹ vào cạnh.\n- HS cất nhạc cụ gọn gàng."},{"ten":"5. Tích hợp Năng lực số & AI","gv":"- (Miền 1: Khai thác dữ liệu và thông tin — Cơ bản, bậc 1) GV chiếu ảnh hoặc đoạn video ngắn từ học liệu số về trai-en-gô trong dàn nhạc, mở âm thanh mẫu; HS nghe và so sánh với tiếng trai-en-gô của lớp; GV chỉ trên màn hình các bộ phận: thân, dây treo, dùi.\n- (Miền 3: Sáng tạo nội dung số — Cơ bản, bậc 1) GV ghi âm nhóm gõ đệm trai-en-gô cho bài hát, mở lại qua loa; HS nghe, nói tiếng gõ đã đều phách chưa, có tiếng nào bị tắt do cầm sai; GV thao tác thiết bị, HS chỉ nghe và nhận xét.\n⚠ (Miền 4: An toàn) GV dặn HS không gõ dùi hay nhạc cụ lên máy tính, loa; không chạm vào dây điện của loa, máy chiếu; video nhạc cụ lấy từ học liệu bộ sách, mở loa vừa đủ nghe.","hs":"- HS xem video, chỉ được thân, dây treo, dùi của trai-en-gô; nói tiếng gõ mẫu giống hay khác tiếng gõ của lớp.\n- HS nghe lại bản ghi âm, nhận xét gõ đều phách chưa; nêu được một điều cần chú ý khi dùng thiết bị trong lớp."}],"status":"checked","source":"KHBD Âm nhạc 1 KNTT (Bút Xanh, theo SGV) — Tiết 31"},
{"lop":1,"mon":"Âm nhạc","tuan":32,"tiet":32,"bai":"Chủ đề 8: Vui đón hè — Ôn tập cuối năm (tiết 1)","yccd":"1. Năng lực âm nhạc\n- Gõ đúng hai mẫu tiết tấu (mẫu 1: đen – đen – trắng; mẫu 2: đen – đen – đen – lặng) bằng trống con, thanh phách, trai-en-gô; biết cầm, gõ đúng cách từng nhạc cụ.\n- Đọc đúng tên nốt, cao độ bài đọc nhạc Hát cùng Đô – Rê – Mi – Pha – Son kết hợp kí hiệu bàn tay; biết đọc to – đọc nhỏ theo hiệu lệnh.\n- Phối hợp gõ 3 nhạc cụ theo nhóm tạo thành “dàn nhạc” nhỏ của lớp.\n2. Năng lực chung\n- Tự chủ và tự học: tự nhớ lại cách cầm, gõ từng nhạc cụ.\n- Giao tiếp và hợp tác: gõ đúng lượt nhóm mình, phối hợp cùng nhóm bạn.\n3. Phẩm chất\n- Chăm chỉ ôn luyện; giữ gìn nhạc cụ.\n4. Tích hợp\n- Năng lực số 1.1 CB1a: Tìm được thông tin đơn giản theo hướng dẫn: HS nghe âm thanh mẫu của 3 nhạc cụ từ học liệu số, nói đúng tên nhạc cụ vừa nghe.","dodung":"- Giáo viên: đàn Organ (hoặc file nhạc đệm), loa, trống con, thanh phách, trai-en-gô, bảng hình tiết tấu mẫu 1 và mẫu 2, bảng kí hiệu bàn tay 5 nốt, thẻ “to”/“nhỏ”, thiết bị trình chiếu mở học liệu số.\n- Học sinh: SGK Âm nhạc 1, thanh phách, trống con.","hoatdong":[{"ten":"1. Khởi động","gv":"- GV cho HS chơi “Nghe tiếng đoán nhạc cụ”: gõ lần lượt trống con, thanh phách, trai-en-gô sau lưng, HS đoán tên.\n- GV giới thiệu tiết ôn tập cuối năm gồm 2 nội dung: gõ tiết tấu với nhạc cụ và ôn đọc nhạc.","hs":"- HS nghe, đoán tên nhạc cụ.\n- HS lắng nghe."},{"ten":"2. Ôn nhạc cụ: Gõ mẫu tiết tấu 1 và mẫu tiết tấu 2","gv":"- GV treo bảng hình tiết tấu mẫu 1 (đen – đen – trắng), vỗ tay mẫu, đọc “vỗ – vỗ – ngân”; cho cả lớp vỗ tay theo rồi gõ bằng thanh phách.\n- GV treo mẫu 2 (đen – đen – đen – lặng), gõ mẫu, đọc “gõ – gõ – gõ – nghỉ” (ngón trỏ đặt lên môi ở phách lặng); cho HS gõ bằng trống con, nhắc cầm dùi đúng, gõ vào mặt trống.\n- GV chia 3 nhóm: trống con gõ mẫu 2, thanh phách gõ mẫu 1, trai-en-gô gõ mẫu 1; gõ lần lượt từng nhóm rồi cùng gõ; nhắc nhóm trai-en-gô cầm dây treo, tắt tiếng ở phách lặng.\n- GV mở nhạc bài Gà gáy hoặc Ngôi sao lấp lánh, cho các nhóm gõ đệm theo phách bằng nhạc cụ của mình.","hs":"- HS vỗ tay, gõ thanh phách theo mẫu 1.\n- HS gõ trống con theo mẫu 2, thực hiện đúng phách lặng.\n- HS gõ theo nhóm, sau đó cả 3 nhóm cùng gõ; đổi nhạc cụ giữa các nhóm.\n- HS gõ đệm theo phách cho bài hát."},{"ten":"3. Ôn đọc nhạc: Hát cùng Đô – Rê – Mi – Pha – Son (đọc to – đọc nhỏ)","gv":"- GV đàn 5 nốt đi lên, đi xuống, cho HS đọc kết hợp kí hiệu bàn tay.\n- GV mở nhạc, cho cả lớp đọc cả bài 1–2 lần; sửa cao độ chỗ chưa đúng.\n- GV giơ thẻ “to” / “nhỏ”: thẻ “to” thì đọc to, thẻ “nhỏ” thì đọc nhỏ; đổi thẻ giữa các câu; sau đó mời HS lên làm người giơ thẻ.\n- GV cho nhóm đọc nhạc kết hợp gõ thanh phách theo phách; nhận xét.","hs":"- HS đọc 5 nốt kết hợp kí hiệu tay.\n- HS đọc cả bài theo nhạc.\n- HS nhìn thẻ đọc to – nhỏ đúng hiệu lệnh; HS lên làm người giơ thẻ.\n- HS đọc nhạc theo nhóm kết hợp gõ đệm."},{"ten":"4. Vận dụng","gv":"- GV tổ chức “Dàn nhạc lớp 1”: nhóm đọc nhạc, nhóm gõ trống con, nhóm gõ thanh phách, nhóm gõ trai-en-gô cùng biểu diễn bài đọc nhạc.\n- GV nhận xét, khen ngợi; dặn HS về ôn các bài hát học kì II để tiết sau ôn tiếp.","hs":"- HS biểu diễn theo phân công.\n- HS lắng nghe, ghi nhớ."},{"ten":"5. Tích hợp Năng lực số & AI","gv":"- (Miền 1: Khai thác dữ liệu và thông tin — Cơ bản, bậc 1) GV mở âm thanh mẫu của trống con, thanh phách, trai-en-gô từ học liệu số, chiếu ảnh 3 nhạc cụ; GV bấm phát từng tiếng, HS nói tên nhạc cụ và chỉ ảnh đúng; GV chiếu bảng hình tiết tấu trên màn hình, dùng con trỏ chỉ từng nốt cho HS gõ theo.\n- (Miền 3: Sáng tạo nội dung số — Cơ bản, bậc 1) GV quay đoạn “Dàn nhạc lớp 1” biểu diễn, mở lại trên màn hình; HS xem, nói nhóm nào gõ đều, nhóm nào chưa đúng lượt; GV thao tác thiết bị, HS chỉ xem và nhận xét.\n⚠ (Miền 4: An toàn) Âm thanh mẫu lấy từ học liệu bộ sách; đoạn quay chỉ xem tại lớp, không đăng lên mạng khi chưa được cha mẹ đồng ý; không gõ nhạc cụ lên thiết bị, mở loa vừa đủ nghe.","hs":"- HS nghe từng tiếng mẫu, nói đúng tên nhạc cụ và chỉ ảnh; nhìn con trỏ trên màn hình gõ đúng mẫu tiết tấu.\n- HS xem lại đoạn quay, nhận xét nhóm gõ đều, nhóm cần sửa."}],"status":"checked","source":"KHBD Âm nhạc 1 KNTT (Bút Xanh, theo SGV) — Tiết 32"},
{"lop":1,"mon":"Âm nhạc","tuan":33,"tiet":33,"bai":"Chủ đề 8: Vui đón hè — Ôn tập cuối năm (tiết 2)","yccd":"1. Năng lực âm nhạc\n- Nhìn tranh minh họa nói đúng tên các bài hát đã học trong năm, nhất là 4 bài học kì II: Xúc xắc xúc xẻ, Gà gáy, Cây gia đình, Ngôi sao lấp lánh.\n- Hát thuộc lời, đúng giai điệu 4 bài hát học kì II với các hình thức đồng ca, tốp ca, song ca, đơn ca kết hợp gõ đệm hoặc vận động.\n- Nêu được tên tác giả hoặc xuất xứ của bài hát khi giới thiệu.\n2. Năng lực chung\n- Tự chủ và tự học: tự chọn bài, tự chọn hình thức trình bày.\n- Giao tiếp và hợp tác: phối hợp trong tốp ca, song ca; biết cổ vũ bạn.\n3. Phẩm chất\n- Tự tin; yêu quê hương, gia đình, thầy cô, bạn bè qua các bài hát.\n4. Tích hợp\n- Năng lực số 3.3 CB1a: Xác định được các quy tắc đơn giản về bản quyền và giấy phép áp dụng cho dữ liệu, thông tin và nội dung số: HS nói được tên bài hát và tên tác giả khi giới thiệu bài trình bày.","dodung":"- Giáo viên: đàn Organ (hoặc file nhạc đệm), loa, nhạc đệm 8 bài hát đã học, bộ tranh minh họa các bài hát, nhạc cụ gõ, thiết bị trình chiếu mở học liệu số.\n- Học sinh: SGK Âm nhạc 1, thanh phách, trống con.","hoatdong":[{"ten":"1. Khởi động","gv":"- GV mở đoạn nhạc dạo ngắn của một bài hát bất kì, HS đoán tên bài; chơi 2–3 lượt.\n- GV giới thiệu nội dung tiết ôn tập: xem tranh kể tên bài hát và ôn các bài hát học kì II.","hs":"- HS nghe, đoán tên bài hát.\n- HS lắng nghe."},{"ten":"2. Xem tranh, kể tên bài hát đã học","gv":"- GV chiếu hoặc treo lần lượt các bức tranh minh họa (rừng hoa, lá cờ Tổ quốc, lớp học, bạn mới, ngày Tết, chú gà trống, cây gia đình, bầu trời sao), hỏi: Tranh gợi nhớ bài hát nào? Ai sáng tác?\n- GV cho HS hát câu đầu của bài vừa nêu; chốt lại 8 bài hát trong năm, nhấn mạnh 4 bài học kì II.\n- GV hỏi: Em thích nhất bài nào? Vì sao?","hs":"- HS quan sát tranh, nói tên bài hát, tên tác giả (ví dụ: Gà gáy – dân ca Cống Khao, lời mới Huy Trân).\n- HS hát câu đầu mỗi bài.\n- HS trả lời theo cảm nhận."},{"ten":"3. Ôn các bài hát học kì II","gv":"- GV mở nhạc đệm, cho cả lớp đồng ca lần lượt Xúc xắc xúc xẻ, Gà gáy, Cây gia đình, Ngôi sao lấp lánh; sửa chỗ hát sai, nhắc tính chất mỗi bài (rộn ràng, vui tươi, tình cảm, nhẹ nhàng).\n- GV chia tổ: mỗi tổ chọn 1 bài, chọn hình thức tốp ca kết hợp gõ đệm thanh phách/trống con hoặc vận động; cho 5 phút tập.\n- GV mời từng tổ trình bày; mời thêm 2–3 cặp song ca và 1–2 HS đơn ca bài mình thích.\n- GV nhận xét từng nhóm: thuộc lời, đúng nhạc, gõ đệm đều, vận động đẹp; khen ngợi.","hs":"- HS đồng ca 4 bài theo nhạc đệm.\n- HS thảo luận trong tổ, chọn bài, hình thức và tập luyện.\n- HS trình bày theo tổ; song ca, đơn ca xung phong.\n- HS nhận xét bạn, cổ vũ."},{"ten":"4. Vận dụng","gv":"- GV hướng dẫn HS chuẩn bị cho tiết đánh giá: mỗi em chọn 1 nội dung yêu thích (hát, đọc nhạc, gõ nhạc cụ), có thể trình bày cá nhân hoặc theo nhóm 2–4 bạn.\n- GV ghi danh sách nhóm và nội dung; dặn HS về tập cùng bạn.","hs":"- HS chọn nội dung, tìm bạn cùng nhóm.\n- HS đăng kí với GV, ghi nhớ."},{"ten":"5. Tích hợp Năng lực số & AI","gv":"- (Miền 1: Khai thác dữ liệu và thông tin — Cơ bản, bậc 1) GV chiếu bộ tranh minh họa các bài hát trên màn hình kèm nhạc dạo mỗi bài từ học liệu số; HS nhìn tranh, nghe nhạc, nói tên bài và tác giả; GV bấm hiện tên bài, tên tác giả để HS đối chiếu.\n- (Miền 2: Giao tiếp và hợp tác trong môi trường số — Cơ bản, bậc 1) GV gửi lên nhóm lớp (Zalo) danh sách nhóm, nội dung đăng kí trình bày cùng nhạc đệm 4 bài để cha mẹ mở cho HS tập ở nhà; GV thao tác gửi, HS chỉ tập cùng người lớn.\n⚠ (Miền 4: An toàn) Nhạc đệm, tranh lấy từ học liệu bộ sách; HS không tự dùng điện thoại, tập ở nhà cùng người lớn trong thời gian ngắn; không chia sẻ thông tin của lớp ra ngoài nhóm.","hs":"- HS nhìn tranh, nghe nhạc dạo, nói đúng tên bài hát và tác giả; đối chiếu với màn hình.\n- HS biết về nhà nhờ cha mẹ mở nhạc đệm GV gửi để tập bài mình đã đăng kí."}],"status":"checked","source":"KHBD Âm nhạc 1 KNTT (Bút Xanh, theo SGV) — Tiết 33"},
{"lop":1,"mon":"Âm nhạc","tuan":34,"tiet":34,"bai":"Chủ đề 8: Vui đón hè — Đánh giá cuối năm (tiết 1)","yccd":"1. Năng lực âm nhạc\n- Trình bày tự tin một nội dung yêu thích đã học (hát, đọc nhạc theo kí hiệu bàn tay, gõ nhạc cụ theo tiết tấu hoặc gõ đệm) theo hình thức cá nhân hoặc nhóm.\n- Hát đúng giai điệu, rõ lời hoặc đọc đúng cao độ, gõ đúng tiết tấu nội dung đã chọn; biết kết hợp gõ đệm hoặc vận động.\n- Biết lắng nghe và nhận xét đơn giản phần trình bày của bạn.\n2. Năng lực chung\n- Tự chủ và tự học: tự chuẩn bị, tự tin trình bày.\n- Giao tiếp và hợp tác: phối hợp nhóm, cổ vũ bạn.\n3. Phẩm chất\n- Trung thực khi tự nhận xét; tôn trọng bạn.\n4. Tích hợp\n- Năng lực số 3.3 CB1a: Xác định được các quy tắc đơn giản về bản quyền và giấy phép áp dụng cho dữ liệu, thông tin và nội dung số: HS giới thiệu được tên bài, tên tác giả trước khi trình bày.","dodung":"- Giáo viên: đàn Organ (hoặc file nhạc đệm), loa, nhạc đệm các bài hát và bài đọc nhạc, nhạc cụ gõ (trống con, thanh phách, trai-en-gô), danh sách nhóm đăng kí, phiếu ghi nhận xét theo 3 mức Biết – Hiểu – Vận dụng, thiết bị trình chiếu mở học liệu số.\n- Học sinh: SGK Âm nhạc 1, thanh phách, nội dung đã chuẩn bị.","hoatdong":[{"ten":"1. Khởi động","gv":"- GV mở nhạc, cho cả lớp hát và vận động bài Ngôi sao lấp lánh để tạo không khí vui vẻ.\n- GV nêu cách đánh giá: mỗi nhóm/cá nhân trình bày nội dung đã đăng kí; GV nhận xét theo 3 mức Biết – Hiểu – Vận dụng, không cho điểm; các bạn dưới lớp lắng nghe, cổ vũ.","hs":"- HS hát và vận động.\n- HS lắng nghe, nắm cách thực hiện."},{"ten":"2. Ôn luyện nhanh trước khi trình bày","gv":"- GV cho các nhóm 3–4 phút tập lại nội dung đã chọn; GV đi từng nhóm hỗ trợ (bắt nhịp, nhắc kí hiệu tay, cách cầm nhạc cụ).\n- GV sắp xếp thứ tự trình bày: nhóm 1, nhóm 2 và khoảng một nửa lớp trình bày ở tiết này, số còn lại trình bày tiết sau.","hs":"- HS tập lại theo nhóm.\n- HS biết thứ tự trình bày của mình."},{"ten":"3. Trình bày và đánh giá (nhóm 1, nhóm 2)","gv":"- GV mời lần lượt từng nhóm/cá nhân lên: giới thiệu tên bài, tác giả (GV hỏi gợi ý), rồi trình bày theo nhạc đệm; GV đệm đàn hoặc mở nhạc, bắt nhịp.\n- GV quan sát, ghi nhận vào phiếu: hát/đọc đúng chưa, gõ đệm hay vận động có phù hợp không, thái độ tự tin.\n- Sau mỗi phần trình bày, GV hỏi cả lớp: Bạn hát đúng nhạc chưa? Bạn gõ đệm đều chưa? Rồi nhận xét ngắn theo mức: Biết (nhớ tên bài, hát/đọc được), Hiểu (hát đúng nhạc, rõ lời, đúng tiết tấu), Vận dụng (kết hợp gõ đệm/vận động, biểu diễn tự tin).\n- GV khen ngợi, động viên nhóm còn rụt rè; không so sánh HS với nhau.","hs":"- Nhóm/cá nhân lên giới thiệu và trình bày.\n- HS dưới lớp lắng nghe, giữ trật tự.\n- HS nhận xét bạn theo gợi ý; nhóm trình bày tự nói mình làm tốt gì, chưa tốt gì.\n- HS vỗ tay cổ vũ."},{"ten":"4. Vận dụng","gv":"- GV cho cả lớp cùng hát lại bài được nhiều nhóm chọn nhất, kết hợp gõ đệm.\n- GV dặn các nhóm còn lại chuẩn bị trình bày ở tiết sau.","hs":"- HS hát tập thể kết hợp gõ đệm.\n- HS ghi nhớ."},{"ten":"5. Tích hợp Năng lực số & AI","gv":"- (Miền 3: Sáng tạo nội dung số — Cơ bản, bậc 1) GV dùng điện thoại quay phần trình bày của từng nhóm, mở lại ngay trên màn hình cho nhóm xem; HS tự nhận xét: hát rõ lời chưa, gõ đệm đều chưa, đứng biểu diễn có tự tin không; GV thao tác thiết bị, HS chỉ xem và nói.\n- (Miền 1: Khai thác dữ liệu và thông tin — Cơ bản, bậc 1) GV mở nhạc đệm từng bài từ học liệu số, chiếu tên bài, tên tác giả để HS đọc khi giới thiệu phần trình bày của mình.\n⚠ (Miền 4: An toàn) Đoạn quay chỉ dùng cho HS tự nhận xét tại lớp, lưu trên thiết bị của GV, không đăng lên mạng khi chưa được cha mẹ đồng ý; nhạc đệm lấy từ học liệu bộ sách; mở loa vừa đủ nghe.","hs":"- HS xem lại phần trình bày của nhóm mình trên màn hình, tự nói được một điều làm tốt và một điều cần sửa.\n- HS nhìn màn hình đọc đúng tên bài, tên tác giả khi giới thiệu."}],"status":"checked","source":"KHBD Âm nhạc 1 KNTT (Bút Xanh, theo SGV) — Tiết 34"},
{"lop":1,"mon":"Âm nhạc","tuan":35,"tiet":35,"bai":"Chủ đề 8: Vui đón hè — Đánh giá cuối năm (tiết 2)","yccd":"1. Năng lực âm nhạc\n- Trình bày tự tin nội dung yêu thích đã chọn (hát, đọc nhạc, gõ nhạc cụ) theo hình thức cá nhân hoặc nhóm; hát đúng giai điệu, rõ lời hoặc đọc đúng cao độ, gõ đúng tiết tấu.\n- Tự đánh giá được phần trình bày của mình theo gợi ý đơn giản; biết nhận xét bạn.\n- Nhớ tên các bài hát, bài đọc nhạc, nhạc cụ đã học trong năm.\n2. Năng lực chung\n- Tự chủ và tự học: tự tin trình bày, tự nhận xét trung thực.\n- Giao tiếp và hợp tác: phối hợp nhóm, cổ vũ và tôn trọng bạn.\n3. Phẩm chất\n- Trung thực; yêu thích âm nhạc, tự hào về sự tiến bộ của bản thân sau một năm học.\n4. Tích hợp\n- Năng lực số 2.1 CB1a: Biết một số cách giao tiếp đơn giản qua kênh số với sự hỗ trợ: HS biết cùng cha mẹ xem lại video biểu diễn của lớp do GV gửi qua nhóm lớp và kể lại bài mình đã trình bày.","dodung":"- Giáo viên: đàn Organ (hoặc file nhạc đệm), loa, nhạc đệm các bài hát và bài đọc nhạc, nhạc cụ gõ (trống con, thanh phách, trai-en-gô), phiếu ghi nhận xét 3 mức, thẻ mặt cười để HS tự đánh giá, thiết bị trình chiếu mở học liệu số.\n- Học sinh: SGK Âm nhạc 1, thanh phách, nội dung đã chuẩn bị.","hoatdong":[{"ten":"1. Khởi động","gv":"- GV cho HS chơi Ban nhạc “Những người bạn”: GV làm kí hiệu bàn tay, cả lớp đọc nốt Đô – Rê – Mi – Pha – Son theo tay GV.\n- GV nhắc lại cách đánh giá theo 3 mức Biết – Hiểu – Vận dụng, không cho điểm; nêu các nhóm trình bày hôm nay.","hs":"- HS đọc nốt theo tay GV.\n- HS lắng nghe."},{"ten":"2. Trình bày và đánh giá (các nhóm còn lại)","gv":"- GV mời lần lượt các nhóm/cá nhân còn lại lên giới thiệu tên bài, tác giả và trình bày; GV đệm đàn hoặc mở nhạc, bắt nhịp; hỗ trợ HS quên lời bằng cách hát nhẩm cùng.\n- GV quan sát, ghi phiếu; sau mỗi phần mời 1–2 HS nhận xét bạn, rồi GV nhận xét theo mức Biết – Hiểu – Vận dụng, nêu rõ điểm đáng khen.\n- GV mời HS đã trình bày ở tiết trước nhưng muốn thể hiện lại lên trình bày thêm (nếu còn thời gian).","hs":"- Nhóm/cá nhân lên giới thiệu và trình bày.\n- HS nhận xét bạn; nhóm trình bày tự nhận xét.\n- HS xung phong trình bày lại."},{"ten":"3. Hướng dẫn HS tự đánh giá","gv":"- GV chiếu hoặc đọc 3 câu hỏi tự đánh giá, HS giơ thẻ mặt cười nếu làm được: Em nhớ tên bài mình trình bày không? Em hát/đọc đúng nhạc chưa? Em có gõ đệm hoặc vận động cùng bài không?\n- GV hỏi thêm: Trong năm em thích nhất bài hát nào, nhạc cụ nào? Cho vài HS chia sẻ.\n- GV chốt: mỗi em đều tiến bộ; khen những HS mạnh dạn hơn so với đầu năm.","hs":"- HS tự đánh giá bằng cách giơ thẻ theo từng câu hỏi.\n- HS chia sẻ bài hát, nhạc cụ yêu thích.\n- HS lắng nghe."},{"ten":"4. Tổng kết năm học","gv":"- GV cùng HS nhắc lại những gì đã học: 8 bài hát, các bài đọc nhạc với 5 nốt Đô – Rê – Mi – Pha – Son, 3 nhạc cụ gõ (trống con, thanh phách, trai-en-gô), các bài nghe nhạc và câu chuyện âm nhạc.\n- GV khen ngợi cả lớp, tuyên dương nhóm/cá nhân tiêu biểu; dặn HS nghỉ hè hát cho gia đình nghe, tập kí hiệu bàn tay, giữ gìn nhạc cụ.\n- GV cho cả lớp cùng hát bài Ngôi sao lấp lánh kết hợp gõ đệm và vận động để kết thúc năm học.","hs":"- HS kể tên bài hát, nhạc cụ, nốt nhạc đã học.\n- HS lắng nghe, vỗ tay chúc mừng bạn.\n- HS hát, gõ đệm, vận động tập thể."},{"ten":"5. Tích hợp Năng lực số & AI","gv":"- (Miền 3: Sáng tạo nội dung số — Cơ bản, bậc 1) GV quay phần trình bày của các nhóm, ghép nối với đoạn quay tiết trước thành video “Buổi biểu diễn cuối năm của lớp”, mở lại trên màn hình cho cả lớp xem; HS xem và nói mình đã trình bày bài gì; GV thao tác thiết bị, HS chỉ xem và nói.\n- (Miền 2: Giao tiếp và hợp tác trong môi trường số — Cơ bản, bậc 1) GV gửi video lên nhóm lớp (Zalo) sau khi được cha mẹ đồng ý để HS xem lại cùng gia đình và kể cho cha mẹ nghe về bài mình đã trình bày; HS chỉ xem cùng người lớn, không tự dùng điện thoại.\n⚠ (Miền 4: An toàn) Video lưu trên thiết bị của GV; chỉ chia sẻ trong nhóm lớp khi cha mẹ đồng ý, không đăng công khai; HS không tự sử dụng điện thoại; thời gian xem ngắn, mở loa vừa đủ nghe.","hs":"- HS xem video “Buổi biểu diễn cuối năm của lớp”, nói được mình trình bày bài gì, cùng nhóm nào.\n- HS biết về nhà xem lại video cùng cha mẹ và kể lại bài mình đã trình bày."}],"status":"checked","source":"KHBD Âm nhạc 1 KNTT (Bút Xanh, theo SGV) — Tiết 35"}
];
